function createAdminUserDetailView(user) {
  if (!user) {
    return createAdminEmptyState(
      "Client not found",
      "Go back to the clients table and open another account.",
    );
  }

  const draftFeatureIds = getAdminUserDraftFeatureIds(user.email, user.assignedFeatureIds);
  const hasChanges = !featureIdListsMatch(draftFeatureIds, user.assignedFeatureIds);
  const isSaving = Boolean(state.adminSaveBusyByEmail[user.email]);
  const isDeleting = Boolean(state.adminDeleteBusyByEmail[user.email]);
  const isStatusSaving = Boolean(state.adminStatusBusyByEmail[user.email]);
  const deleteDisabledReason = getAdminUserDeleteDisabledReason(user);
  const toolInputsDisabled = isDeleting || isStatusSaving;
  const featureLookup = new Map(state.adminFeatures.map((feature) => [feature.featureId, feature]));
  const assignedFeatures = draftFeatureIds.map((featureId) => (
    featureLookup.get(featureId) || {
      featureId,
      name: featureId,
      description: "",
      channel: "",
      mode: "",
    }
  ));
  const filteredFeatures = getFilteredAdminFeatures();
  const showToolResults = state.adminFeaturePickerOpen;

  const wrapper = document.createElement("div");
  wrapper.className = "admin-users-view admin-users-detail-view";

  const strip = document.createElement("div");
  strip.className = "admin-detail-strip";
  const roleBadge = createAdminStateBadge(user.isAdmin ? "Admin" : "Client");

  const clientTypeBadge = createAdminStateBadge(
    getAdminClientTypeLabel(user.clientType),
    getAdminClientTypeClass(user.clientType),
  );

  const activeBadge = createAdminStateBadge(
    isStatusSaving ? "Saving status" : user.isActive ? "Active" : "Inactive",
    user.isActive ? "is-active-client" : "is-inactive-client",
  );

  const toolsBadge = document.createElement("span");
  toolsBadge.className = "feature-status";
  toolsBadge.textContent = `${draftFeatureIds.length} visible tool${draftFeatureIds.length === 1 ? "" : "s"}`;

  strip.append(roleBadge, clientTypeBadge, activeBadge, toolsBadge);

  const grid = document.createElement("div");
  grid.className = "admin-detail-grid";

  const infoPanel = document.createElement("section");
  infoPanel.className = "admin-detail-panel";
  const infoTitle = document.createElement("h4");
  infoTitle.textContent = "Account";
  const infoRows = document.createElement("div");
  infoRows.className = "detail-stack";
  infoRows.append(
    createAdminDetailRow("Client type", getAdminClientTypeLabel(user.clientType)),
    createAdminDetailRow("Login", user.isActive ? "Active" : "Inactive"),
    createAdminDetailRow("Registered", formatAdminDateTime(user.registeredAt) || "Unknown"),
    createAdminDetailRow("Last login", user.lastLoginAt ? formatAdminDateTime(user.lastLoginAt) : "No login yet"),
    createAdminDetailRow("Usage events", String(Number.isFinite(user.usageCount) ? user.usageCount : 0)),
  );

  const infoActions = document.createElement("div");
  infoActions.className = "admin-detail-panel-actions";

  const statusControl = createAdminActiveSwitch(user, {
    disabled: isSaving || isDeleting,
  });
  const clientTypeControl = createAdminClientTypeSelect(user, {
    disabled: isSaving || isDeleting || isStatusSaving,
  });
  infoActions.append(clientTypeControl);
  infoActions.append(statusControl);

  const editButton = document.createElement("button");
  editButton.type = "button";
  editButton.className = "ghost-button small";
  editButton.dataset.adminOpenEditUser = user.email;
  editButton.disabled = isSaving || isDeleting || isStatusSaving;
  editButton.textContent = "Edit client";
  infoActions.append(editButton);

  const deleteButton = document.createElement("button");
  deleteButton.type = "button";
  deleteButton.className = "ghost-button danger small";
  deleteButton.dataset.adminDeleteUser = user.email;
  deleteButton.disabled = isSaving || isDeleting || isStatusSaving || Boolean(deleteDisabledReason);
  deleteButton.textContent = isDeleting ? "Deleting..." : "Delete client";
  infoActions.append(deleteButton);

  infoPanel.append(infoTitle, infoRows, infoActions);
  if (deleteDisabledReason) {
    const deleteNote = document.createElement("p");
    deleteNote.className = "admin-danger-note is-warn";
    deleteNote.textContent = deleteDisabledReason;
    infoPanel.append(deleteNote);
  }

  const accessPanel = document.createElement("section");
  accessPanel.className = "admin-detail-panel admin-detail-access-panel";

  const accessTitle = document.createElement("h4");
  accessTitle.textContent = "Visible tools";

  const availableFeatures = filteredFeatures.filter((feature) => !draftFeatureIds.includes(feature.featureId));

  const picker = document.createElement("div");
  picker.className = "admin-tool-picker";
  picker.dataset.adminFeaturePicker = "true";

  const searchField = document.createElement("label");
  searchField.className = "field admin-tool-search-field";

  const searchLabel = document.createElement("span");
  searchLabel.textContent = "Search tools";

  const searchInput = document.createElement("input");
  searchInput.type = "text";
  searchInput.placeholder = "Click to browse all tools or type to filter";
  searchInput.value = state.adminFeatureSearch;
  searchInput.autocomplete = "off";
  searchInput.disabled = toolInputsDisabled;
  searchInput.dataset.adminFeatureSearchInput = "true";
  searchInput.setAttribute("aria-expanded", String(showToolResults));

  searchField.append(searchLabel, searchInput);

  const results = document.createElement("div");
  results.className = `admin-tool-results${showToolResults ? "" : " is-hidden"}`;

  if (!state.adminFeatures.length) {
    const empty = document.createElement("p");
    empty.className = "admin-empty-copy";
    empty.textContent = "No active tools are available to assign.";
    results.append(empty);
  } else if (!availableFeatures.length && !state.adminFeatureSearch) {
    const empty = document.createElement("p");
    empty.className = "admin-empty-copy";
    empty.textContent = "All tools are already assigned.";
    results.append(empty);
  } else if (!availableFeatures.length) {
    const empty = document.createElement("p");
    empty.className = "admin-empty-copy";
    empty.textContent = "No tools match that search.";
    results.append(empty);
  } else {
    results.append(
      ...availableFeatures.map((feature) => createAdminFeatureSearchResult(feature, {
        disabled: toolInputsDisabled,
        userEmail: user.email,
      })),
    );
  }

  picker.append(searchField, results);

  const assignedShell = document.createElement("div");
  assignedShell.className = "admin-assigned-tools-shell";

  const assignedHead = document.createElement("div");
  assignedHead.className = "admin-assigned-tools-head";

  const assignedTitle = document.createElement("h5");
  assignedTitle.textContent = "Assigned tools";

  const assignedCount = document.createElement("span");
  assignedCount.className = "status-pill";
  assignedCount.textContent = `${assignedFeatures.length} selected`;

  assignedHead.append(assignedTitle, assignedCount);

  const assignedList = document.createElement("div");
  assignedList.className = "admin-assigned-tools";
  if (!assignedFeatures.length) {
    const empty = document.createElement("p");
    empty.className = "admin-tool-badge-empty";
    empty.textContent = "No tools assigned yet.";
    assignedList.append(empty);
  } else {
    assignedList.append(
      ...assignedFeatures.map((feature) => createAdminAssignedFeatureBadge(feature, {
        userEmail: user.email,
        disabled: toolInputsDisabled,
      })),
    );
  }

  assignedShell.append(assignedHead, assignedList);

  const actions = document.createElement("div");
  actions.className = "card-actions admin-user-actions";

  const summary = document.createElement("span");
  summary.className = "admin-user-summary";
  if (isDeleting) {
    summary.textContent = "Deleting user…";
  } else if (isSaving) {
    summary.textContent = "Saving changes…";
  } else if (hasChanges) {
    summary.textContent = "Changes not saved";
  } else {
    summary.textContent = "All access changes saved";
  }

  actions.append(summary);
  accessPanel.append(accessTitle, picker, assignedShell, actions);

  grid.append(infoPanel, accessPanel);
  wrapper.append(strip, grid);
  return wrapper;
}

function renderAdminUsersPane() {
  const adminVisible = canManageClients();

  if (
    !elements.adminUsersPane
    || !elements.adminUsersShell
    || !elements.adminUsersContent
  ) {
    return;
  }

  if (!adminVisible) {
    elements.adminUsersShell.classList.remove("is-hidden");
    elements.adminUsersShell.classList.remove("is-add-view");
    elements.adminUsersShell.classList.remove("is-detail-view");
    return;
  }

  if (elements.adminUsersError) {
    syncAdminUsersError();
  }
  if (
    (state.adminView === "detail" || state.adminView === "edit")
    && !state.adminUsersLoading
    && !getAdminSelectedUser()
  ) {
    state.adminView = "list";
    state.adminSelectedUserEmail = "";
  }

  if (elements.adminOpenAddUserButton) {
    elements.adminOpenAddUserButton.classList.toggle("is-hidden", state.adminView !== "list");
    elements.adminOpenAddUserButton.disabled = false;
  }

  if (state.adminView === "add") {
    elements.adminUsersShell.classList.add("is-add-view");
    elements.adminUsersShell.classList.remove("is-detail-view");
    if (elements.adminUsersError) {
      elements.adminUsersError.classList.add("is-hidden");
    }
    elements.adminUsersContent.replaceChildren(createAdminAddUserView());
    return;
  }

  if (state.adminView === "edit") {
    elements.adminUsersShell.classList.add("is-add-view");
    elements.adminUsersShell.classList.remove("is-detail-view");
    if (elements.adminUsersError) {
      elements.adminUsersError.classList.add("is-hidden");
    }
    elements.adminUsersContent.replaceChildren(createAdminEditUserView(getAdminSelectedUser()));
    return;
  }

  elements.adminUsersShell.classList.remove("is-add-view");

  if (state.adminView === "detail") {
    elements.adminUsersShell.classList.add("is-detail-view");
    elements.adminUsersContent.replaceChildren(createAdminUserDetailView(getAdminSelectedUser()));
    return;
  }

  elements.adminUsersShell.classList.remove("is-detail-view");
  elements.adminUsersContent.replaceChildren(createAdminUsersListView());
}

async function refreshAdminUsers(options = {}) {
  const shouldRender = options.render !== false;
  if (!canManageClients()) {
    return null;
  }

  if (state.adminUsersLoading) {
    if (shouldRender) {
      state.adminUsersNeedsRender = true;
    }
    return null;
  }

  state.adminUsersLoading = true;
  state.adminUsersNeedsRender = shouldRender;
  state.adminUsersError = "";
  if (shouldRender && document.body.dataset.view === "app") {
    renderApp();
  }

  try {
    const previousUsersByEmail = new Map(state.adminUsers.map((user) => [user.email, user]));
    const previousDrafts = state.adminUserDrafts;
    const response = await apiRequest("/api/admin/users", {
      timeoutMs: options.timeoutMs || 15000,
    });

    state.adminFeatures = (Array.isArray(response.features) ? response.features : [])
      .map((feature) => normalizeAdminFeatureRecord(feature))
      .filter((feature) => feature.featureId)
      .sort((left, right) => {
        const leftSort = Number.isFinite(left.sortOrder) ? left.sortOrder : 100;
        const rightSort = Number.isFinite(right.sortOrder) ? right.sortOrder : 100;
        if (leftSort !== rightSort) {
          return leftSort - rightSort;
        }
        return left.name.localeCompare(right.name);
      });
    state.adminUsers = sortAdminUsers((Array.isArray(response.users) ? response.users : [])
      .map((user) => normalizeAdminUserRecord(user))
      .filter((user) => user.email));
    state.adminUserDrafts = buildAdminUserDrafts(state.adminUsers, previousUsersByEmail, previousDrafts);
    if (state.adminView === "detail" && !state.adminUsers.some((user) => user.email === state.adminSelectedUserEmail)) {
      state.adminView = "list";
      state.adminSelectedUserEmail = "";
    }

    if (authSession) {
      authSession = normalizeStoredSession({
        ...authSession,
        isAdmin: Boolean(response.currentUser?.isAdmin),
      });
      persistJson(AUTH_SESSION_KEY, authSession);
    }
    state.settingsMode = normalizeSettingsMode(state.settingsMode);
    return response;
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t load clients right now.");
    if (Number(error?.status || 0) === 403 && authSession) {
      authSession = normalizeStoredSession({
        ...authSession,
        isAdmin: false,
      });
      persistJson(AUTH_SESSION_KEY, authSession);
      state.settingsMode = "account";
    }
    return null;
  } finally {
    state.adminUsersLoading = false;
    if (document.body.dataset.view === "app" && state.adminUsersNeedsRender) {
      state.adminUsersNeedsRender = false;
      renderApp();
    }
  }
}

async function refreshOpportunities(options = {}) {
  const shouldRender = options.render !== false;
  if (!canReviewOpportunities()) {
    state.opportunities = [];
    state.opportunitiesError = "";
    state.opportunitiesLoading = false;
    return null;
  }

  if (state.opportunitiesLoading) {
    return null;
  }

  state.opportunitiesLoading = true;
  state.opportunitiesError = "";
  if (shouldRender && document.body.dataset.view === "app") {
    renderApp({ preserveStatus: true });
  }

  try {
    const response = await apiRequest("/api/admin/opportunities?limit=200", {
      timeoutMs: options.timeoutMs || 15000,
    });
    state.opportunities = sortOpportunitiesByUrgency(
      (Array.isArray(response.opportunities) ? response.opportunities : [])
        .map((opportunity) => normalizeOpportunityRecord(opportunity))
        .filter((opportunity) => opportunity.id > 0),
    );
    state.opportunitiesLoadedAt = Date.now();
    return response;
  } catch (error) {
    state.opportunitiesError = formatApiErrorMessage(error, "We couldn’t load opportunities right now.");
    if (Number(error?.status || 0) === 403 && state.activeTab === "opportunities") {
      state.activeTab = "features";
      state.lastPrimaryTab = "features";
      persistLastPrimaryTab();
      setHashForTab("features");
    }
    return null;
  } finally {
    state.opportunitiesLoading = false;
    if (shouldRender && document.body.dataset.view === "app") {
      renderApp({ preserveStatus: true });
    }
  }
}

async function addAdminUser() {
  if (!canManageClients() || state.adminAddUserBusy) {
    return;
  }

  const email = normalizeEmail(state.adminNewUserEmail);
  const displayName = normalizeText(state.adminNewUserDisplayName);

  if (!validateEmail(email)) {
    state.adminUsersError = "Enter a valid email address before adding the client.";
    renderApp();
    return;
  }

  state.adminAddUserBusy = true;
  state.adminUsersError = "";
  renderApp();

  let didSucceed = false;
  try {
    const response = await apiRequest("/api/admin/users", {
      method: "POST",
      body: {
        email,
        displayName,
      },
    });

    state.adminNewUserEmail = "";
    state.adminNewUserDisplayName = "";
    const createdUser = upsertAdminUserState(response.user || {
      email,
      displayName,
      assignedFeatureIds: [],
    });

    state.adminView = "detail";
    state.adminSelectedUserEmail = createdUser?.email || email;
    didSucceed = true;
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t add that user right now.");
  } finally {
    state.adminAddUserBusy = false;
    renderApp();
    if (didSucceed) {
      setStatus("Client added");
    }
  }
}

async function saveAdminUserDetails() {
  const user = getAdminSelectedUser();
  if (!canManageClients() || !user || state.adminEditUserBusy) {
    return;
  }

  const currentEmail = normalizeEmail(user.email);
  const nextEmail = normalizeEmail(state.adminEditUserEmail);
  const nextDisplayName = normalizeText(state.adminEditUserDisplayName);

  if (!validateEmail(nextEmail)) {
    state.adminUsersError = "Enter a valid email address before saving.";
    renderApp();
    return;
  }

  state.adminEditUserBusy = true;
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(currentEmail)}`, {
      method: "POST",
      body: {
        email: nextEmail,
        displayName: nextDisplayName,
      },
    });

    updatedUser = replaceAdminUserState(currentEmail, response.user || {
      ...user,
      email: nextEmail,
      displayName: nextDisplayName,
    });
    state.adminSelectedUserEmail = updatedUser?.email || nextEmail;
    state.adminView = "detail";
    state.adminEditUserEmail = "";
    state.adminEditUserDisplayName = "";
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that user right now.");
  } finally {
    state.adminEditUserBusy = false;
    renderApp();
    if (updatedUser) {
      setStatus("Client updated");
    }
  }
}

async function saveAdminUserStatus(email, isActive) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminStatusBusyByEmail[normalizedEmail]) {
    return;
  }

  const disabledReason = getAdminUserActiveDisabledReason(user, Boolean(isActive));
  if (disabledReason) {
    openAuthAlert("Client status unavailable", disabledReason, {
      eyebrow: "Client status",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
    return;
  }

  state.adminStatusBusyByEmail = {
    ...state.adminStatusBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}/status`, {
      method: "POST",
      body: {
        isActive: Boolean(isActive),
      },
    });

    updatedUser = upsertAdminUserState(response.user || {
      ...user,
      isActive: Boolean(isActive),
    });
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that client right now.");
    openAuthAlert("Couldn’t update client", state.adminUsersError, {
      eyebrow: "Client status",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminStatusBusyByEmail;
    state.adminStatusBusyByEmail = nextBusy;
    renderApp();
    if (updatedUser) {
      setStatus(updatedUser.isActive ? "Client activated" : "Client disabled");
    }
  }
}

async function saveAdminUserClientType(email, clientType) {
  const normalizedEmail = normalizeEmail(email);
  const normalizedClientType = normalizeAdminClientType(clientType);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || !normalizedClientType || state.adminTypeBusyByEmail[normalizedEmail]) {
    return;
  }

  const previousClientType = normalizeAdminClientType(user.clientType) || deriveAdminClientType(user.paymentStatus);
  if (previousClientType === normalizedClientType) {
    return;
  }

  state.adminTypeBusyByEmail = {
    ...state.adminTypeBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsers = state.adminUsers.map((entry) => (
    entry.email === normalizedEmail
      ? { ...entry, clientType: normalizedClientType }
      : entry
  ));
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}/client-type`, {
      method: "POST",
      body: {
        clientType: normalizedClientType,
      },
    });

    updatedUser = upsertAdminUserState(response.user || {
      ...user,
      clientType: normalizedClientType,
    });
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsers = state.adminUsers.map((entry) => (
      entry.email === normalizedEmail
        ? { ...entry, clientType: previousClientType }
        : entry
    ));
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that client type right now.");
    openAuthAlert("Couldn’t update client type", state.adminUsersError, {
      eyebrow: "Client type",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminTypeBusyByEmail;
    state.adminTypeBusyByEmail = nextBusy;
    renderApp();
    if (updatedUser) {
      setStatus(`Client type set to ${getAdminClientTypeLabel(updatedUser.clientType)}`);
    }
  }
}

async function saveAdminUserFeatures(email) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminSaveBusyByEmail[normalizedEmail]) {
    return;
  }

  const requestedFeatureIds = getAdminUserDraftFeatureIds(normalizedEmail, user.assignedFeatureIds);
  state.adminSaveBusyByEmail = {
    ...state.adminSaveBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsersError = "";
  renderApp();

  let didSucceed = false;
  try {
    await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}/features`, {
      method: "POST",
      body: {
        assignedFeatureIds: requestedFeatureIds,
      },
    });

    state.adminUsers = state.adminUsers.map((entry) => (
      entry.email === normalizedEmail
        ? {
          ...entry,
          assignedFeatureIds: [...requestedFeatureIds],
        }
        : entry
    ));

    if (normalizedEmail === activeEmail) {
      await refreshFeatureActivationStates({ render: false });
      try {
        await refreshWhatsAppConnection({ render: false });
      } catch {
        // Keep the user access update even if the follow-up refresh fails.
      }
    }

    await refreshAdminUsers({ render: false });
    didSucceed = true;
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t save tool access right now.");
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminSaveBusyByEmail;
    state.adminSaveBusyByEmail = nextBusy;
    const latestUser = state.adminUsers.find((entry) => entry.email === normalizedEmail) || null;
    const shouldRetry = didSucceed
      && Boolean(latestUser)
      && (
        Boolean(state.adminSaveQueuedByEmail[normalizedEmail])
        || !featureIdListsMatch(
          getAdminUserDraftFeatureIds(normalizedEmail, latestUser.assignedFeatureIds),
          latestUser.assignedFeatureIds,
        )
      );
    setAdminUserSaveQueued(normalizedEmail, false);
    renderApp();
    if (didSucceed) {
      setStatus("Client access saved");
    }
    if (shouldRetry && !state.adminDeleteBusyByEmail[normalizedEmail]) {
      void saveAdminUserFeatures(normalizedEmail);
    }
  }
}

function deleteAdminUser(email) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminDeleteBusyByEmail[normalizedEmail]) {
    return;
  }

  const disabledReason = getAdminUserDeleteDisabledReason(user);
  if (disabledReason) {
    openAuthAlert("Delete client unavailable", disabledReason, {
      eyebrow: "Delete client",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
    return;
  }

  const label = user.displayName || deriveDisplayName(user.email);
  openAuthAlert(
    "Are you sure?",
    `Delete ${label} (${normalizedEmail})? This removes their portal access, assigned tools, billing history, WhatsApp setup, and saved messages.`,
    {
      eyebrow: "Delete client",
      buttonLabel: "Delete client",
      secondaryButtonLabel: "Cancel",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
      focusTarget: "secondary",
      onPrimary: () => {
        void confirmAdminUserDelete(normalizedEmail);
      },
    },
  );
}

async function confirmAdminUserDelete(email) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminDeleteBusyByEmail[normalizedEmail]) {
    return;
  }

  state.adminDeleteBusyByEmail = {
    ...state.adminDeleteBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsersError = "";
  renderApp();

  let didSucceed = false;
  try {
    await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}`, {
      method: "DELETE",
    });

    persistJson(getClientKey(normalizedEmail), null);
    removeAdminUserState(normalizedEmail);
    state.adminFeatureSearch = "";
    state.adminFeaturePickerOpen = false;
    didSucceed = true;
    void refreshAdminUsers({ render: false });
  } catch (error) {
    openAuthAlert(
      "Couldn’t delete client",
      formatApiErrorMessage(error, "We couldn’t delete that client right now."),
      {
        eyebrow: "Delete client",
      },
    );
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminDeleteBusyByEmail;
    state.adminDeleteBusyByEmail = nextBusy;
    renderApp();
    if (didSucceed) {
      setStatus("Client deleted");
    }
  }
}

function updateHeader() {
  const displayName = getDisplayName();
  const workspaceName = getWorkspaceName();
  const selectedFeature = getSelectedFeature();
  const settingsLabel = state.settingsMode === "users"
    ? getSettingsModeContent(state.settingsMode).title
    : "Settings";
  const titleLabel = state.settingsOpen
    ? settingsLabel
    : state.selectedFeatureId && selectedFeature
      ? selectedFeature.name
      : TAB_LABELS[state.activeTab] || capitalizeWords(state.activeTab);
  if (elements.workspaceTitle) {
    elements.workspaceTitle.textContent = workspaceName;
  }
  if (elements.workspaceSubtitle) {
    elements.workspaceSubtitle.textContent = `Signed in as ${displayName}`;
  }
  elements.accountAvatar.textContent = getAvatarLabel();
  elements.accountLabel.textContent = activeEmail;
  document.title = `${workspaceName} · ${titleLabel}`;
}

function getAgentWorkspace() {
  if (!clientState.agent) {
    clientState.agent = createDefaultAgentWorkspace();
  }

  clientState.agent = normalizeAgentWorkspace(clientState.agent);
  return clientState.agent;
}

function getActiveAgentChat(agent = getAgentWorkspace()) {
  return agent.chats.find((chat) => chat.id === agent.activeChatId) || agent.chats[0] || null;
}

function syncActiveAgentChatFromWorkspace(agent = getAgentWorkspace(), options = {}) {
  const chat = getActiveAgentChat(agent);
  if (!chat) {
    return null;
  }

  const messages = Array.isArray(agent.messages)
    ? agent.messages.map(normalizeAgentMessage).filter(Boolean).slice(-AGENT_MAX_MESSAGES)
    : [];
  chat.messages = messages;
  chat.updatedAt = messages.at(-1)?.createdAt || options.updatedAt || chat.updatedAt || new Date().toISOString();
  if (options.clientActivity === true) {
    chat.lastClientActivityAt = options.at || chat.updatedAt;
  }
  return chat;
}

function prepareAgentWorkspaceForPersistence(agent = getAgentWorkspace()) {
  syncActiveAgentChatFromWorkspace(agent);
  agent.chats = sortAgentChats(agent.chats).slice(0, AGENT_MAX_CHATS);
  agent.folders = sortAgentFolders(agent.folders, agent.folderSort).slice(0, AGENT_MAX_FOLDERS);
  agent.folderSort = normalizeAgentFolderSort(agent.folderSort || state.agentFolderSort);
  if (!agent.chats.some((chat) => chat.id === agent.activeChatId)) {
    agent.activeChatId = agent.chats[0]?.id || "";
  }
  clientState.agent = normalizeAgentWorkspace(agent);
  return clientState.agent;
}

function getAgentChatIdleReferenceAt(chat) {
  return Math.max(
    parseAgentTimestamp(chat?.lastClientActivityAt),
    parseAgentTimestamp(chat?.lastOpenedAt),
    parseAgentTimestamp(chat?.updatedAt),
    parseAgentTimestamp(chat?.createdAt),
  );
}

function archiveAgentChat(chat, archivedAt = new Date().toISOString()) {
  if (!chat) {
    return;
  }

  chat.status = "historical";
  chat.archivedAt = chat.archivedAt || archivedAt;
}

function createAndActivateAgentChat(agent = getAgentWorkspace(), options = {}) {
  syncActiveAgentChatFromWorkspace(agent);
  const chat = createAgentChat([], {
    title: options.title || "New chat",
    status: "active",
    lastOpenedAt: new Date().toISOString(),
  });
  agent.chats.unshift(chat);
  agent.chats = sortAgentChats(agent.chats).slice(0, AGENT_MAX_CHATS);
  agent.activeChatId = chat.id;
  agent.messages = chat.messages;
  return chat;
}

function rollOverIdleAgentChatIfNeeded(agent = getAgentWorkspace(), nowMs = Date.now()) {
  const chat = getActiveAgentChat(agent);
  if (!chat) {
    return false;
  }

  const now = new Date(nowMs).toISOString();
  const idleReferenceAt = getAgentChatIdleReferenceAt(chat);
  if (!chat.messages.length || !idleReferenceAt || nowMs - idleReferenceAt < AGENT_CHAT_IDLE_MS) {
    chat.lastOpenedAt = now;
    return false;
  }

  archiveAgentChat(chat, now);
  createAndActivateAgentChat(agent, { title: "New chat" });
  return true;
}

function recordAgentPortalOpened(options = {}) {
  if (!clientState?.agent) {
    return false;
  }

  const agent = getAgentWorkspace();
  const didRollOver = rollOverIdleAgentChatIfNeeded(agent);
  if (options.persist !== false) {
    persistClientState();
  }
  return didRollOver;
}

function syncAgentStateFromClientState(options = {}) {
  const agent = getAgentWorkspace();
  state.agentPanelMode = normalizeAgentPanelMode(agent.panelMode || state.agentPanelMode);
  state.agentFolderSort = normalizeAgentFolderSort(agent.folderSort || state.agentFolderSort);
  if (options.recordOpen) {
    recordAgentPortalOpened({ persist: options.persistOpen !== false });
  }
}

function touchActiveAgentChat(options = {}) {
  const agent = getAgentWorkspace();
  const now = options.at || new Date().toISOString();
  const chat = syncActiveAgentChatFromWorkspace(agent, {
    at: now,
    clientActivity: options.clientActivity === true,
    updatedAt: now,
  });
  if (chat && options.opened === true) {
    chat.lastOpenedAt = now;
  }
  return chat;
}

function startNewAgentChat() {
  const agent = getAgentWorkspace();
  const activeChat = getActiveAgentChat(agent);
  if (activeChat) {
    archiveAgentChat(activeChat);
  }
  createAndActivateAgentChat(agent, { title: "New chat" });
  state.agentPanelMode = "chats";
  agent.panelMode = "chats";
  elements.agentMessageList?.removeAttribute("data-agent-message-render-signature");
  persistClientState();
  renderApp({ preserveStatus: true });
  window.requestAnimationFrame(() => {
    elements.agentComposerInput?.focus();
  });
}

function selectAgentChat(chatId) {
  const agent = getAgentWorkspace();
  const chat = agent.chats.find((candidate) => candidate.id === chatId);
  if (!chat) {
    return;
  }

  syncActiveAgentChatFromWorkspace(agent);
  const previousChat = getActiveAgentChat(agent);
  if (previousChat && previousChat.id !== chat.id) {
    archiveAgentChat(previousChat);
  }
  agent.activeChatId = chat.id;
  agent.messages = chat.messages;
  chat.status = "active";
  chat.lastOpenedAt = new Date().toISOString();
  state.agentPanelMode = "chats";
  agent.panelMode = "chats";
  elements.agentMessageList?.removeAttribute("data-agent-message-render-signature");
  persistClientState();
  renderApp({ preserveStatus: true });
}

// The rest of the portal confirms destructive actions with the in-app dialog,
// and this used to be the one caller of window.confirm(). Native dialogs are
// suppressed outright in some mobile browsers and in-app webviews, where
// confirm() returns false without ever showing anything -- the delete button
// looked dead. Use the same dialog every other delete uses.
function deleteAgentChat(chatId, options = {}) {
  const agent = getAgentWorkspace();
  const chat = agent.chats.find((candidate) => candidate.id === chatId);
  if (!chat || chat.id === agent.activeChatId) {
    return;
  }

  const title = getAgentChatTitle(chat);
  openAuthAlert(
    "Delete conversation?",
    `Delete “${title}”? This conversation will be removed from your chat history.`,
    {
      eyebrow: "Delete conversation",
      icon: "!",
      tone: "warning",
      buttonLabel: "Delete",
      primaryTone: "danger",
      secondaryButtonLabel: "Cancel",
      focusTarget: "secondary",
      returnFocus: options.returnFocus || elements.agentNewChatButton,
      onPrimary: () => {
        confirmAgentChatDelete(chat.id);
      },
    },
  );
}

function confirmAgentChatDelete(chatId) {
  const agent = getAgentWorkspace();
  const chat = agent.chats.find((candidate) => candidate.id === chatId);
  if (!chat || chat.id === agent.activeChatId) {
    return;
  }

  agent.chats = agent.chats.filter((candidate) => candidate.id !== chat.id);
  persistClientState();
  renderAgentChats();
  setStatus("Conversation deleted");
}

function setAgentPanelMode(mode, options = {}) {
  const nextMode = normalizeAgentPanelMode(mode);
  state.agentPanelMode = nextMode;
  const agent = getAgentWorkspace();
  agent.panelMode = nextMode;
  if (options.persist !== false) {
    persistClientState();
  }
  updateAgentWorkspace();
}

function getAgentPanelModeControls() {
  return [
    [elements.agentPanelActionsModeButton, "actions"],
    [elements.agentPanelChatsModeButton, "chats"],
    [elements.agentPanelFoldersModeButton, "folders"],
  ].filter(([button]) => Boolean(button));
}

function setAgentFolderSearch(value) {
  state.agentFolderSearch = normalizeAgentTextItem(value, "").slice(0, 80);
  renderAgentFolders();
}

function setAgentFolderSort(value, options = {}) {
  const sort = normalizeAgentFolderSort(value);
  state.agentFolderSort = sort;
  const agent = getAgentWorkspace();
  agent.folderSort = sort;
  if (options.persist !== false) {
    persistClientState();
  }
  renderAgentFolders();
}

function closeAgentFolderDisclosurePanels(except = "") {
  state.agentFolderCreateOpen = except === "create";
  state.agentFolderFilterOpen = except === "filter";
  state.agentFolderSortOpen = except === "sort";
}

function setAgentFolderCreateOpen(open) {
  closeAgentFolderDisclosurePanels(open ? "create" : "");
  renderAgentFolders();
  if (open) {
    window.requestAnimationFrame(() => {
      elements.agentFolderNameInput?.focus();
    });
  }
}

function setAgentFolderFilterOpen(open) {
  closeAgentFolderDisclosurePanels(open ? "filter" : "");
  renderAgentFolders();
  if (open) {
    window.requestAnimationFrame(() => {
      elements.agentFolderSearchInput?.focus();
    });
  }
}

function setAgentFolderSortOpen(open) {
  closeAgentFolderDisclosurePanels(open ? "sort" : "");
  renderAgentFolders();
  if (open) {
    window.requestAnimationFrame(() => {
      elements.agentFolderSortSelect?.focus();
    });
  }
}

function syncAgentFolderDisclosureControl(button, panel, open, active = open) {
  button?.setAttribute("aria-expanded", String(Boolean(open)));
  button?.classList.toggle("is-active", Boolean(active));
  panel?.classList.toggle("is-hidden", !open);
  if (panel) {
    panel.hidden = !open;
  }
}

function syncAgentFolderDisclosureControls() {
  syncAgentFolderDisclosureControl(
    elements.agentFolderCreateToggleButton,
    elements.agentFolderCreateForm,
    state.agentFolderCreateOpen,
  );
  elements.agentFolderCreateToggleButton?.classList.toggle("is-open", state.agentFolderCreateOpen);

  syncAgentFolderDisclosureControl(
    elements.agentFolderFilterButton,
    elements.agentFolderFilterPanel,
    state.agentFolderFilterOpen,
    state.agentFolderFilterOpen || Boolean(state.agentFolderSearch),
  );

  syncAgentFolderDisclosureControl(
    elements.agentFolderSortButton,
    elements.agentFolderSortPanel,
    state.agentFolderSortOpen,
    state.agentFolderSortOpen || state.agentFolderSort !== "recent",
  );
}

function addAgentFolder(name, type = "general") {
  const folderName = normalizeAgentFolderName(name, "");
  if (!folderName) {
    return null;
  }

  const agent = getAgentWorkspace();
  const duplicate = agent.folders.some((folder) => folder.name.toLowerCase() === folderName.toLowerCase());
  if (duplicate) {
    return null;
  }

  const folder = createAgentFolderRecord(folderName, type);
  agent.folders.unshift(folder);
  agent.folders = sortAgentFolders(agent.folders, state.agentFolderSort).slice(0, AGENT_MAX_FOLDERS);
  agent.panelMode = "folders";
  state.agentPanelMode = "folders";
  persistClientState();
  updateAgentWorkspace();
  return folder;
}

function normalizeAgentDeliveryChannel(value) {
  const text = String(value || "").toLowerCase();
  if (/\bwhats\s*app\b|\bwhatsapp\b/.test(text)) {
    return "whatsapp";
  }
  if (/\btelegram\b/.test(text)) {
    return "telegram";
  }
  if (/\bemail\b|\bmail\b/.test(text)) {
    return "email";
  }
  if (/\bportal\b|\bworkspace\b|\bchat\b|\bnotification(?:s)?\b/.test(text)) {
    return "portal";
  }
  return "";
}

function extractAgentTimeLocal(text) {
  const value = String(text || "");
  const colonMatch = value.match(/\b([01]?\d|2[0-3])[:.]([0-5]\d)\s*(a\.?m\.?|p\.?m\.?|am|pm)?\b/i);
  const hourOnlyMatch = value.match(/\b(1[0-2]|0?[1-9])\s*(a\.?m\.?|p\.?m\.?|am|pm)\b/i);
  const match = colonMatch || hourOnlyMatch;
  if (!match) {
    return "";
  }

  let hour = Number.parseInt(match[1], 10);
  const minute = colonMatch ? Number.parseInt(match[2], 10) : 0;
  const meridiem = String(colonMatch ? match[3] || "" : match[2] || "").toLowerCase().replace(/\./g, "");
  if (!Number.isFinite(hour) || !Number.isFinite(minute)) {
    return "";
  }
  if (meridiem === "pm" && hour < 12) {
    hour += 12;
  }
  if (meridiem === "am" && hour === 12) {
    hour = 0;
  }
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
    return "";
  }
  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function extractAgentDatePolicy(text) {
  const value = String(text || "").toLowerCase();
  if (/\btomorrow\b/.test(value)) {
    return "tomorrow";
  }
  if (/\btoday\b|\btonight\b/.test(value)) {
    return "today";
  }
  return "next_occurrence";
}

function getAgentDefaultScheduledMessageText(timeLocal = "") {
  const normalizedTime = String(timeLocal || "").trim();
  return normalizedTime ? `It's ${normalizedTime}.` : "";
}

function isAgentDefaultScheduledMessageText(messageText, timeLocal = "") {
  return String(messageText || "").trim() === getAgentDefaultScheduledMessageText(timeLocal);
}

function extractAgentScheduledMessageText(text, timeLocal = "") {
  const value = String(text || "").trim();
  const quotedMatch = value.match(/\b(?:saying|that says|with text|message(?: saying)?|text)\s+["“']([^"”']{1,400})["”']/i);
  if (quotedMatch?.[1]) {
    return quotedMatch[1].trim();
  }

  const reminderMatch = value.match(/\bremind me to\s+(.+?)\s+(?:at|when|by)\b/i);
  if (reminderMatch?.[1]) {
    return reminderMatch[1].trim();
  }

  if (timeLocal) {
    return getAgentDefaultScheduledMessageText(timeLocal);
  }
  return "";
}

function isAgentScheduledMessageRequest(text) {
  const value = String(text || "").toLowerCase();
  const asksForSend = /\b(send|message|notify|remind|alert)\b/.test(value);
  const hasTimeTrigger = Boolean(extractAgentTimeLocal(value)) || /\b(today|tomorrow|tonight)\b/.test(value);
  return asksForSend && hasTimeTrigger;
}

function resolveAgentScheduledRunAt(details = {}, now = new Date()) {
  const timeLocal = String(details.timeLocal || "").trim();
  const timeMatch = timeLocal.match(/^([01]\d|2[0-3]):([0-5]\d)$/);
  if (!timeMatch) {
    return "";
  }

  const timeZone = normalizeMonitorScheduleTimezone(
    details.timezone || clientState?.settings?.timezone || defaultTimeZone(),
    "UTC",
  ) || "UTC";
  const currentTime = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date();
  const currentParts = getMonitorZonedDateTimeParts(currentTime, timeZone);
  if (!currentParts) {
    return "";
  }

  const hour = Number.parseInt(timeMatch[1], 10);
  const minute = Number.parseInt(timeMatch[2], 10);
  let dateParts = {
    year: currentParts.year,
    month: currentParts.month,
    day: currentParts.day,
  };
  const datePolicy = String(details.datePolicy || "next_occurrence").trim();
  if (datePolicy === "tomorrow") {
    dateParts = addMonitorUtcDays(dateParts, 1);
  }

  let candidate = buildMonitorDateInTimeZone({
    ...dateParts,
    hour,
    minute,
    second: 0,
  }, timeZone);

  if (datePolicy === "next_occurrence" && candidate && candidate.getTime() <= currentTime.getTime()) {
    dateParts = addMonitorUtcDays(dateParts, 1);
    candidate = buildMonitorDateInTimeZone({
      ...dateParts,
      hour,
      minute,
      second: 0,
    }, timeZone);
  }

  return candidate && !Number.isNaN(candidate.getTime()) ? candidate.toISOString() : "";
}

function buildAgentScheduledMessageQuestionPlan(details = {}) {
  const questions = [];
  const questionKeys = [];
  if (!normalizeAgentDeliveryChannel(details.channel)) {
    questionKeys.push("channel");
    questions.push("Which channel should I use to send it?");
  }
  if (!String(details.timeLocal || details.runAt || "").trim()) {
    questionKeys.push("time");
    questions.push("What exact local time should I send it?");
  }
  if (!String(details.messageText || "").trim()) {
    questionKeys.push("messageText");
    questions.push("What should the message say?");
  }
  return { questions, questionKeys };
}

function buildAgentScheduledMessageDetails(text) {
  const requestText = String(text || "");
  const channel = normalizeAgentDeliveryChannel(requestText);
  const timeLocal = extractAgentTimeLocal(requestText);
  const timezone = normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC";
  const datePolicy = extractAgentDatePolicy(requestText);
  const messageText = extractAgentScheduledMessageText(requestText, timeLocal);
  const messageSource = messageText && !isAgentDefaultScheduledMessageText(messageText, timeLocal)
    ? "user"
    : "generated";
  const details = {
    actionType: "send_message",
    channel,
    recipientRef: /\b(me|myself|owner)\b/i.test(requestText) ? "owner" : "owner",
    timeLocal,
    datePolicy,
    timezone,
    messageText,
    messageSource,
    runAt: "",
  };
  details.runAt = resolveAgentScheduledRunAt(details);
  return details;
}

function buildAgentSourceActionDetails(text, proposal = null) {
  const requestText = String(text || "");
  const fields = proposal?.fields && typeof proposal.fields === "object" ? proposal.fields : {};
  const attachedSourceType = ["file", "url"].includes(agentSourceAttachment?.sourceType)
    ? agentSourceAttachment.sourceType
    : "";
  const sourceType = String(fields.sourceType || attachedSourceType || "url").trim().toLowerCase();
  const sourceUrl = String(
    fields.sourceUrl
    || (sourceType === "url" ? agentSourceAttachment?.sourceUrl : "")
    || requestText.match(/https?:\/\/[^\s<>)\]}]+/i)?.[0]
    || "",
  ).replace(/[.,!?]+$/, "");
  const frequency = String(fields.frequency || extractAgentFrequencyField(requestText) || "daily").trim();
  const interval = buildAgentMonitorIntervalFromFrequency(frequency);
  return {
    sourceType: sourceType === "file" ? "file" : "url",
    sourceUrl: sourceType === "file" ? "" : sourceUrl,
    fileName: sourceType === "file" ? String(fields.sourceFileName || agentSourceAttachment?.fileName || "").trim() : "",
    mimeType: sourceType === "file" ? String(fields.sourceMimeType || agentSourceAttachment?.mimeType || "").trim() : "",
    frequency,
    intervalMinutes: interval.intervalMinutes || Math.max(1, interval.intervalDays * 24 * 60),
    timezone: getWorkspaceTimeZone(),
  };
}

function buildAgentSourceActionExecutionPlan(details = {}) {
  return {
    trigger: {
      type: "interval",
      frequency: String(details.frequency || "daily"),
      intervalMinutes: Number(details.intervalMinutes || 1440),
      timezone: String(details.timezone || getWorkspaceTimeZone()),
    },
    action: {
      type: "source_snapshot",
      sourceType: String(details.sourceType || ""),
      sourceUrl: String(details.sourceUrl || ""),
      fileName: String(details.fileName || ""),
    },
  };
}

function buildAgentScheduledMessageExecutionPlan(details = {}) {
  return {
    trigger: {
      type: "at",
      runAt: String(details.runAt || "").trim(),
      timeLocal: String(details.timeLocal || "").trim(),
      timezone: String(details.timezone || "").trim(),
      datePolicy: String(details.datePolicy || "next_occurrence").trim(),
    },
    action: {
      type: "send_message",
      channel: normalizeAgentDeliveryChannel(details.channel),
      recipientRef: String(details.recipientRef || "owner").trim(),
      messageText: String(details.messageText || "").trim(),
    },
  };
}

function formatAgentScheduledMessageChannel(channel) {
  const normalized = normalizeAgentDeliveryChannel(channel);
  if (normalized === "whatsapp") {
    return "WhatsApp";
  }
  if (normalized === "telegram") {
    return "Telegram";
  }
  if (normalized === "email") {
    return "email";
  }
  if (normalized === "portal") {
    return "the notification center";
  }
  return "the chosen channel";
}

function getAgentBlueprintForText(text) {
  const value = String(text || "").toLowerCase();
  if (isAgentScheduledMessageRequest(value)) {
    return AGENT_BLUEPRINTS.scheduledMessage;
  }

  if (/(https?:\/\/\S+|\b(?:file|document|spreadsheet|csv|pdf)\b)/i.test(value)
    && /\b(?:check|watch|monitor|refresh|fetch|run|every|daily|hourly|weekly|schedule|keep)\b/i.test(value)) {
    return AGENT_BLUEPRINTS.sourceAction;
  }

  if (/\b(?:calendar|meeting|meetings|agenda|appointment|appointments)\b/i.test(value)
    && /\b(?:summar(?:y|ize|ise)|brief|overview|review|list|show)\b/i.test(value)) {
    return AGENT_BLUEPRINTS.calendarSummary;
  }

  if (/\b(gmail|inbox|email|mailbox|digest|summari[sz]e|summary)\b/.test(value)) {
    return AGENT_BLUEPRINTS.emailDigest;
  }

  if (/\b(re-?engage|follow[- ]?up|past customer|quiet conversation|dormant)\b/.test(value)) {
    return AGENT_BLUEPRINTS.reengagement;
  }

  if (/\b(whatsapp|reply|approval|lead|customer message)\b/.test(value)) {
    return AGENT_BLUEPRINTS.whatsappReplies;
  }

  if (/\b(watch|monitor|deadline|alert|web|search|opportunit|event)\b/.test(value)) {
    return AGENT_BLUEPRINTS.webMonitor;
  }

  return AGENT_BLUEPRINTS.custom;
}

function getAgentBlueprintForType(type) {
  const normalizedType = String(type || "").trim();
  return Object.values(AGENT_BLUEPRINTS).find((blueprint) => blueprint.type === normalizedType)
    || AGENT_BLUEPRINTS.custom;
}

function cloneAgentItems(items = []) {
  return Array.isArray(items) ? items.map((item) => ({ ...item })) : [];
}

function createAgentProposalFromRequest(text, blueprintOverride = null) {
  const blueprint = blueprintOverride && typeof blueprintOverride === "object"
    ? blueprintOverride
    : getAgentBlueprintForText(text);
  const scheduledDetails = blueprint.type === "scheduled-message" ? buildAgentScheduledMessageDetails(text) : {};
  const inferredFields = blueprint.type === "scheduled-message"
    ? {}
    : inferAgentProposalFieldsFromText(text, blueprint.type);
  // Action results default to the notification center. Setup questions and
  // approvals still stay in the Assistyca conversation.
  if (
    blueprint.type !== "scheduled-message"
    && getAgentProposalFieldSchema({ type: blueprint.type, requestText: String(text || "") })
      .some((field) => field?.key === "deliveryChannel")
    && !inferredFields.deliveryChannel
  ) {
    inferredFields.deliveryChannel = "portal";
  }
  if (blueprint.type === "whatsapp-replies" && isWhatsAppConnectionReady()) {
    inferredFields.whatsappNumber = inferredFields.whatsappNumber || "connected WhatsApp number";
    inferredFields.deliveryChannel = inferredFields.deliveryChannel || "portal";
  }
  const scheduledQuestionPlan = blueprint.type === "scheduled-message"
    ? buildAgentScheduledMessageQuestionPlan(scheduledDetails)
    : { questions: [...blueprint.questions], questionKeys: [] };
  const scheduledChannel = normalizeAgentDeliveryChannel(scheduledDetails.channel);
  const relatedFeatureId = blueprint.type === "scheduled-message" && scheduledChannel === "whatsapp"
    ? WHATSAPP_REPLY_ASSISTANT_FEATURE_ID
    : blueprint.relatedFeatureId;
  const calendarConnected = isCalendarConnectionReady();
  const gmailConnected = isEmailConnectionReady();
  let missingCredential = blueprint.missingCredential;
  if (blueprint.type === "scheduled-message" && scheduledChannel === "whatsapp") {
    missingCredential = isFeatureSetupComplete(getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID))
      ? ""
      : "WhatsApp Business API access token";
  } else if (blueprint.type === "whatsapp-replies" && isWhatsAppConnectionReady()) {
    missingCredential = "";
  } else if (blueprint.type === "calendar-summary" && calendarConnected) {
    missingCredential = "";
  } else if (blueprint.type === "email-digest" && gmailConnected) {
    missingCredential = "";
  }
  const proposal = normalizeAgentProposal({
    id: createAgentId("agent-proposal"),
    type: blueprint.type,
    requestText: String(text || "").trim(),
    title: blueprint.title,
    summary: blueprint.summary,
    response: blueprint.response,
    relatedFeatureId,
    primaryActionLabel: blueprint.primaryActionLabel,
    setupActionLabel: blueprint.setupActionLabel,
    missingCredential,
    status: "needs-approval",
    approved: false,
    revision: 1,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    details: scheduledDetails,
    fields: inferredFields,
    executionPlan: blueprint.type === "scheduled-message"
      ? buildAgentScheduledMessageExecutionPlan(scheduledDetails)
      : {},
    skills: cloneAgentItems(blueprint.skills),
    helpers: cloneAgentItems(blueprint.helpers),
    questions: scheduledQuestionPlan.questions,
    questionKeys: scheduledQuestionPlan.questionKeys,
    alternatives: [...blueprint.alternatives],
  });

  const requestedManualOnly = agentWebMonitorTextSuggestsManualOnly(text)
    || (["calendar-summary", "email-digest"].includes(blueprint.type) && !extractAgentFrequencyField(text));
  if (requestedManualOnly) {
    proposal.details = {
      ...proposal.details,
      manualOnly: true,
      runMode: "manual",
    };
    proposal.executionPlan = {
      ...proposal.executionPlan,
      manualOnly: true,
      runMode: "manual",
      frequency: "manual only",
    };
  }

  if (proposal.type === "custom") {
    proposal.title = getAgentProposalPurposeTitle(proposal);
    proposal.summary = getAgentActionPurposeText(String(text).trim().slice(0, 140)) || blueprint.summary;
  }
  if (proposal.type === "scheduled-message") {
    const channelLabel = formatAgentScheduledMessageChannel(scheduledDetails.channel);
    const timeLabel = scheduledDetails.timeLocal ? ` at ${scheduledDetails.timeLocal}` : "";
    proposal.summary = `Schedule a one-shot ${channelLabel} message${timeLabel}.`;
  } else if (proposal.type === "source-action") {
    const sourceDetails = buildAgentSourceActionDetails(text, proposal);
    proposal.details = sourceDetails;
    proposal.executionPlan = buildAgentSourceActionExecutionPlan(sourceDetails);
    updateAgentProposalSummaryFromFields(proposal);
  } else {
    updateAgentProposalSummaryFromFields(proposal);
  }

  syncAgentProposalRequiredConnection(proposal);
  if (proposal.type === "custom") {
    proposal.title = getAgentProposalPurposeTitle(proposal);
  }
  return proposal;
}

function getActiveAgentProposal() {
  const agent = getAgentWorkspace();
  return agent.proposals.find((proposal) => proposal.id === agent.activeProposalId)
    || agent.proposals[agent.proposals.length - 1]
    || null;
}

function isAgentCalendarSummaryRequest(text) {
  const value = String(text || "").trim().toLowerCase();
  return /\b(?:meeting|meetings|calendar|agenda|appointment|appointments)\b/.test(value)
    && /\b(?:summar(?:y|ize|ise)|brief|overview|review|list|show)\b/.test(value);
}

function switchAgentProposalToCalendarSummary(proposal, requestText) {
  if (!proposal || proposal.type !== "email-digest" || !isAgentCalendarSummaryRequest(requestText)) {
    return false;
  }

  const previousId = proposal.id;
  const previousCreatedAt = proposal.createdAt;
  const previousRevision = Math.max(1, Number(proposal.revision || 1));
  const previousDeliveryChannel = getAgentProposalFieldValue(proposal, "deliveryChannel");
  const previousManualOnly = getAgentProposalManualOnly(proposal);
  const replacement = createAgentProposalFromRequest(requestText, AGENT_BLUEPRINTS.calendarSummary);
  if (previousDeliveryChannel && !replacement.fields.deliveryChannel) {
    replacement.fields.deliveryChannel = previousDeliveryChannel;
  }
  if (getPlatformConnectionByPlatform("calendar")?.connectionStatus === "connected") {
    replacement.fields.calendar = "Connected calendar";
  }
  if (previousManualOnly) {
    replacement.details = {
      ...replacement.details,
      manualOnly: true,
      runMode: "manual",
    };
    replacement.executionPlan = {
      ...replacement.executionPlan,
      manualOnly: true,
      runMode: "manual",
      frequency: "manual only",
    };
  }
  syncAgentProposalFieldCompatibility(replacement);
  updateAgentProposalSummaryFromFields(replacement);
  syncAgentProposalRequiredConnection(replacement);

  Object.assign(proposal, replacement, {
    id: previousId,
    createdAt: previousCreatedAt || replacement.createdAt,
    revision: previousRevision + 1,
    approved: false,
    approvedAt: "",
    status: "needs-approval",
    updatedAt: new Date().toISOString(),
  });
  return true;
}

function getLatestApprovedAgentProposal() {
  const agent = getAgentWorkspace();
  return [...agent.proposals].reverse().find((proposal) => proposal.approved) || null;
}

function pushAgentMessage(role, text, metadata = {}) {
  const agent = getAgentWorkspace();
  const message = createAgentMessage(role, text, metadata);
  if (!message.text) {
    return null;
  }

  agent.messages.push(message);
  agent.messages = agent.messages.slice(-AGENT_MAX_MESSAGES);
  syncActiveAgentChatFromWorkspace(agent, {
    at: message.createdAt,
    clientActivity: message.role === "user",
    updatedAt: message.createdAt,
  });
  return message;
}

function createAgentAction(id, label, value = label, tone = "secondary") {
  return { id, label, value, tone };
}

function resolveAgentMessageActions(messageId, resolvedBy = "user-message") {
  const agent = getAgentWorkspace();
  const message = agent.messages.find((candidate) => candidate.id === messageId);
  if (!message || !Array.isArray(message.metadata?.actions) || !message.metadata.actions.length) {
    return false;
  }

  message.metadata.actionsResolvedAt = message.metadata.actionsResolvedAt || new Date().toISOString();
  message.metadata.actionsResolvedBy = String(resolvedBy || "user-message").trim();
  return true;
}

function resolvePendingAgentMessageActions(resolvedBy = "user-message") {
  const agent = getAgentWorkspace();
  let didResolve = false;
  for (const message of agent.messages) {
    if (message.role !== "assistant" || message.metadata?.actionsResolvedAt) {
      continue;
    }
    if (!Array.isArray(message.metadata?.actions) || !message.metadata.actions.length) {
      continue;
    }
    message.metadata.actionsResolvedAt = new Date().toISOString();
    message.metadata.actionsResolvedBy = String(resolvedBy || "user-message").trim();
    didResolve = true;
  }
  return didResolve;
}

function areAgentMessageActionsResolved(message, messages = []) {
  if (message.metadata?.actionsResolvedAt) {
    return true;
  }

  const messageIndex = messages.findIndex((candidate) => candidate.id === message.id);
  return messageIndex >= 0 && messageIndex < messages.length - 1;
}

function getAgentStoredMessageActions(message) {
  return Array.isArray(message?.metadata?.actions) ? message.metadata.actions : [];
}

function getAgentMessageProposal(message, agent = getAgentWorkspace()) {
  const proposalId = message?.metadata?.proposalId || "";
  return proposalId
    ? agent.proposals.find((candidate) => candidate.id === proposalId) || null
    : null;
}

function getAgentRenderableMessageActions(message, kind, proposal) {
  if (!message || message.role === "user" || kind === "connection-setup") {
    return [];
  }

  if (kind === "action-choice") {
    return [];
  }

  if (kind === "question" && proposal && !proposal.approved && proposal.status !== "rejected") {
    const questionIndex = Math.max(0, Number(message.metadata?.questionIndex || proposal.questionIndex || 0) || 0);
    const questionText = getAgentDisplayMessageText(message, kind, proposal);
    const requirement = getAgentProposalRequiredConnection(proposal);
    if (requirement && !isAgentProposalRequiredConnectionReady(requirement) && isAgentConnectionSetupReply(questionText)) {
      return [createAgentAction(
        "open-setup",
        requirement.actionLabel || "Open setup",
        proposal.id,
        "primary",
      )];
    }
    const questionFieldKey = String(message.metadata?.fieldKey || "").trim();
    const questionActions = questionFieldKey
      ? getAgentQuestionActions(proposal, questionIndex, questionText, questionFieldKey)
      : getAgentQuestionActions(proposal, questionIndex, message.text);
    if (questionActions.length) {
      return questionActions;
    }
  }

  if (kind === "approval" && proposal) {
    return getAgentApprovalPromptActions(proposal, message.text);
  }

  return getAgentStoredMessageActions(message);
}

function normalizeAgentProposalFieldKey(key) {
  const rawKey = String(key || "").trim();
  if (!rawKey) {
    return "";
  }
  const aliasKey = rawKey
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/[\s.-]+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "")
    .toLowerCase();
  return AGENT_PROPOSAL_FIELD_ALIASES[aliasKey] || rawKey.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 80);
}

function getAgentProposalFieldKeyForSchema(rawKey, allowedKeys) {
  let key = normalizeAgentProposalFieldKey(rawKey);
  if (allowedKeys.has(key)) {
    return key;
  }

  const aliasKey = String(rawKey || "")
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/[\s.-]+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "")
    .toLowerCase();
  if (["schedule", "time", "cadence", "interval"].includes(aliasKey) && allowedKeys.has("frequency")) {
    key = "frequency";
  } else if (["schedule", "time", "send_time", "sendtime"].includes(aliasKey) && allowedKeys.has("schedule")) {
    key = "schedule";
  }
  return allowedKeys.has(key) ? key : "";
}

function getAgentProposalFieldSchema(proposal) {
  const requestText = String(proposal?.requestText || "");
  if (
    proposal?.type === "custom"
    && /\b(calendar|agenda|appointments?)\b/i.test(requestText)
  ) {
    return AGENT_CALENDAR_FIELD_SCHEMA;
  }
  return AGENT_PROPOSAL_FIELD_SCHEMAS[proposal?.type] || AGENT_PROPOSAL_FIELD_SCHEMAS.custom;
}

function getAgentProposalFieldMap(proposal) {
  return proposal?.fields && typeof proposal.fields === "object" && !Array.isArray(proposal.fields)
    ? proposal.fields
    : {};
}

function hasAgentProposalFieldValue(proposal, key) {
  if (key === "deliveryChannel") {
    return Boolean(getAgentProposalDeliveryChannel(proposal));
  }
  return Boolean(String(getAgentProposalFieldMap(proposal)[key] || "").trim());
}

function isAgentWebMonitorLocationSensitive(proposal) {
  if (proposal?.type !== "web-monitor") {
    return false;
  }
  const fields = getAgentProposalFieldMap(proposal);
  const text = `${proposal.requestText || ""} ${fields.watchQuery || ""}`.toLowerCase();
  return /\b(events?|activities|things to do|kids?|children|famil(y|ies)|nearby|near me|local|restaurants?|venues?|classes?|workshops?|camps?)\b/.test(text);
}

function isAgentProposalFieldRequired(proposal, field) {
  if (!field || field.required === false) {
    return false;
  }
  if (field.requiredWhen === "web-monitor-location-sensitive") {
    return isAgentWebMonitorLocationSensitive(proposal);
  }
  if (field.requiredWhen === "source-url") {
    return String(getAgentProposalFieldMap(proposal).sourceType || "").trim().toLowerCase() === "url";
  }
  if (field.requiredWhen === "source-file") {
    return String(getAgentProposalFieldMap(proposal).sourceType || "").trim().toLowerCase() === "file";
  }
  return true;
}

function getAgentNextMissingQuestionIndex(proposal) {
  if (proposal?.type === "scheduled-message") {
    const questions = Array.isArray(proposal.questions) ? proposal.questions : [];
    const answers = Array.isArray(proposal.answers) ? proposal.answers : [];
    return answers.length < questions.length ? answers.length : -1;
  }

  const schema = getAgentProposalFieldSchema(proposal);
  for (let index = 0; index < schema.length; index += 1) {
    const field = schema[index];
    if (isAgentProposalFieldRequired(proposal, field) && !hasAgentProposalFieldValue(proposal, field.key)) {
      return index;
    }
  }
  return -1;
}

function formatAgentProposalFieldValue(key, value) {
  const cleanValue = String(value || "").trim().replace(/\s+/g, " ");
  if (!cleanValue) {
    return "";
  }
  if (key === "deliveryChannel") {
    const channel = normalizeAgentDeliveryChannel(cleanValue);
    return channel ? formatAgentScheduledMessageChannel(channel) : cleanValue;
  }
  return cleanValue.slice(0, 400).trim();
}

function getAgentProposalFieldKeysForAnswers(proposal, answerCount = 0) {
  const schema = getAgentProposalFieldSchema(proposal);
  if (answerCount === 1) {
    const missingIndex = getAgentNextMissingQuestionIndex(proposal);
    if (missingIndex >= 0 && schema[missingIndex]?.key) {
      return [schema[missingIndex].key];
    }
  }

  if (proposal?.type === "web-monitor") {
    if (answerCount >= 5) {
      return schema.map((field) => field.key);
    }
    if (answerCount === 4) {
      return ["watchQuery", "location", "frequency", "deliveryChannel"];
    }
    return ["watchQuery", "frequency", "deliveryChannel"];
  }

  if (proposal?.type === "email-digest") {
    return ["mailbox", "schedule", "deliveryChannel"];
  }

  if (proposal?.type === "calendar-summary") {
    return ["calendar", "timeWindow", "deliveryChannel"];
  }

  if (proposal?.type === "whatsapp-replies") {
    return ["whatsappNumber", "approver", "guardrails", "deliveryChannel"];
  }

  if (proposal?.type === "reengagement") {
    return ["inactivityPeriod", "frequency", "deliveryChannel"];
  }

  if (proposal?.type === "source-action") {
    return ["sourceType", "sourceUrl", "sourceFileName", "frequency"];
  }

  return schema.map((field) => field.key);
}

function mergeAgentProposalFields(proposal, rawFields = {}) {
  if (!proposal || proposal.type === "scheduled-message") {
    return false;
  }

  const allowedKeys = new Set(getAgentProposalFieldSchema(proposal).map((field) => field.key));
  const currentFields = { ...getAgentProposalFieldMap(proposal) };
  let didChange = false;

  for (const [rawKey, rawValue] of Object.entries(rawFields || {})) {
    const key = getAgentProposalFieldKeyForSchema(rawKey, allowedKeys);
    if (!key) {
      continue;
    }
    const value = formatAgentProposalFieldValue(key, rawValue);
    if (!value || currentFields[key] === value) {
      continue;
    }
    currentFields[key] = value;
    didChange = true;
  }

  proposal.fields = currentFields;
  proposal.answers = getAgentProposalAnswersFromFields(proposal);
  return didChange;
}

function mergeAgentProposalAnswers(proposal, rawAnswers = []) {
  const answers = Array.isArray(rawAnswers)
    ? rawAnswers.map((answer) => String(answer || "").trim()).filter(Boolean)
    : [];
  if (!proposal || proposal.type === "scheduled-message" || !answers.length) {
    return false;
  }

  const keys = getAgentProposalFieldKeysForAnswers(proposal, answers.length);
  const fields = {};
  answers.forEach((answer, index) => {
    const key = keys[index];
    if (key) {
      fields[key] = answer;
    }
  });
  return mergeAgentProposalFields(proposal, fields);
}

function getAgentProposalAnswersFromFields(proposal) {
  if (proposal?.type === "scheduled-message") {
    return Array.isArray(proposal.answers) ? proposal.answers : [];
  }
  const fields = getAgentProposalFieldMap(proposal);
  return getAgentProposalFieldSchema(proposal)
    .map((field) => String(fields[field.key] || "").trim())
    .filter(Boolean);
}

function syncAgentProposalFieldCompatibility(proposal) {
  if (!proposal || proposal.type === "scheduled-message") {
    return proposal;
  }
  proposal.fields = normalizeAgentFieldValues(proposal.fields);
  if (!Object.keys(proposal.fields).length && Array.isArray(proposal.answers) && proposal.answers.length) {
    mergeAgentProposalAnswers(proposal, proposal.answers);
  } else {
    proposal.answers = getAgentProposalAnswersFromFields(proposal);
  }
  return proposal;
}

function extractAgentFrequencyField(text) {
  const value = String(text || "");
  const everyMatch = value.match(/\bevery\s+(\d+)\s*(minutes?|mins?|hours?|days?|weeks?|months?)\b/i);
  if (everyMatch) {
    const amount = everyMatch[1];
    const unit = everyMatch[2].toLowerCase().replace(/^mins?$/, "minutes");
    return `every ${amount} ${unit}`;
  }
  const namedMatch = value.match(/\b(hourly|daily|weekly|monthly|every day|every week|every month)\b/i);
  return namedMatch ? namedMatch[0] : "";
}

function buildAgentMonitorIntervalFromFrequency(value = "") {
  const text = String(value || "").trim().toLowerCase();
  const everyMatch = text.match(/\bevery\s+(\d+)\s*(minutes?|mins?|hours?|hrs?|days?|weeks?|months?)\b/i);
  if (everyMatch) {
    const amount = Math.max(1, Number.parseInt(everyMatch[1], 10) || 1);
    const unit = everyMatch[2].toLowerCase();
    if (unit.startsWith("minute") || unit.startsWith("min")) {
      return { intervalMinutes: normalizeMonitorIntervalMinutes(amount), intervalDays: 1 };
    }
    if (unit.startsWith("hour") || unit.startsWith("hr")) {
      return { intervalMinutes: normalizeMonitorIntervalMinutes(amount * 60), intervalDays: 1 };
    }
    if (unit.startsWith("week")) {
      return { intervalMinutes: 0, intervalDays: normalizeMonitorIntervalDays(amount * 7) };
    }
    if (unit.startsWith("month")) {
      return { intervalMinutes: 0, intervalDays: normalizeMonitorIntervalDays(amount * 30) };
    }
    return { intervalMinutes: 0, intervalDays: normalizeMonitorIntervalDays(amount) };
  }

  if (["hourly", "every hour"].includes(text)) {
    return { intervalMinutes: 60, intervalDays: 1 };
  }
  if (["daily", "every day"].includes(text)) {
    return { intervalMinutes: 0, intervalDays: 1 };
  }
  if (["weekly", "every week"].includes(text)) {
    return { intervalMinutes: 0, intervalDays: 7 };
  }
  if (["monthly", "every month"].includes(text)) {
    return { intervalMinutes: 0, intervalDays: 30 };
  }
  return {
    intervalMinutes: DEFAULT_MONITOR_SETTINGS.intervalMinutes,
    intervalDays: DEFAULT_MONITOR_SETTINGS.intervalDays,
  };
}

function extractAgentWebMonitorTimeWindow(text) {
  const value = String(text || "");
  const monthMatch = value.match(/\b(in|during|for)\s+((?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*)(?:\s+(\d{4}))?\b/i);
  if (monthMatch) {
    return `${monthMatch[2]}${monthMatch[3] ? ` ${monthMatch[3]}` : ""}`;
  }
  const rangeMatch = value.match(/\b(next|this)\s+(week|month|quarter|year)\b/i);
  return rangeMatch ? rangeMatch[0] : "";
}

function extractAgentWebMonitorWatchQuery(text) {
  const original = String(text || "").trim();
  let value = original
    .replace(/^\s*(please\s+)?(check|search|monitor|watch|look for|find)\s+(the\s+)?(web|internet|online)?\s*/i, "")
    .replace(/\bwhen you (have|find|get) results?[\s\S]*$/i, "")
    .replace(/\bevery\s+\d+\s*(minutes?|mins?|hours?|days?|weeks?|months?)\b/ig, "")
    .replace(/\b(hourly|daily|weekly|monthly|every day|every week|every month)\b/ig, "")
    .replace(/\b(send|email|message|notify)\s+me[\s\S]*$/i, "")
    .replace(/^\s*(for|about|on)\s+/i, "")
    .replace(/\s+(and|to|with)\s*$/i, "")
    .trim();
  value = value.replace(/\s+/g, " ");
  return value || original;
}

function inferAgentProposalFieldsFromText(text, proposalType) {
  const value = String(text || "").trim();
  const fields = {};
  const deliveryChannel = normalizeAgentDeliveryChannel(value);
  const frequency = extractAgentFrequencyField(value);

  if (proposalType === "source-action") {
    const urlMatch = value.match(/https?:\/\/[^\s<>)\]}]+/i);
    if (urlMatch) {
      fields.sourceType = "url";
      fields.sourceUrl = urlMatch[0].replace(/[.,!?]+$/, "");
    } else if (/\b(?:file|document|spreadsheet|csv|pdf)\b/i.test(value)) {
      fields.sourceType = "file";
      if (agentSourceAttachment?.fileName) {
        fields.sourceFileName = agentSourceAttachment.fileName;
        fields.sourceMimeType = agentSourceAttachment.mimeType || "";
      }
    }
    if (frequency) {
      fields.frequency = frequency;
    }
    return fields;
  }

  if (proposalType === "web-monitor") {
    fields.watchQuery = extractAgentWebMonitorWatchQuery(value);
    if (frequency) {
      fields.frequency = frequency;
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    const timeWindow = extractAgentWebMonitorTimeWindow(value);
    if (timeWindow) {
      fields.timeWindow = timeWindow;
    }
    return fields;
  }

  if (proposalType === "email-digest") {
    if (/\b(gmail|google mail)\b/i.test(value)) {
      fields.mailbox = "Gmail";
    } else if (/\b(outlook|office 365|microsoft mail)\b/i.test(value)) {
      fields.mailbox = "Outlook";
    }
    if (frequency) {
      fields.schedule = frequency;
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    return fields;
  }

  if (proposalType === "calendar-summary") {
    if (/\b(calendar|meeting|meetings|agenda|appointment|appointments)\b/i.test(value)) {
      fields.calendar = "Connected calendar";
    }
    const meetingWindow = value.match(/\b(next|this|last)\s+(week|month|quarter|year)\b/i);
    if (meetingWindow) {
      fields.timeWindow = meetingWindow[0];
    } else if (/\b(today|tomorrow)\b/i.test(value)) {
      fields.timeWindow = value.match(/\b(today|tomorrow)\b/i)[0];
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    return fields;
  }

  if (proposalType === "reengagement") {
    const inactivityMatch = value.match(/\b(\d+)\s*(days?|weeks?|months?)\b/i);
    if (inactivityMatch) {
      fields.inactivityPeriod = `${inactivityMatch[1]} ${inactivityMatch[2].toLowerCase()}`;
    }
    if (frequency) {
      fields.frequency = frequency;
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    return fields;
  }

  if (proposalType === "whatsapp-replies") {
    if (/\bwhatsapp\b/i.test(value)) {
      fields.whatsappNumber = "connected WhatsApp number";
    }
    const deliveryMatch = value.match(/\b(?:send|deliver|bring|notify|alert|review)\b[\s\S]{0,40}\b(whatsapp|telegram|portal|chat|workspace)\b/i);
    const requestedDeliveryChannel = normalizeAgentDeliveryChannel(deliveryMatch?.[1] || "");
    if (requestedDeliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(requestedDeliveryChannel);
    }
    return fields;
  }

  if (/\b(calendar|agenda|appointments?)\b/i.test(value)) {
    return {};
  }

  fields.result = value;
  if (frequency) {
    fields.frequency = frequency;
  }
  if (deliveryChannel) {
    fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
  }
  return fields;
}

function updateAgentProposalSummaryFromFields(proposal) {
  if (!proposal || proposal.type === "scheduled-message") {
    return;
  }
  const fields = getAgentProposalFieldMap(proposal);
  if (proposal.type === "web-monitor" && fields.watchQuery) {
    const location = fields.location ? ` around ${fields.location}` : "";
    const frequency = fields.frequency ? ` ${fields.frequency}` : "";
    const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
    const deliveryTarget = getAgentProposalDeliveryTarget(proposal, deliveryChannel);
    const deliveryText = deliveryChannel
      ? ` and send source-backed alerts ${formatAgentDeliveryTargetSentence(deliveryChannel, deliveryTarget)}`
      : " and send source-backed alerts";
    proposal.summary = `Monitor ${fields.watchQuery}${location}${frequency}${deliveryText}.`;
  } else if (proposal.type === "email-digest" && (fields.mailbox || fields.schedule)) {
    const mailbox = fields.mailbox || "the selected mailbox";
    const schedule = fields.schedule ? ` on ${fields.schedule}` : "";
    proposal.summary = `Summarize important messages from ${mailbox}${schedule}.`;
  } else if (proposal.type === "calendar-summary" && (fields.calendar || fields.timeWindow)) {
    const calendar = fields.calendar || "the selected calendar";
    const timeWindow = fields.timeWindow ? ` for ${fields.timeWindow}` : "";
    const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
    const deliveryText = deliveryChannel
      ? ` and deliver it by ${formatAgentScheduledMessageChannel(deliveryChannel)}`
      : "";
    proposal.summary = `Summarize meetings from ${calendar}${timeWindow}${deliveryText}.`;
  } else if (proposal.type === "reengagement" && (fields.inactivityPeriod || fields.frequency)) {
    const inactivity = fields.inactivityPeriod || "the chosen quiet period";
    const frequency = fields.frequency ? ` ${fields.frequency}` : "";
    proposal.summary = `Find conversations quiet for ${inactivity}${frequency} and draft follow-ups.`;
  } else if (proposal.type === "source-action") {
    const source = fields.sourceType === "file" ? (fields.sourceFileName || "the attached file") : (fields.sourceUrl || "the selected URL");
    const frequency = fields.frequency ? ` ${fields.frequency}` : "";
    proposal.summary = `Check ${source}${frequency} and record each source snapshot.`;
  }
}

function applyAgentFieldProposalRevision(proposal, changes = {}, options = {}) {
  if (!proposal || proposal.type === "scheduled-message") {
    return false;
  }

  const patch = changes && typeof changes === "object" ? changes : {};
  let didChange = false;
  if (patch.fields && typeof patch.fields === "object" && !Array.isArray(patch.fields)) {
    didChange = mergeAgentProposalFields(proposal, patch.fields) || didChange;
  }
  if (Array.isArray(patch.answers)) {
    didChange = mergeAgentProposalAnswers(proposal, patch.answers) || didChange;
  }

  syncAgentProposalFieldCompatibility(proposal);
  normalizeAgentMonthlyBatchProposalFields(proposal);
  updateAgentProposalSummaryFromFields(proposal);
  syncAgentProposalRequiredConnection(proposal);
  if (didChange && options.bumpRevision !== false) {
    proposal.revision = Math.max(1, Number(proposal.revision || 1)) + 1;
    proposal.updatedAt = new Date().toISOString();
    proposal.status = "needs-approval";
    proposal.approved = false;
  }
  return didChange;
}

function isAgentConnectionSetupReply(value = "") {
  return /\b(?:connect|reconnect|connection|access|credential|token|setup|permission|oauth|read[- ]only)\b/i.test(
    String(value || ""),
  );
}

function pushAgentProposalNextStep(proposal, reply = "") {
  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    pushAgentRequiredConnectionSetupPrompt(proposal, requirement, reply);
    return;
  }
  const missingIndex = getAgentNextMissingQuestionIndex(proposal);
  if (missingIndex >= 0) {
    pushAgentQuestion(proposal, missingIndex, reply || getAgentDefaultProposalQuestionText(proposal, missingIndex));
    return;
  }
  const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
  const nextStepReply = deliveryChannel === "portal" && isAgentDeliveryQuestionText(reply)
    ? "I’ll add the results to Notifications. Shall I set it up?"
    : reply;
  pushAgentApprovalPrompt(proposal, nextStepReply || getAgentDefaultApprovalPromptText(proposal));
}

function getAgentQuestionFieldIndexByKey(proposal, key) {
  const schema = getAgentProposalFieldSchema(proposal);
  return schema.findIndex((field) => field?.key === key);
}

function getAgentQuestionContextText(proposal, questionText = "") {
  const fields = getAgentProposalFieldMap(proposal);
  const fieldText = Object.values(fields)
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  return [
    proposal?.requestText,
    proposal?.summary,
    ...fieldText,
    questionText,
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

const AGENT_MONTH_NAME_PATTERN = "(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)";
const AGENT_MONTHLY_BATCH_OBJECT_PATTERN = "(?:receipts?|invoices?|statements?|expenses?|bills?|transactions?|reports?|summar(?:y|ies|ize|ise)|digests?|bookkeeping|reconciliation)";
const AGENT_GENERIC_CUSTOM_TITLE_PATTERN = /^(?:custom\s+task\s+agent|workflow helper|task helper|agent helper|planning agent|task plan)$/i;
const AGENT_MONTH_NAME_INDEX = {
  jan: 0,
  january: 0,
  feb: 1,
  february: 1,
  mar: 2,
  march: 2,
  apr: 3,
  april: 3,
  may: 4,
  jun: 5,
  june: 5,
  jul: 6,
  july: 6,
  aug: 7,
  august: 7,
  sep: 8,
  sept: 8,
  september: 8,
  oct: 9,
  october: 9,
  nov: 10,
  november: 10,
  dec: 11,
  december: 11,
};

function formatAgentYearMonthValue(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function getAgentWorkspaceMonthDate(timeZone = getWorkspaceTimeZone()) {
  const today = getAgentWorkspaceDateParts(timeZone);
  return new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
}

function shiftAgentMonth(date, offset = 0) {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + Number(offset || 0), 1));
}

function parseAgentManualRunMonthValue(value, timeZone = getWorkspaceTimeZone()) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const numericMatch = text.match(/\b(\d{4})-(\d{1,2})\b/);
  if (numericMatch) {
    const year = Number.parseInt(numericMatch[1], 10);
    const month = Number.parseInt(numericMatch[2], 10);
    if (Number.isInteger(year) && month >= 1 && month <= 12) {
      return `${year}-${String(month).padStart(2, "0")}`;
    }
  }

  const monthMatch = text.match(/\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:\s+(\d{4}))?\b/i);
  if (!monthMatch) {
    return "";
  }

  const monthIndex = AGENT_MONTH_NAME_INDEX[String(monthMatch[1] || "").toLowerCase()];
  if (!Number.isInteger(monthIndex)) {
    return "";
  }
  const workspaceMonth = getAgentWorkspaceMonthDate(timeZone);
  const year = Number.parseInt(monthMatch[2] || "", 10) || workspaceMonth.getUTCFullYear();
  return formatAgentYearMonthValue(new Date(Date.UTC(year, monthIndex, 1)));
}

function formatAgentPreviousMonth(options) {
  const previousMonth = shiftAgentMonth(getAgentWorkspaceMonthDate(), -1);
  return new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(previousMonth);
}

// The receipts example names last month, so it has to be recomputed rather
// than hardcoded. The label stays short ("July 26") while the prompt spells
// the year out: both month parsers accept only a four-digit year and
// otherwise assume the current one, which would read "December 26" typed in
// January as December of the wrong year.
function updateAgentReceiptsQuickAction() {
  const button = elements.agentReceiptsQuickAction;
  if (!button) {
    return;
  }
  button.textContent = `Pull all my receipts from ${formatAgentPreviousMonth({ month: "long", year: "2-digit" })}`;
  button.dataset.agentPrompt = `Pull all my receipts from ${formatAgentPreviousMonth({ month: "long", year: "numeric" })}.`;
}

function formatAgentManualRunMonthLabel(value, fallback = "") {
  const normalizedValue = parseAgentManualRunMonthValue(value) || parseAgentManualRunMonthValue(fallback);
  const match = normalizedValue.match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return String(value || fallback || "").trim();
  }
  const date = new Date(Date.UTC(Number.parseInt(match[1], 10), Number.parseInt(match[2], 10) - 1, 1));
  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}

function getAgentProposalManualRunMonthValue(proposal, draft = {}) {
  const fields = getAgentProposalFieldMap(proposal);
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const settings = getAgentProposalExecutionSettings(proposal);
  const candidates = [
    draft.manualRunMonth,
    fields.manualRunMonth,
    details.manualRunMonth,
    details.reportingMonth,
    proposal?.executionPlan?.manualRunMonth,
    proposal?.executionPlan?.reportingMonth,
    settings.manualRunMonth,
    settings.reportingMonth,
    fields.result,
    proposal?.requestText,
  ];
  for (const candidate of candidates) {
    const value = parseAgentManualRunMonthValue(candidate);
    if (value) {
      return value;
    }
  }
  return formatAgentYearMonthValue(getAgentWorkspaceMonthDate());
}

// "All mailboxes" is first and is the default, so an action created before
// there was a choice keeps reading everything.
function getAgentMailboxAccountOptions(currentValue = "") {
  const options = [{ value: "", label: "All mailboxes" }];
  for (const connection of getConnectedEmailConnections()) {
    const name = getEmailConnectionName(connection);
    const provider = EMAIL_PROVIDER_LABELS[getEmailConnectionProvider(connection)] || "Email";
    options.push({ value: name, label: `${name} (${provider})` });
  }
  const current = normalizeText(currentValue);
  // A mailbox that has since been disconnected still shows, so the action does
  // not look like it reads everything when it would actually fail.
  if (current && !options.some((option) => option.value === current)) {
    options.push({ value: current, label: `${current} (not connected)` });
  }
  return options;
}

// A calendar action reads one calendar per tag. Five is well past what anyone
// watches at once, and it caps how many provider reads one run makes.
const AGENT_CALENDAR_TAG_LIMIT = 5;
const AGENT_CALENDAR_TAG_EMAIL_PATTERN = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]{2,}$/;
// The connected account's own calendar: the one ID in a saved field that is not
// an address. Google accepts the same alias, so it keeps meaning the right
// calendar even if the address behind the connection changes.
const AGENT_CALENDAR_PRIMARY_ID = "primary";

function isAgentCalendarAddressTag(value) {
  return AGENT_CALENDAR_TAG_EMAIL_PATTERN.test(String(value || "").trim());
}

// The tag for the connected account. Older actions saved free text here
// ("connected Google Calendar", "Connected calendar"); the connection itself is
// the honest source, so that text is dropped and this replaces it.
function getConnectedCalendarTagLabel() {
  const connection = getPlatformConnectionByPlatform("calendar");
  if (!connection || connection.connectionStatus === "disconnected") {
    return "";
  }
  const address = normalizeText(connection.accountAddress);
  return address ? `Google Calendar (${address})` : "Google Calendar";
}

// Only addresses survive from the saved value. Anything else named the
// connected account's own calendar, which has its own ID above.
function getAgentCalendarAddressTags(value) {
  const tags = [];
  for (const entry of String(value || "").split(/[,\n;]+/)) {
    const address = entry.trim();
    if (!isAgentCalendarAddressTag(address)) {
      continue;
    }
    if (!tags.some((tag) => tag.toLowerCase() === address.toLowerCase())) {
      tags.push(address);
    }
  }
  return tags;
}

// The saved field is a list of calendar IDs. Anything that is not an address
// means the connected account's own calendar, which is how an action written
// before the picker existed - it saved a label such as "Google Calendar" - keeps
// reading exactly what it always read. This mirrors parse_calendar_ids on the
// server: the two have to agree, or the editor shows one thing and the run
// reads another.
function getAgentCalendarSelectionIds(value) {
  const entries = Array.isArray(value) ? value : String(value || "").split(/[,\n;]+/);
  const ids = [];
  for (const entry of entries) {
    const text = String(entry || "").trim();
    if (!text) {
      continue;
    }
    const id = isAgentCalendarAddressTag(text) ? text.toLowerCase() : AGENT_CALENDAR_PRIMARY_ID;
    if (!ids.includes(id)) {
      ids.push(id);
    }
  }
  return ids.slice(0, AGENT_CALENDAR_TAG_LIMIT);
}

function formatAgentCalendarFieldValue(value) {
  return getAgentCalendarSelectionIds(value).join(", ");
}

// Every open Calendars field, so the ones on screen redraw when the calendars
// inside the account finish loading. A field whose editor has been closed is
// dropped rather than drawn into a detached form.
const agentCalendarFieldRenderers = new Set();

function renderOpenAgentCalendarFields() {
  for (const renderer of [...agentCalendarFieldRenderers]) {
    // A field is built before its form reaches the page, so "not on the page"
    // only means closed once it has been there.
    if (renderer.field.isConnected) {
      renderer.attached = true;
    } else if (renderer.attached) {
      agentCalendarFieldRenderers.delete(renderer);
      continue;
    }
    renderer.render();
  }
}

function resetAgentCalendarSources() {
  state.agentCalendarSources = [];
  state.agentCalendarSourcesSignature = "";
  state.agentCalendarSourcesLoading = false;
  state.agentCalendarSourcesLoadedAt = 0;
  state.agentCalendarSourcesError = "";
}

// Which calendar connections are in play. The cache is keyed on this so
// connecting or disconnecting an account reloads its calendars, and merely
// reopening an action editor does not.
function getAgentCalendarConnectionSignature() {
  return state.platformConnections
    .filter((connection) => connection?.platform === "calendar")
    .map((connection) => `${normalizeText(connection.id)}:${normalizeText(connection.connectionStatus)}`)
    .sort()
    .join("|");
}

function normalizeAgentCalendarSource(source) {
  const calendars = Array.isArray(source?.calendars) ? source.calendars : [];
  return {
    connectionId: normalizeText(source?.connectionId),
    platform: normalizeText(source?.platform) || "calendar",
    label: normalizeText(source?.label) || "Calendar",
    accountAddress: normalizeText(source?.accountAddress),
    status: normalizeText(source?.status) || "ok",
    message: normalizeText(source?.message),
    calendars: calendars
      .map((calendar) => ({
        id: normalizeText(calendar?.id),
        label: normalizeText(calendar?.label) || normalizeText(calendar?.id),
        primary: Boolean(calendar?.primary),
      }))
      .filter((calendar) => calendar.id),
  };
}

function getAgentCalendarSourceHeading(source) {
  return source.accountAddress ? `${source.label} (${source.accountAddress})` : source.label;
}

async function refreshAgentCalendarSources(options = {}) {
  const signature = getAgentCalendarConnectionSignature();
  if (!isSignedIn() || !signature) {
    resetAgentCalendarSources();
    return [];
  }
  const isCached = state.agentCalendarSourcesLoadedAt > 0 && state.agentCalendarSourcesSignature === signature;
  if (state.agentCalendarSourcesLoading || (isCached && !options.force)) {
    return state.agentCalendarSources;
  }

  state.agentCalendarSourcesLoading = true;
  state.agentCalendarSourcesError = "";
  renderOpenAgentCalendarFields();
  try {
    const response = await apiRequest("/api/platform-connections/calendars", { timeoutMs: 15000 });
    state.agentCalendarSources = Array.isArray(response.sources)
      ? response.sources.map(normalizeAgentCalendarSource)
      : [];
  } catch (error) {
    // A picker that cannot load falls back to typing an address, so this is a
    // note beside the field rather than a failure of the editor.
    state.agentCalendarSources = [];
    state.agentCalendarSourcesError = normalizeText(error?.message)
      || "Couldn’t load the calendars in this account.";
  } finally {
    state.agentCalendarSourcesSignature = signature;
    state.agentCalendarSourcesLoadedAt = Date.now();
    state.agentCalendarSourcesLoading = false;
    renderOpenAgentCalendarFields();
  }
  return state.agentCalendarSources;
}

function getAgentManualRunMonthOptions(currentValue = "") {
  const baseMonth = getAgentWorkspaceMonthDate();
  const options = [];
  for (let offset = 0; offset > -13; offset -= 1) {
    const value = formatAgentYearMonthValue(shiftAgentMonth(baseMonth, offset));
    options.push({ value, label: formatAgentManualRunMonthLabel(value) });
  }
  const normalizedCurrentValue = parseAgentManualRunMonthValue(currentValue);
  if (normalizedCurrentValue && !options.some((option) => option.value === normalizedCurrentValue)) {
    options.unshift({
      value: normalizedCurrentValue,
      label: formatAgentManualRunMonthLabel(normalizedCurrentValue),
    });
  }
  return options;
}

function replaceAgentMonthlyBatchWindowInResult(value, targetLabel) {
  const text = String(value || "")
    .trim()
    .replace(/\bthe\s+the\s+((?:selected|requested|previous|last)\s+month)\b/i, "the $1");
  const target = String(targetLabel || "").trim();
  if (!text || !target) {
    return text;
  }
  if (text.toLowerCase().includes(target.toLowerCase())) {
    return text;
  }

  const namedMonthWindow = new RegExp(`\\b(?:from|for|during|in)\\s+${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\b`, "i");
  if (namedMonthWindow.test(text)) {
    return text.replace(namedMonthWindow, `for ${target}`);
  }

  const leadingMonthObject = new RegExp(`\\b${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\s+(${AGENT_MONTHLY_BATCH_OBJECT_PATTERN})\\b`, "i");
  if (leadingMonthObject.test(text)) {
    return text.replace(leadingMonthObject, `${target} $1`);
  }

  if (/\b(?:the\s+)?(?:selected|requested|previous|last)\s+month\b/i.test(text)) {
    return text.replace(/\b(?:the\s+)?(?:selected|requested|previous|last)\s+month\b/i, target);
  }

  return `${text.replace(/[.?!]+$/, "")} for ${target}`;
}

function getAgentMonthlyBatchResultText(proposal, draft = {}) {
  const rawResult = String(draft.result || getAgentProposalFieldValue(proposal, "result") || proposal?.requestText || "").trim();
  if (!agentContextSuggestsMonthlyBatchTask(proposal, rawResult)) {
    return rawResult;
  }

  const draftFrequency = String(draft.frequency || "").trim().toLowerCase();
  const isManual = draftFrequency ? draftFrequency === "manual" : getAgentProposalManualOnly(proposal);
  const targetLabel = isManual
    ? formatAgentManualRunMonthLabel(getAgentProposalManualRunMonthValue(proposal, draft))
    : "the previous month";
  return replaceAgentMonthlyBatchWindowInResult(rawResult, targetLabel);
}

function normalizeAgentMonthlyBatchProposalFields(proposal, draft = {}) {
  if (!proposal || proposal.type === "scheduled-message" || !agentContextSuggestsMonthlyBatchTask(proposal, draft.result || "")) {
    return false;
  }

  const fields = { ...getAgentProposalFieldMap(proposal) };
  const draftFrequency = String(draft.frequency || "").trim().toLowerCase();
  const isManual = draftFrequency ? draftFrequency === "manual" : getAgentProposalManualOnly(proposal);
  const monthValue = getAgentProposalManualRunMonthValue(proposal, draft);
  const resultText = getAgentMonthlyBatchResultText(proposal, {
    ...draft,
    manualRunMonth: monthValue,
    result: draft.result || fields.result,
  });
  const outputFolder = getAgentMonthlyBatchOutputFolder(proposal, {
    ...draft,
    manualRunMonth: isManual ? monthValue : "",
    result: resultText || draft.result || fields.result,
  });
  let didChange = false;
  if (isManual && monthValue && fields.manualRunMonth !== monthValue) {
    fields.manualRunMonth = monthValue;
    didChange = true;
  } else if (!isManual && fields.manualRunMonth) {
    delete fields.manualRunMonth;
    didChange = true;
  }
  if (resultText && fields.result !== resultText) {
    fields.result = resultText;
    didChange = true;
  }
  if (outputFolder && fields.outputFolder !== outputFolder) {
    fields.outputFolder = outputFolder;
    didChange = true;
  }
  if (didChange) {
    proposal.fields = normalizeAgentFieldValues(fields);
    proposal.answers = getAgentProposalAnswersFromFields(proposal);
    proposal.updatedAt = new Date().toISOString();
  }
  return didChange;
}

function isAgentRunModeQuestionText(value = "") {
  const text = String(value || "").toLowerCase();
  return (
    /\b(?:just once|one[-\s]?time|run once|once)\b/.test(text)
    && /\b(?:schedule|repeat|recur|recurring|again)\b/.test(text)
  );
}

function isAgentFrequencyQuestionText(value = "") {
  return /\b(?:how often|frequency|cadence|daily|weekly|monthly|hourly|every\s+\d+|every day|every week|every month)\b/i.test(String(value || ""));
}

function isAgentDeliveryQuestionText(value = "") {
  const text = String(value || "");
  return (
    /\bwhere\b[\s\S]{0,100}\b(?:send|deliver|notify|alert|bring|review)\b/i.test(text)
    || /\b(?:which|what)\s+(?:delivery\s+)?channel\b/i.test(text)
    || /\bhow\s+should\s+i\s+(?:let you know|notify|send|deliver|bring)\b/i.test(text)
  );
}

function isAgentMonthlyBatchCadenceConfirmationText(value = "") {
  const text = String(value || "").toLowerCase();
  return (
    /\bmonthly\b/.test(text)
    && /\b(?:beginning|start|first)\b/.test(text)
    && /\b(?:previous|last)\s+month\b/.test(text)
    && /\b(?:ok|okay|work|confirm|right)\b/.test(text)
  );
}

function agentContextSuggestsMonthlyBatchTask(proposal, questionText = "") {
  const text = getAgentQuestionContextText(proposal, questionText);
  const hasBatchObject = new RegExp(`\\b${AGENT_MONTHLY_BATCH_OBJECT_PATTERN}\\b`).test(text);
  const hasRelativeMonthlyWindow = /\b(?:monthly|month|last month|this month|next month|previous month|current month)\b/.test(text);
  const hasNamedMonthWindow = new RegExp(`\\b(?:from|for|during|in)\\s+${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\b`).test(text)
    || new RegExp(`\\b${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\s+(?:receipts?|invoices?|statements?|expenses?|bills?|transactions?|reports?)\\b`).test(text);
  const hasMonthlyWindow = hasRelativeMonthlyWindow || hasNamedMonthWindow;
  const hasBatchVerb = /\b(?:collect|pull|gather|fetch|find|search|export|summarize|summarise|prepare|get|send)\b/.test(text);
  return hasBatchObject && hasMonthlyWindow && hasBatchVerb;
}

function isAgentProposalCustomGoogleBatchRunner(proposal) {
  return proposal?.type === "custom"
    && agentContextSuggestsMonthlyBatchTask(proposal, getAgentProposalFieldValue(proposal, "result"));
}

function getAgentMonthlyBatchScheduleActions(includeOneTime = false, options = {}) {
  const cadenceValue = "monthly, at the beginning of each month for the previous month";
  if (options.confirmCadence) {
    return [
      createAgentAction("choose", "Yes, monthly", cadenceValue, "primary"),
      createAgentAction("choose", "Change timing", "change the timing"),
    ];
  }

  const actions = includeOneTime
    ? [createAgentAction("choose", "Just once", "just once for the requested month")]
    : [];
  actions.push(createAgentAction(
    "choose",
    includeOneTime ? "Every month" : "Monthly",
    cadenceValue,
  ));
  return actions;
}

function filterAgentQuestionActions(actions) {
  const normalizedActions = Array.isArray(actions) ? actions.filter(Boolean) : [];
  return normalizedActions.length > 1 ? normalizedActions : [];
}

function getAgentContextualQuestionActions(proposal, questionIndex = 0, questionText = "") {
  if (proposal?.type === "scheduled-message") {
    return [];
  }
  const schema = getAgentProposalFieldSchema(proposal);
  const field = schema[Math.max(0, Number(questionIndex || 0))];
  const isMonthlyBatchTask = agentContextSuggestsMonthlyBatchTask(proposal, questionText);

  if (isAgentRunModeQuestionText(questionText)) {
    return isMonthlyBatchTask
      ? getAgentMonthlyBatchScheduleActions(true)
      : [
        createAgentAction("choose", "Just once", "just once"),
        createAgentAction("choose", "On a schedule", "on a schedule"),
      ];
  }

  if (field?.key === "frequency" && isMonthlyBatchTask) {
    if (isAgentMonthlyBatchCadenceConfirmationText(questionText)) {
      return getAgentMonthlyBatchScheduleActions(false, { confirmCadence: true });
    }
    return [];
  }

  return [];
}

function getAgentQuestionFieldIndexFromText(proposal, questionText = "") {
  if (proposal?.type === "scheduled-message") {
    return -1;
  }
  const text = String(questionText || "").toLowerCase();
  const findKey = (key) => getAgentQuestionFieldIndexByKey(proposal, key);

  if (isAgentRunModeQuestionText(text)) {
    const frequencyIndex = findKey("frequency");
    if (frequencyIndex >= 0) {
      return frequencyIndex;
    }
  }

  // Check delivery wording before frequency wording. A delivery question
  // can mention a cadence (for example, "after the monthly run"), but its
  // answer choices must still be channels rather than Monthly/Weekly.
  if (isAgentDeliveryQuestionText(text)) {
    const deliveryIndex = findKey("deliveryChannel");
    if (deliveryIndex >= 0) {
      return deliveryIndex;
    }
  }

  if (isAgentFrequencyQuestionText(text)) {
    const frequencyIndex = findKey("frequency");
    if (frequencyIndex >= 0) {
      return frequencyIndex;
    }
  }

  if (/\b(?:mailbox|inbox|gmail|outlook|email account|mail account)\b/.test(text)) {
    const mailboxIndex = findKey("mailbox");
    if (mailboxIndex >= 0) {
      return mailboxIndex;
    }
  }

  if (/\b(?:source|where to look|where should i search)\b/.test(text)) {
    const sourceIndex = findKey("sourceType");
    if (sourceIndex >= 0) {
      return sourceIndex;
    }
    const mailboxIndex = findKey("mailbox");
    if (mailboxIndex >= 0) {
      return mailboxIndex;
    }
  }

  if (/\bcalendar\b/.test(text)) {
    const calendarIndex = findKey("calendar");
    if (calendarIndex >= 0) {
      return calendarIndex;
    }
  }

  if (/\b(?:date range|time range|which date|what date|when|today|tomorrow|this week|next week|this month|next month)\b/.test(text)) {
    const timeWindowIndex = findKey("timeWindow");
    if (timeWindowIndex >= 0) {
      return timeWindowIndex;
    }
  }

  return -1;
}

function getAgentQuestionActionFieldIndex(proposal, questionIndex = 0, questionText = "", questionFieldKey = "") {
  const explicitIndex = getAgentQuestionFieldIndexByKey(proposal, questionFieldKey);
  const inferredIndex = getAgentQuestionFieldIndexFromText(proposal, questionText);
  // Prefer the wording when metadata and visible text disagree. This keeps
  // answer chips tied to the question the user can actually read, including
  // messages persisted before fieldKey metadata was corrected.
  if (inferredIndex >= 0) {
    return inferredIndex;
  }
  if (explicitIndex >= 0) {
    return explicitIndex;
  }
  return Math.max(0, Number(questionIndex || 0));
}

function getAgentQuestionActions(proposal, questionIndex = 0, questionText = "", questionFieldKey = "") {
  const index = getAgentQuestionActionFieldIndex(proposal, questionIndex, questionText, questionFieldKey);

  if (proposal?.type === "scheduled-message") {
    const questionKey = proposal.questionKeys?.[index] || "";
    if (questionKey === "channel") {
      return [
        createAgentAction("choose", "WhatsApp"),
        createAgentAction("choose", "Email"),
        createAgentAction("choose", "Telegram"),
      ];
    }
    if (questionKey === "time") {
      return [
        createAgentAction("choose", "12:40"),
        createAgentAction("choose", "9:00 AM"),
      ];
    }
    return [];
  }

  const field = getAgentProposalFieldSchema(proposal)[index];
  if ((isAgentRunModeQuestionText(questionText) || isAgentFrequencyQuestionText(questionText)) && field?.key !== "frequency") {
    return [];
  }
  const contextualActions = getAgentContextualQuestionActions(proposal, index, questionText);
  if (contextualActions.length) {
    return filterAgentQuestionActions(contextualActions);
  }
  const fieldActions = Array.isArray(field?.actions)
    ? field.actions.map((action) => (
      typeof action === "string"
        ? createAgentAction("choose", action)
        : createAgentAction("choose", action.label, action.value || action.label, action.tone || "secondary")
    ))
    : [];
  return filterAgentQuestionActions(fieldActions);
}

function getAgentApprovalActions(proposal) {
  return [
    createAgentAction("approve-proposal", "Set it up", proposal?.id || "", "primary"),
    createAgentAction("request-change", "Change something", proposal?.id || ""),
  ];
}

function shouldAttachAgentApprovalActions(proposal, messageText = "") {
  if (!proposal) {
    return false;
  }
  const text = String(messageText || "").toLowerCase();
  const asksToConfirmSetup = (
    /\bconfirm\b/.test(text)
    || /\bgo ahead\b/.test(text)
    || /\bproceed\b/.test(text)
    || /\bset\s+(?:it|this|that|the setup)\s+up\b/.test(text)
  );
  const offersChangePath = (
    /\bchange\b/.test(text)
    || /\badjust\b/.test(text)
    || /\bedit\b/.test(text)
    || /\bmodify\b/.test(text)
  );
  return !(asksToConfirmSetup && offersChangePath);
}

function getAgentApprovalPromptActions(proposal, messageText = "") {
  return shouldAttachAgentApprovalActions(proposal, messageText)
    ? getAgentApprovalActions(proposal)
    : [];
}

function pushAgentQuestion(proposal, questionIndex = 0, questionOverride = "") {
  const index = Math.max(0, Number(questionIndex || 0));
  const messageText = String(questionOverride || "").trim();
  if (!messageText) {
    return null;
  }
  const requestedFieldKey = proposal?.type === "scheduled-message"
    ? (proposal.questionKeys?.[index] || "")
    : (getAgentProposalFieldSchema(proposal)[index]?.key || "");
  const actionIndex = getAgentQuestionActionFieldIndex(proposal, index, messageText, requestedFieldKey);
  proposal.questionIndex = actionIndex;
  const field = proposal?.type === "scheduled-message"
    ? null
    : getAgentProposalFieldSchema(proposal)[actionIndex] || null;
  return pushAgentMessage("assistant", messageText, {
    kind: "question",
    proposalId: proposal.id,
    questionIndex: actionIndex,
    fieldKey: field?.key || "",
    actions: getAgentQuestionActions(proposal, actionIndex, messageText, field?.key || requestedFieldKey),
  });
}

function pushAgentApprovalPrompt(proposal, reply = "") {
  const messageText = String(reply || "").trim();
  if (!messageText) {
    return null;
  }
  return pushAgentMessage("assistant", messageText, {
    kind: "approval",
    proposalId: proposal.id,
    proposalRevision: Math.max(1, Number(proposal.revision || 1)),
    actions: getAgentApprovalPromptActions(proposal, messageText),
  });
}

function persistAgentWorkspace(status = "Agent workspace saved.") {
  persistClientState();
  setStatus(status);
}

function getProposalReadinessLabel(proposal) {
  if (!proposal) {
    return "Ready";
  }

  if (proposal.approved) {
    return "Approved";
  }

  if (proposal.status === "scheduling") {
    return "Scheduling";
  }

  if (proposal.status === "revising") {
    return "Updating plan";
  }

  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    return "Needs setup";
  }

  if (proposal.missingCredential) {
    return "Needs credential";
  }

  const feature = proposal.relatedFeatureId ? getFeatureById(proposal.relatedFeatureId) : null;
  if (feature && isFeatureSetupComplete(feature)) {
    return "Skill ready";
  }

  return "Needs approval";
}

function getProposalSetupLabel(proposal) {
  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    return requirement.actionLabel || "Open setup";
  }

  if (!proposal?.relatedFeatureId) {
    return "Review skills";
  }

  const feature = getFeatureById(proposal.relatedFeatureId);
  if (!feature) {
    return proposal.setupActionLabel || "Review setup";
  }

  if (isFeatureSetupComplete(feature)) {
    return "Open active skill";
  }

  return proposal.setupActionLabel || "Open setup";
}

function getAgentRequiredConnectionCalloutText(requirement) {
  if (!requirement) {
    return "";
  }
  if (requirement.id === "google-workspace") {
    return "Google needs to be connected with Gmail or Drive read access before I can create this action. No API key is needed.";
  }
  return `${requirement.missingCredential} is required before I can create this action.`;
}

function normalizeAgentErrorTechnicalInfo(technical = {}) {
  const source = technical && typeof technical === "object" ? technical : {};
  const rawStatus = Number(source.status || 0);
  const status = Number.isInteger(rawStatus) && rawStatus >= 100 && rawStatus <= 599 ? rawStatus : 0;
  const rawUpstreamStatus = Number(source.upstreamStatus || 0);
  const upstreamStatus = Number.isInteger(rawUpstreamStatus)
    && rawUpstreamStatus >= 100
    && rawUpstreamStatus <= 599
    ? rawUpstreamStatus
    : 0;
  const rawCode = String(source.code || "").trim().toLowerCase();
  const code = /^[a-z0-9_-]{1,80}$/.test(rawCode) ? rawCode : "request_failed";
  const rawProviderCode = String(source.providerCode || "").trim().toLowerCase();
  const providerCode = /^[a-z0-9_-]{1,80}$/.test(rawProviderCode) ? rawProviderCode : "";
  const occurredAt = String(source.occurredAt || "").trim();
  return {
    endpoint: "/api/agent/turn",
    status,
    upstreamStatus,
    code,
    providerCode,
    occurredAt: /^\d{4}-\d{2}-\d{2}T/.test(occurredAt) ? occurredAt : "",
  };
}

function getAgentErrorTechnicalInfo(error) {
  const isTimedOut = isAbortError(error);
  return normalizeAgentErrorTechnicalInfo({
    status: error?.status,
    upstreamStatus: error?.payload?.upstreamStatus,
    providerCode: error?.payload?.providerCode,
    code: error?.payload?.error || (isTimedOut ? "client_timeout" : "request_failed"),
    occurredAt: new Date().toISOString(),
  });
}

function getAgentErrorGuidance(technical) {
  const details = normalizeAgentErrorTechnicalInfo(technical);
  if (details.code === "agent_billing_required") {
    if (details.providerCode === "credit_balance_exhausted") {
      return "OpenAI reported that this project’s prepaid credit balance is exhausted. If you just added funds, refresh billing and confirm the server is using the same project before retrying.";
    }
    if (["organization_spend_limit_exceeded", "project_spend_limit_exceeded"].includes(details.providerCode)) {
      return "OpenAI reported a spend limit, not necessarily an empty balance. Check the project and organization limits, then retry.";
    }
    if (details.providerCode === "organization_usage_limit_exceeded") {
      return "OpenAI reported that the organization usage limit was reached. Check the organization limit or request an increase, then retry.";
    }
    if (details.providerCode === "insufficient_quota") {
      return "OpenAI returned a legacy quota or billing rejection. This does not prove a recent payment failed to apply; refresh billing and retry, then check the project and API key if it persists.";
    }
    return "OpenAI reported a billing restriction for this project. Refresh billing and retry; this message does not by itself prove that your funds are missing.";
  }
  if (details.code === "agent_quota_unclear") {
    return "OpenAI returned a quota or usage-limit response, but the exact cause was not identified. This does not prove that your funds are missing. Refresh billing and retry; if it continues, check credits, spend limits, and rate limits.";
  }
  if (details.code === "agent_configuration_error") {
    return "The server is missing a valid OpenAI configuration. Check the API key, model name, and deployment environment variables.";
  }
  if (details.code === "agent_authentication_error") {
    return "OpenAI rejected its credentials. Check the server API key and permissions.";
  }
  if (details.code === "agent_rate_limited") {
    return "OpenAI is temporarily rate-limited. Wait briefly before retrying.";
  }
  if (details.code === "agent_network_error") {
    return "The server could not reach OpenAI. Check service health and network access, then retry.";
  }
  if (details.code === "secret_in_chat") {
    return "Use the secure connection form for credentials. Do not paste tokens or API keys into chat.";
  }
  if (details.status === 401 || details.status === 403) {
    return "The session may have expired or may not have permission to use this endpoint. Sign in again, then retry.";
  }
  if (details.status === 503 || details.code === "agent_unavailable") {
    return "The server could not reach the model service or its configuration is unavailable. Check the server logs and the model/API configuration, then retry.";
  }
  if (details.status === 502 || details.code === "invalid_agent_turn") {
    return "The model returned a response the portal could not validate. Check the server response logs and the agent-turn response schema.";
  }
  if (details.code === "client_timeout") {
    return "The browser waited too long for a response. The server may still be processing the request; check service health and server logs before retrying.";
  }
  if (!details.status || details.code === "request_failed") {
    return "The request may have timed out or the network may have dropped. Check connectivity and service health, then retry.";
  }
  return "Retry once. If it keeps failing, inspect the server logs for this endpoint, status, and error code.";
}

function createAgentErrorHelpBody(technical = {}) {
  const details = normalizeAgentErrorTechnicalInfo(technical);
  const body = document.createElement("div");
  body.className = "agent-error-help";

  const intro = document.createElement("p");
  intro.className = "agent-error-help-intro";
  intro.textContent = "The request failed before any task was created or sent. These safe diagnostics can help locate the problem.";

  const detailList = document.createElement("dl");
  detailList.className = "agent-error-help-details";
  const rows = [
    ["Endpoint", details.endpoint],
    ["HTTP status", details.status ? String(details.status) : "Not returned"],
    ...(details.upstreamStatus ? [["Upstream status", String(details.upstreamStatus)]] : []),
    ...(details.providerCode ? [["Provider code", details.providerCode]] : []),
    ["Error code", details.code],
    ["Time", details.occurredAt || "Not recorded"],
  ];
  for (const [label, value] of rows) {
    const row = document.createElement("div");
    row.className = "agent-error-help-detail";
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    description.textContent = value;
    row.append(term, description);
    detailList.append(row);
  }

  const guidance = document.createElement("div");
  guidance.className = "agent-error-help-guidance";
  const guidanceTitle = document.createElement("strong");
  guidanceTitle.textContent = "What to check";
  const guidanceText = document.createElement("p");
  guidanceText.textContent = getAgentErrorGuidance(details);
  guidance.append(guidanceTitle, guidanceText);

  const note = document.createElement("p");
  note.className = "agent-error-help-note";
  note.textContent = "No credentials or raw server response are shown here.";

  body.append(intro, detailList, guidance, note);
  return body;
}

function openAgentErrorHelp(technical = {}, returnFocus = null) {
  openAuthAlert(
    "Request details",
    "Use the diagnostics below to understand why this request stopped.",
    {
      eyebrow: "Technical details",
      icon: "i",
      tone: "progress",
      bodyNode: createAgentErrorHelpBody(technical),
      buttonLabel: "Close",
      returnFocus,
    },
  );
}

function createAgentConnectionSetupCard(message) {
  const setup = message?.metadata?.connectionSetup && typeof message.metadata.connectionSetup === "object"
    ? message.metadata.connectionSetup
    : {};
  const card = document.createElement("section");
  card.className = "agent-message-connection-card";
  card.setAttribute("aria-label", "WhatsApp setup details");

  const eyebrow = document.createElement("span");
  eyebrow.className = "agent-message-connection-card-eyebrow";
  eyebrow.textContent = "WhatsApp setup";

  const title = document.createElement("h3");
  title.className = "agent-message-connection-card-title";
  title.textContent = setup.platformConnected ? "Finish the Business connection" : "Connect WhatsApp Business";

  const copy = document.createElement("p");
  copy.className = "agent-message-connection-card-copy";
  copy.textContent = setup.platformConnected
    ? "The WhatsApp app is connected, but incoming-message monitoring uses a separate WhatsApp Business connection."
    : "Add these details in the secure setup form so I can monitor incoming messages.";

  const list = document.createElement("ul");
  list.className = "agent-message-connection-card-list";
  const missingFields = Array.isArray(setup.missingFields) ? setup.missingFields : [];
  for (const field of missingFields) {
    const item = document.createElement("li");
    item.className = "agent-message-connection-card-item";
    item.textContent = String(field?.label || "Required connection detail");
    list.append(item);
  }
  if (!missingFields.length) {
    const item = document.createElement("li");
    item.className = "agent-message-connection-card-item";
    item.textContent = "Verified WhatsApp Business connection";
    list.append(item);
  }

  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-message-connection-card-button primary-button";
  button.textContent = "Open WhatsApp setup";
  button.dataset.agentMessageAction = "open-whatsapp-setup";
  button.dataset.agentActionValue = "whatsapp";
  button.dataset.agentActionMessage = message.id;
  const agent = getAgentWorkspace();
  button.disabled = Boolean(agentTurnBusy || areAgentMessageActionsResolved(message, agent.messages));

  const note = document.createElement("p");
  note.className = "agent-message-connection-card-note";
  note.textContent = "Your access token stays in the secure setup form and is never shown in chat.";

  card.append(eyebrow, title, copy, list, button, note);
  return card;
}

function getAgentWhatsAppApprovalForMessage(message) {
  return message?.metadata?.approval && typeof message.metadata.approval === "object"
    ? message.metadata.approval
    : {};
}

function createAgentWhatsAppReplyCard(message) {
  const approval = getAgentWhatsAppApprovalForMessage(message);
  const status = String(approval.status || message.metadata?.approvalStatus || "pending").trim().toLowerCase();
  const senderName = String(approval.sender_name || approval.senderName || approval.sender_wa_id || "WhatsApp contact").trim();
  const incomingText = String(approval.latest_message || approval.incoming_text || approval.message || "").trim();
  const suggestedReply = String(approval.suggested_reply || approval.suggestedReply || "").trim();

  const card = document.createElement("section");
  card.className = `agent-message-whatsapp-card is-${status || "pending"}`;
  card.setAttribute("aria-label", `WhatsApp reply from ${senderName}`);

  const header = document.createElement("div");
  header.className = "agent-message-whatsapp-card-head";
  const eyebrow = document.createElement("span");
  eyebrow.className = "agent-message-whatsapp-card-eyebrow";
  eyebrow.textContent = "WhatsApp reply";
  const title = document.createElement("h3");
  title.className = "agent-message-whatsapp-card-title";
  title.textContent = senderName;
  const statusLabel = document.createElement("span");
  statusLabel.className = "agent-message-whatsapp-card-status";
  statusLabel.setAttribute("role", "status");
  statusLabel.textContent = status === "sent" ? "Sent" : status === "skipped" ? "Skipped" : "Needs review";
  header.append(eyebrow, title, statusLabel);

  const incomingLabel = document.createElement("span");
  incomingLabel.className = "agent-message-whatsapp-card-label";
  incomingLabel.textContent = "They wrote";
  const incoming = document.createElement("p");
  incoming.className = "agent-message-whatsapp-card-incoming";
  incoming.textContent = incomingText || "New WhatsApp message received.";

  const replyLabel = document.createElement("label");
  replyLabel.className = "agent-message-whatsapp-card-label";
  replyLabel.textContent = "Suggested reply";
  const textarea = document.createElement("textarea");
  textarea.className = "agent-message-whatsapp-card-textarea";
  textarea.id = `agent-whatsapp-reply-${message.id}`;
  replyLabel.htmlFor = textarea.id;
  textarea.rows = 3;
  textarea.value = suggestedReply;
  textarea.setAttribute("aria-label", `Suggested reply to ${senderName}`);
  textarea.disabled = status !== "pending";

  card.append(header, incomingLabel, incoming, replyLabel, textarea);

  if (status === "pending") {
    if (message.metadata?.approvalError) {
      const error = document.createElement("p");
      error.className = "agent-message-whatsapp-card-error";
      error.setAttribute("role", "alert");
      error.textContent = String(message.metadata.approvalError);
      card.append(error);
    }
    const note = document.createElement("p");
    note.className = "agent-message-whatsapp-card-note";
    note.textContent = "Review or edit it here. Nothing is sent until you choose Send reply.";
    const actions = document.createElement("div");
    actions.className = "agent-message-whatsapp-card-actions";

    const sendButton = document.createElement("button");
    sendButton.type = "button";
    sendButton.className = "primary-button small";
    sendButton.textContent = "Send reply";
    sendButton.dataset.agentWhatsAppAction = "send";
    sendButton.dataset.agentWhatsAppApproval = String(approval.approval_id || approval.approvalId || "");
    sendButton.dataset.agentWhatsAppMessage = message.id;

    const skipButton = document.createElement("button");
    skipButton.type = "button";
    skipButton.className = "ghost-button small";
    skipButton.textContent = "Skip";
    skipButton.dataset.agentWhatsAppAction = "skip";
    skipButton.dataset.agentWhatsAppApproval = String(approval.approval_id || approval.approvalId || "");
    skipButton.dataset.agentWhatsAppMessage = message.id;
    actions.append(sendButton, skipButton);
    card.append(note, actions);
  } else if (message.metadata?.approvalError) {
    const error = document.createElement("p");
    error.className = "agent-message-whatsapp-card-error";
    error.setAttribute("role", "alert");
    error.textContent = String(message.metadata.approvalError);
    card.append(error);
  } else {
    const outcome = document.createElement("p");
    outcome.className = "agent-message-whatsapp-card-note";
    outcome.textContent = status === "sent"
      ? "The approved reply was sent to this WhatsApp contact."
      : "This suggestion was skipped and will not be sent.";
    card.append(outcome);
  }

  return card;
}

async function handleAgentWhatsAppApprovalAction(button) {
  const approvalId = String(button?.dataset.agentWhatsAppApproval || "").trim();
  const messageId = String(button?.dataset.agentWhatsAppMessage || "").trim();
  const action = String(button?.dataset.agentWhatsAppAction || "").trim().toLowerCase();
  if (!approvalId || !messageId || !["send", "skip"].includes(action)) {
    return;
  }

  const agent = getAgentWorkspace();
  const message = agent.messages.find((candidate) => candidate.id === messageId);
  if (!message) {
    return;
  }
  const approval = getAgentWhatsAppApprovalForMessage(message);
  if (String(approval.status || "pending").toLowerCase() !== "pending") {
    return;
  }

  const card = button.closest(".agent-message-whatsapp-card");
  const textarea = card?.querySelector(".agent-message-whatsapp-card-textarea");
  const buttons = card ? Array.from(card.querySelectorAll("button")) : [button];
  buttons.forEach((candidate) => {
    candidate.disabled = true;
  });
  if (card) {
    card.classList.add("is-busy");
  }

  try {
    const response = await apiRequest(`/api/approvals/${encodeURIComponent(approvalId)}/${action}`, {
      method: "POST",
      body: action === "send" ? { reply_text: String(textarea?.value || "").trim() } : {},
    });
    message.metadata.approval = response.approval || {
      ...approval,
      status: action === "send" ? "sent" : "skipped",
    };
    message.metadata.approvalStatus = action === "send" ? "sent" : "skipped";
    message.metadata.approvalError = "";
    persistAgentWorkspace(action === "send" ? "Reply sent." : "Reply skipped.");
    renderAgentMessages();
  } catch (error) {
    message.metadata.approvalError = formatApiErrorMessage(
      error,
      action === "send" ? "I couldn’t send that reply. Check the WhatsApp connection and try again." : "I couldn’t skip that reply. Try again.",
    );
    persistClientState();
    renderAgentMessages();
  }
}

function getAgentDisplayMessageText(message, kind, proposal) {
  return String(message?.text || "");
}

function getAgentProposalResultActionId(proposalId) {
  const id = String(proposalId || "").trim();
  if (!id) {
    return "";
  }
  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === id);
  if (!proposal) {
    return "";
  }
  const backendActionId = String(proposal.executionPlan?.backendActionId || "").trim();
  if (proposal.type === "scheduled-message") {
    return backendActionId;
  }
  if (proposal.type === "source-action" && backendActionId) {
    return `source:${backendActionId}`;
  }
  return `proposal:${proposal.id}`;
}

function getAgentResultActionLinkId(message, proposal) {
  if (!message?.metadata?.showActionLink) {
    return "";
  }
  return String(message.metadata?.actionId || "").trim()
    || getAgentProposalResultActionId(proposal?.id || message.metadata?.proposalId || "");
}

function appendAgentResultActionLink(bubble, message, displayText, proposal) {
  const actionId = getAgentResultActionLinkId(message, proposal);
  if (!actionId) {
    bubble.textContent = displayText;
    return;
  }

  const text = String(displayText || "").trim();
  bubble.append(document.createTextNode(text));
  bubble.append(document.createTextNode(/[.!?]$/.test(text) ? " View it " : ". View it "));
  const linkButton = document.createElement("button");
  linkButton.type = "button";
  linkButton.className = "agent-action-inline-link";
  linkButton.dataset.agentShowAction = actionId;
  linkButton.dataset.agentActionProposal = message.metadata?.proposalId || "";
  linkButton.textContent = "here";
  linkButton.setAttribute("aria-label", "Show this action in the Actions panel");
  bubble.append(linkButton, document.createTextNode("."));
}

function getAgentMessageActionChoices(message) {
  return Array.isArray(message?.metadata?.actionChoices) ? message.metadata.actionChoices : [];
}

function createAgentActionChoiceCard(message) {
  const card = document.createElement("section");
  card.className = "agent-message-action-picker";
  card.setAttribute("aria-label", "Choose one of your actions");

  const eyebrow = document.createElement("span");
  eyebrow.className = "agent-message-action-picker-eyebrow";
  eyebrow.textContent = "Your active actions";
  card.append(eyebrow);

  const list = document.createElement("div");
  list.className = "agent-message-action-picker-list";
  const agent = getAgentWorkspace();
  const resolved = Boolean(agentTurnBusy || areAgentMessageActionsResolved(message, agent.messages));
  for (const choice of getAgentMessageActionChoices(message)) {
    const row = document.createElement("div");
    row.className = "agent-message-action-picker-row";

    const button = document.createElement("button");
    button.type = "button";
    button.className = "agent-message-action-picker-option";
    button.dataset.agentMessageAction = "choose";
    button.dataset.agentActionValue = getAgentActionChoiceValue(choice);
    button.dataset.agentActionMessage = message.id;
    button.disabled = resolved;

    const name = document.createElement("span");
    name.className = "agent-message-action-picker-name";
    name.textContent = String(choice?.name || "Action");
    button.append(name);

    const meta = [choice?.status, choice?.created].map((part) => String(part || "").trim()).filter(Boolean);
    if (meta.length) {
      const detail = document.createElement("span");
      detail.className = "agent-message-action-picker-meta";
      detail.textContent = meta.join(" · ");
      button.append(detail);
    }
    row.append(button, createAgentActionChoiceDetailsButton(choice));
    list.append(row);
  }
  card.append(list);
  return card;
}

function createAgentActionChoiceDetailsButton(choice) {
  // Two actions can share a title, so the picker keeps a way to look one up
  // before committing to it.
  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-message-action-picker-details";
  button.dataset.agentActionDetails = String(choice?.id || "");
  button.dataset.agentActionDetailsName = String(choice?.name || "");
  button.dataset.agentActionDetailsStatus = String(choice?.status || "");
  button.dataset.agentActionDetailsCreated = String(choice?.created || "");
  button.title = "Show details";
  button.setAttribute("aria-label", `Show details for ${String(choice?.name || "this action")}`);

  const icon = createSvgElement("svg", {
    class: "agent-message-action-picker-details-icon",
    viewBox: "0 0 24 24",
    fill: "none",
    "aria-hidden": "true",
    focusable: "false",
  });
  icon.append(
    createSvgElement("circle", {
      cx: "12",
      cy: "12",
      r: "9",
      stroke: "currentColor",
      "stroke-width": "1.6",
    }),
    createSvgElement("path", {
      d: "M12 11.1v5",
      stroke: "currentColor",
      "stroke-width": "1.8",
      "stroke-linecap": "round",
    }),
    createSvgElement("circle", { cx: "12", cy: "7.9", r: "1.05", fill: "currentColor" }),
  );
  button.append(icon);
  return button;
}

function findAgentActionChoiceAction(choiceId) {
  const id = String(choiceId || "").trim();
  if (!id) {
    return null;
  }
  return getRenderableAgentActions().find((action) => String(action?.id || "") === id) || null;
}

function getAgentActionChoiceDetailRows(action, choice) {
  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const timezone = action?.timezone || "";
  const statusClass = action ? getScheduledActionStatusClass(action.status, action) : "";
  const rows = [];

  const status = action
    ? getScheduledActionStatusLabel(action.status, action)
    : String(choice?.status || "").trim();
  if (status) {
    rows.push(["Status", status]);
  }

  const watching = Array.isArray(payload.watchItems) && payload.watchItems.length
    ? payload.watchItems.join(" · ")
    : String(payload.watchQuery || "").trim();
  if (watching) {
    rows.push(["Watching", watching]);
  }

  const source = payload.sourceType === "file"
    ? String(payload.fileName || "").trim()
    : String(payload.sourceUrl || "").trim();
  if (source) {
    rows.push(["Source", source]);
  }

  const frequency = String(payload.frequency || "").trim();
  if (frequency) {
    rows.push(["How often", frequency]);
  }

  const deliveryTarget = String(payload.deliveryTarget || "").trim();
  const deliveryChannel = String(payload.deliveryChannel || action?.channel || "").trim();
  if (deliveryTarget || deliveryChannel) {
    const channelLabel = formatAgentScheduledMessageChannel(deliveryChannel);
    rows.push(["Results go to", deliveryTarget ? `${deliveryTarget} (${channelLabel})` : channelLabel]);
  }

  if (action && !isAgentLocalAction(action)) {
    rows.push(["Scheduled for", formatScheduledActionDate(action.runAt, timezone)]);
  } else if (action && statusClass !== "paused" && !payload.manualOnly) {
    rows.push(["Next run", formatScheduledActionDate(payload.nextRunAt || action.runAt, timezone)]);
  }

  if (payload.lastRunAt) {
    rows.push([
      "Last run",
      `${formatScheduledActionDate(payload.lastRunAt, timezone)} · ${capitalizeWords(payload.lastRunStatus || "success")}`,
    ]);
  }

  const created = action
    ? formatScheduledActionDate(action.createdAt, timezone)
    : String(choice?.created || "").trim();
  if (created) {
    rows.push(["Created", created]);
  }

  const lastError = String(action?.lastError || "").trim();
  if (lastError) {
    rows.push(["Last problem", lastError]);
  }

  return rows;
}

function agentTextReadsLikeDescription(text) {
  // A one-tap answer like "1" or "yes" is how the client picked something in
  // chat, not a description of the action they ended up with.
  const value = String(text || "").trim();
  if (!/[a-z]/i.test(value)) {
    return false;
  }
  return value.includes(" ") || value.length >= 12;
}

function getAgentActionPurposeText(raw) {
  let value = String(raw || "").trim();
  // Custom actions used to carry the blueprint's own account of how the agent
  // builds them, with the raw request stapled on the end. Keep the client's
  // words and drop our side of it.
  const blueprint = String(AGENT_BLUEPRINTS.custom?.summary || "");
  if (blueprint && value.startsWith(blueprint)) {
    value = value.slice(blueprint.length).trim();
  }
  const quotedRequest = value.match(/^Request:\s*"([\s\S]*)"$/);
  if (quotedRequest) {
    value = quotedRequest[1].trim();
  }
  return agentTextReadsLikeDescription(value) ? value : "";
}

function createAgentActionChoiceDetailsBody(action, choice) {
  const body = document.createElement("div");
  body.className = "agent-action-choice-details";

  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const summary = getAgentActionPurposeText(payload.summary || payload.messageText || payload.text);
  if (summary) {
    const intro = document.createElement("p");
    intro.className = "agent-action-choice-details-summary";
    intro.textContent = summary;
    body.append(intro);
  }

  const rows = getAgentActionChoiceDetailRows(action, choice);
  if (rows.length) {
    const grid = document.createElement("dl");
    grid.className = "agent-action-choice-details-grid";
    for (const [label, value] of rows) {
      grid.append(createScheduledActionDetailRow(label, value));
    }
    body.append(grid);
  }

  if (!action) {
    const note = document.createElement("p");
    note.className = "agent-action-choice-details-note";
    note.textContent = "This action is no longer in the Actions panel, so only what the picker recorded is shown.";
    body.append(note);
  }

  return body;
}

function openAgentActionChoiceDetails(button) {
  const choice = {
    id: String(button?.dataset.agentActionDetails || "").trim(),
    name: String(button?.dataset.agentActionDetailsName || "").trim(),
    status: String(button?.dataset.agentActionDetailsStatus || "").trim(),
    created: String(button?.dataset.agentActionDetailsCreated || "").trim(),
  };
  const action = findAgentActionChoiceAction(choice.id);
  openAuthAlert(
    action ? getScheduledActionTitle(action) : (choice.name || "Action"),
    "",
    {
      hideMessage: true,
      eyebrow: "Action details",
      icon: "i",
      tone: "progress",
      bodyNode: createAgentActionChoiceDetailsBody(action, choice),
      buttonLabel: "Close",
      returnFocus: button,
    },
  );
}

function handleAgentActionChoiceDetailsClick(event) {
  const button = getEventTargetElement(event)?.closest("[data-agent-action-details]");
  if (!button) {
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  openAgentActionChoiceDetails(button);
  return true;
}

function renderAgentMessageBubbleContent(bubble, message, kind, proposal, displayText) {
  if (kind === "thinking") {
    const progressText = agentTurnProgressText || "Thinking";
    bubble.setAttribute("aria-label", `Assistyca is ${progressText.toLowerCase()}`);
    bubble.append(document.createTextNode(progressText));
    const dots = document.createElement("span");
    dots.className = "agent-thinking-dots";
    dots.setAttribute("aria-hidden", "true");
    for (let index = 0; index < 3; index += 1) {
      dots.append(document.createElement("span"));
    }
    bubble.append(dots);
    return;
  }

  if (kind === "result" && message?.metadata?.showActionLink) {
    appendAgentResultActionLink(bubble, message, displayText, proposal);
    return;
  }

  bubble.textContent = displayText;
}

function renderAgentMessage(message) {
  const row = document.createElement("article");
  const kind = String(message.metadata?.kind || (message.role === "user" ? "user" : "text"));
  const agent = getAgentWorkspace();
  const proposal = getAgentMessageProposal(message, agent);
  const displayText = getAgentDisplayMessageText(message, kind, proposal);
  row.className = `agent-message is-${message.role} is-${kind}`;
  row.dataset.agentMessageId = message.id;

  const bubble = document.createElement("div");
  bubble.className = "agent-message-bubble";
  renderAgentMessageBubbleContent(bubble, message, kind, proposal, displayText);

  const messageLine = document.createElement("div");
  messageLine.className = "agent-message-line";
  messageLine.append(bubble);
  if (kind === "error") {
    const helpButton = document.createElement("button");
    helpButton.type = "button";
    helpButton.className = "agent-message-help-button";
    const helpIcon = document.createElement("span");
    helpIcon.className = "agent-message-help-icon";
    helpIcon.textContent = "i";
    helpIcon.setAttribute("aria-hidden", "true");
    helpButton.append(helpIcon);
    helpButton.setAttribute("aria-label", "Show technical details for this failure");
    helpButton.title = "Show technical details";
    helpButton.addEventListener("click", () => openAgentErrorHelp(message.metadata?.technical, helpButton));
    messageLine.append(helpButton);
  }
  row.append(messageLine);

  if (kind === "connection-setup") {
    row.append(createAgentConnectionSetupCard(message));
  }
  if (kind === "whatsapp-reply-suggestion") {
    row.append(createAgentWhatsAppReplyCard(message));
  }
  if (kind === "action-choice" && getAgentMessageActionChoices(message).length) {
    row.append(createAgentActionChoiceCard(message));
  }

  const actions = getAgentRenderableMessageActions(message, kind, proposal);
  if (actions.length && message.role !== "user") {
    const messageRevision = Math.max(0, Number(message.metadata?.proposalRevision || 0));
    const isStaleApproval = kind === "approval"
      && proposal
      && messageRevision > 0
      && messageRevision !== Math.max(1, Number(proposal.revision || 1));
    const actionsResolved = areAgentMessageActionsResolved(message, agent.messages);
    const actionRow = document.createElement("div");
    actionRow.className = "agent-message-actions";
    for (const action of actions) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = action.tone === "primary" ? "primary-button small" : "ghost-button small";
      button.dataset.agentMessageAction = action.id;
      button.dataset.agentActionValue = action.value || action.label;
      button.dataset.agentActionProposal = message.metadata?.proposalId || "";
      button.dataset.agentActionRevision = String(messageRevision || "");
      button.dataset.agentActionMessage = message.id;
      button.disabled = Boolean(isStaleApproval || actionsResolved || agentTurnBusy);
      button.textContent = action.label;
      actionRow.append(button);
    }
    row.append(actionRow);
  }

  return row;
}

function getAgentMessageRenderSignature(messages) {
  const agent = getAgentWorkspace();
  return JSON.stringify(messages.map((message) => [
    message.id,
    message.role,
    message.text,
    message.metadata?.kind || "",
    message.metadata?.kind === "thinking" ? agentTurnProgressText : "",
    message.metadata?.kind === "whatsapp-reply-suggestion" ? String(message.metadata?.approval?.status || message.metadata?.approvalStatus || "") : "",
    message.metadata?.kind === "whatsapp-reply-suggestion" ? String(message.metadata?.approvalError || "") : "",
    message.metadata?.kind === "whatsapp-reply-suggestion" ? String(message.metadata?.approval?.suggested_reply || "") : "",
    message.metadata?.kind === "action-choice"
      ? getAgentMessageActionChoices(message).map((choice) => [choice?.name || "", choice?.status || "", choice?.created || ""])
      : "",
    message.metadata?.proposalId || "",
    message.metadata?.actionId || "",
    message.metadata?.showActionLink ? "show-action-link" : "",
    message.metadata?.proposalRevision || "",
    message.metadata?.actionsResolvedAt || "",
    message.metadata?.actionsResolvedBy || "",
    message.metadata?.connectionSetup?.platformConnected ? "connected" : "",
    message.metadata?.connectionSetup?.connectionStatus || "",
    Array.isArray(message.metadata?.connectionSetup?.missingFields)
      ? message.metadata.connectionSetup.missingFields.map((field) => field?.key || field?.label || "")
      : [],
    (() => {
      const kind = String(message.metadata?.kind || (message.role === "user" ? "user" : "text"));
      const proposal = getAgentMessageProposal(message, agent);
      return getAgentRenderableMessageActions(message, kind, proposal).map((action) => [
        action.id || "",
        action.label || "",
        action.value || "",
        action.tone || "",
      ]);
    })(),
  ]));
}

function isAgentMessageListNearBottom(container) {
  return container.scrollHeight - container.scrollTop - container.clientHeight < 96;
}

function scrollAgentMessagesToBottom() {
  if (!elements.agentMessageList) {
    return;
  }

  elements.agentMessageList.scrollTop = elements.agentMessageList.scrollHeight;
}

function shouldPinAgentMessagesToBottom(container, messages) {
  if (!container.dataset.agentMessageRenderSignature) {
    return true;
  }
  if (isAgentMessageListNearBottom(container)) {
    return true;
  }

  const nextLastMessage = messages.at(-1);
  return Boolean(
    nextLastMessage
    && nextLastMessage.id !== container.dataset.agentMessageLastId
    && nextLastMessage.role === "user"
  );
}

const AGENT_MESSAGE_MORPH_MS = 900;
let agentAnimatedChatId = null;
let agentAnimatedMessageIds = new Set();

function playAgentMessageEntrance(row, className) {
  row.classList.add(className);
  const finish = (event) => {
    if (event && event.target !== row) {
      return;
    }
    row.classList.remove(className);
    row.removeEventListener("animationend", finish);
  };
  row.addEventListener("animationend", finish);
}

function playAgentThinkingMorph(row, thinking) {
  const line = row.querySelector(".agent-message-line");
  const bubble = row.querySelector(".agent-message-bubble");
  if (!line || !bubble) {
    playAgentMessageEntrance(row, "is-entering-reply");
    return;
  }

  const inlineWidth = bubble.style.width;
  bubble.style.width = "fit-content";
  const target = bubble.getBoundingClientRect();
  bubble.style.width = inlineWidth;

  const overlay = document.createElement("span");
  overlay.className = "agent-message-morph";
  overlay.setAttribute("aria-hidden", "true");
  overlay.style.setProperty("--agent-morph-from-width", `${Math.round(thinking.width)}px`);
  overlay.style.setProperty("--agent-morph-from-height", `${Math.round(thinking.height)}px`);
  overlay.style.setProperty("--agent-morph-to-width", `${Math.round(target.width)}px`);
  overlay.style.setProperty("--agent-morph-to-height", `${Math.round(target.height)}px`);

  const ghost = document.createElement("span");
  ghost.className = "agent-message-morph-ghost";
  ghost.textContent = thinking.label;
  overlay.append(ghost);
  line.append(overlay);
  row.classList.add("is-morphing");

  window.setTimeout(() => {
    overlay.remove();
    row.classList.remove("is-morphing");
  }, AGENT_MESSAGE_MORPH_MS);
}

function readAgentThinkingBubbleSize(container) {
  const bubble = container.querySelector(".agent-message.is-thinking .agent-message-bubble");
  if (!bubble) {
    return null;
  }

  return {
    width: bubble.offsetWidth,
    height: bubble.offsetHeight,
    label: String(bubble.textContent || "Thinking").trim() || "Thinking",
  };
}

const AGENT_MESSAGE_RISE_EASING = "cubic-bezier(0.33, 1, 0.68, 1)";

function findAgentMessageRow(container, messageId) {
  return container.querySelector(`[data-agent-message-id="${CSS.escape(messageId)}"]`);
}

// Where every message sits right now, so the ones already on screen can glide
// to their new spot instead of jumping the moment a message is added.
function readAgentMessageRowTops(container) {
  const tops = new Map();
  for (const row of container.querySelectorAll("[data-agent-message-id]")) {
    tops.set(row.dataset.agentMessageId, row.getBoundingClientRect().top);
  }
  return tops;
}

function glideSettledAgentRows(container, previousTops, duration) {
  if (!previousTops?.size) {
    return;
  }

  const bounds = container.getBoundingClientRect();
  const moves = [];
  for (const [messageId, previousTop] of previousTops) {
    const row = findAgentMessageRow(container, messageId);
    if (!row) {
      continue;
    }
    const rect = row.getBoundingClientRect();
    if (rect.bottom < bounds.top - 40 || rect.top > bounds.bottom + 40) {
      continue;
    }
    const delta = previousTop - rect.top;
    if (Math.abs(delta) < 1) {
      continue;
    }
    moves.push([row, delta]);
  }

  for (const [row, delta] of moves) {
    row.animate(
      [{ transform: `translateY(${delta}px)` }, { transform: "none" }],
      { duration, easing: AGENT_MESSAGE_RISE_EASING },
    );
  }
}

// A sent message starts just below the list's bottom edge, which sits behind
// the composer.
function getAgentRiseTravel(container, row) {
  return Math.max(24, Math.round(container.getBoundingClientRect().bottom - row.getBoundingClientRect().top) + 10);
}

// A taller message has further to travel, so give it longer to get there and
// keep the speed of the movement about the same either way.
function getAgentRiseDuration(travel) {
  return Math.round(Math.min(620, Math.max(380, 340 + travel * 0.55)));
}

function playAgentUserMessageEntrance(row, travel, duration) {
  row.style.setProperty("--agent-rise-distance", `${travel}px`);
  row.style.setProperty("--agent-rise-duration", `${duration}ms`);
  playAgentMessageEntrance(row, "is-entering-user");
}

function playAgentMessageEntrances(container, newMessages, thinking, previousTops) {
  if (shouldReduceAgentMotion()) {
    return;
  }

  const morphId = thinking
    ? newMessages.filter((message) => message.role !== "user").at(-1)?.id || ""
    : "";
  // The message that was just sent sets the pace, so the rest of the
  // conversation moves up with it rather than on its own schedule.
  const travels = new Map();
  for (const message of newMessages) {
    if (message.role !== "user") {
      continue;
    }
    const row = findAgentMessageRow(container, message.id);
    if (row) {
      travels.set(message.id, getAgentRiseTravel(container, row));
    }
  }
  const duration = getAgentRiseDuration(Math.max(80, ...travels.values(), 0));
  glideSettledAgentRows(container, previousTops, duration);
  for (const message of newMessages) {
    const row = findAgentMessageRow(container, message.id);
    if (!row) {
      continue;
    }
    if (message.role === "user") {
      playAgentUserMessageEntrance(row, travels.get(message.id) || 80, duration);
    } else if (message.id === morphId) {
      playAgentThinkingMorph(row, thinking);
    } else {
      playAgentMessageEntrance(row, "is-entering-reply");
    }
  }
}

function renderAgentMessages() {
  if (!elements.agentMessageList) {
    return;
  }

  const agent = getAgentWorkspace();
  elements.agentEmptyState?.classList.toggle("is-hidden", agent.messages.length > 0);
  updateAgentReceiptsQuickAction();
  const visibleMessages = agentTurnBusy
    ? [
      ...agent.messages,
      {
        id: "agent-thinking",
        role: "assistant",
        text: "Thinking",
        metadata: { kind: "thinking", actions: [] },
      },
    ]
    : agent.messages;
  const signature = getAgentMessageRenderSignature(visibleMessages);
  if (elements.agentMessageList.dataset.agentMessageRenderSignature === signature) {
    return;
  }

  const shouldPinToBottom = shouldPinAgentMessagesToBottom(elements.agentMessageList, visibleMessages);
  const lastMessage = visibleMessages.at(-1);
  const chatId = String(agent.activeChatId || "");
  const isFirstRenderForChat = agentAnimatedChatId !== chatId
    || !elements.agentMessageList.dataset.agentMessageRenderSignature;
  if (isFirstRenderForChat) {
    agentAnimatedChatId = chatId;
    agentAnimatedMessageIds = new Set();
  }
  const settledMessages = visibleMessages.filter((message) => message.metadata?.kind !== "thinking");
  const newMessages = isFirstRenderForChat
    ? []
    : settledMessages.filter((message) => !agentAnimatedMessageIds.has(message.id));
  for (const message of settledMessages) {
    agentAnimatedMessageIds.add(message.id);
  }
  const thinking = agentTurnBusy ? null : readAgentThinkingBubbleSize(elements.agentMessageList);
  const previousTops = newMessages.length ? readAgentMessageRowTops(elements.agentMessageList) : null;
  elements.agentMessageList.dataset.agentMessageRenderSignature = signature;
  elements.agentMessageList.dataset.agentMessageLastId = lastMessage?.id || "";
  elements.agentMessageList.replaceChildren(...visibleMessages.map(renderAgentMessage));
  if (shouldPinToBottom && newMessages.length) {
    // Settle the scroll before measuring, so the entrance animations start from
    // where each message actually ends up.
    scrollAgentMessagesToBottom();
  }
  playAgentMessageEntrances(elements.agentMessageList, newMessages, thinking, previousTops);
  if (shouldPinToBottom) {
    window.requestAnimationFrame(scrollAgentMessagesToBottom);
  }
}

function getAgentChatTitle(chat) {
  const explicitTitle = String(chat?.title || "").trim();
  if (explicitTitle && explicitTitle.toLowerCase() !== "new chat") {
    return explicitTitle;
  }

  const firstUserMessage = chat?.messages?.find((message) => message.role === "user");
  const sourceText = String(firstUserMessage?.text || chat?.messages?.[0]?.text || "").trim();
  if (!sourceText) {
    return "New chat";
  }
  return sourceText.length > 46 ? `${sourceText.slice(0, 43).trim()}…` : sourceText;
}

function getAgentChatPreview(chat) {
  const latestMessage = Array.isArray(chat?.messages) ? chat.messages.at(-1) : null;
  const text = String(latestMessage?.text || "").trim();
  if (!text) {
    return "No messages yet.";
  }
  const speaker = latestMessage.role === "user" ? "You" : "Assistyca";
  const preview = text.replace(/\s+/g, " ");
  return `${speaker}: ${preview.length > 72 ? `${preview.slice(0, 69).trim()}…` : preview}`;
}

function formatAgentChatTime(chat) {
  const timestamp = parseAgentTimestamp(chat?.updatedAt || chat?.createdAt);
  if (!timestamp) {
    return "";
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(timestamp));
}

function createAgentChatItem(chat, activeChatId) {
  const item = document.createElement("article");
  item.className = "agent-chat-item";
  item.dataset.agentChatId = chat.id;
  item.setAttribute("role", "listitem");
  const isActive = chat.id === activeChatId;
  item.classList.toggle("is-active", isActive);

  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = "agent-chat-item-open";
  openButton.setAttribute("aria-current", isActive ? "true" : "false");
  openButton.setAttribute("aria-label", `${isActive ? "Current chat" : "Open chat"}: ${getAgentChatTitle(chat)}`);

  const head = document.createElement("div");
  head.className = "agent-chat-item-head";
  const title = document.createElement("strong");
  title.textContent = getAgentChatTitle(chat);
  const badge = document.createElement("span");
  badge.className = "agent-chat-status";
  badge.textContent = isActive ? "Current" : "Saved";
  head.append(title, badge);

  const time = document.createElement("p");
  time.className = "agent-chat-time";
  time.textContent = formatAgentChatTime(chat);

  const preview = document.createElement("p");
  preview.className = "agent-chat-preview";
  preview.textContent = getAgentChatPreview(chat);

  openButton.append(head, time, preview);
  item.append(openButton);

  if (!isActive) {
    const deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "agent-chat-delete";
    deleteButton.dataset.agentChatDelete = chat.id;
    deleteButton.setAttribute("aria-label", `Delete conversation: ${getAgentChatTitle(chat)}`);
    deleteButton.title = "Delete conversation";
    deleteButton.append(
      createSvgElement("svg", {
        viewBox: "0 0 24 24",
        width: "16",
        height: "16",
        fill: "none",
        "aria-hidden": "true",
        focusable: "false",
      }),
    );
    const deleteIcon = deleteButton.firstElementChild;
    deleteIcon.append(
      createSvgElement("path", {
        d: "M5 7.5h14M9 7.5V5h6v2.5M7 7.5l.8 11.5h8.4L17 7.5M10 11v5M14 11v5",
        stroke: "currentColor",
        "stroke-width": "1.8",
        "stroke-linecap": "round",
        "stroke-linejoin": "round",
      }),
    );
    item.append(deleteButton);
  }

  return item;
}

function renderAgentChats() {
  if (!elements.agentChatList) {
    return;
  }

  const agent = getAgentWorkspace();
  syncActiveAgentChatFromWorkspace(agent);
  const chats = sortAgentChats(agent.chats);
  if (!chats.length) {
    const empty = document.createElement("p");
    empty.className = "agent-action-empty";
    empty.textContent = "Your chats will appear here.";
    elements.agentChatList.replaceChildren(empty);
    return;
  }

  elements.agentChatList.replaceChildren(
    ...chats.map((chat) => createAgentChatItem(chat, agent.activeChatId)),
  );
}

function formatAgentFolderItemCount(count) {
  const total = Math.max(0, Number.parseInt(count, 10) || 0);
  return `${total} item${total === 1 ? "" : "s"}`;
}

function formatAgentFolderTime(folder) {
  const timestamp = parseAgentTimestamp(folder?.updatedAt || folder?.createdAt);
  if (!timestamp) {
    return "";
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
  }).format(new Date(timestamp));
}

function getAgentFolderSearchText(folder) {
  const type = getAgentFolderTypeOption(folder?.type);
  return [
    folder?.name,
    type.value,
    type.label,
    formatAgentFolderItemCount(folder?.itemCount),
  ].join(" ").toLowerCase();
}

function getFilteredAgentFolders(agent = getAgentWorkspace()) {
  const query = normalizeAgentTextItem(state.agentFolderSearch, "").toLowerCase();
  const folders = Array.isArray(agent.folders) ? agent.folders : [];
  const filtered = query
    ? folders.filter((folder) => getAgentFolderSearchText(folder).includes(query))
    : folders;
  return sortAgentFolders(filtered, state.agentFolderSort);
}

// A receipts run writes its bundle into a folder on the server. Nothing used
// to record that anywhere, so the Folders view stayed empty after a
// successful run. Upsert by name so re-running a month updates the count
// rather than stacking duplicates.
function recordAgentReceiptFolder(response = {}) {
  const rawFolder = String(response?.outputFolder || "").trim().replace(/\/+$/, "");
  const name = normalizeAgentFolderName(rawFolder, "");
  if (!name) {
    return null;
  }

  const agent = getAgentWorkspace();
  const itemCount = Math.max(0, Number.parseInt(response?.receiptCount ?? 0, 10) || 0);
  const now = new Date().toISOString();
  const existing = agent.folders.find((folder) => folder.name.toLowerCase() === name.toLowerCase());
  if (existing) {
    existing.type = "receipts";
    existing.itemCount = itemCount;
    existing.updatedAt = now;
  } else {
    agent.folders.unshift(createAgentFolderRecord(name, "receipts", { itemCount, createdAt: now }));
  }
  agent.folders = sortAgentFolders(agent.folders, state.agentFolderSort).slice(0, AGENT_MAX_FOLDERS);
  agentFolderContents.delete(name);
  persistClientState();
  renderAgentFolders();
  return name;
}

function formatAgentFolderFileSize(size) {
  const bytes = Math.max(0, Number(size) || 0);
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  if (bytes < 1024 * 1024) {
    return `${Math.round(bytes / 1024)} KB`;
  }
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

// Folder contents live on the server as the bundle a run wrote to disk, so the
// panel reads them the first time a folder is opened and keeps the answer for
// the rest of the session.
async function loadAgentFolderContents(folderName) {
  const name = normalizeAgentTextItem(folderName, "");
  if (!name) {
    return;
  }

  const cached = agentFolderContents.get(name);
  if (cached && cached.status !== "error") {
    return;
  }

  agentFolderContents.set(name, { status: "loading", items: [], message: "" });
  renderAgentFolders();
  try {
    const response = await apiRequest(`/api/agent/folder-contents?folder=${encodeURIComponent(name)}`);
    const items = Array.isArray(response?.items) ? response.items : [];
    agentFolderContents.set(name, { status: "ready", items, message: "" });
  } catch (error) {
    agentFolderContents.set(name, {
      status: "error",
      items: [],
      message: formatApiErrorMessage(error, "I couldn’t open that folder."),
    });
  }
  renderAgentFolders();
}

function toggleAgentFolderOpen(folderId) {
  const id = normalizeAgentTextItem(folderId, "");
  state.agentFolderOpenId = state.agentFolderOpenId === id ? "" : id;
  renderAgentFolders();

  if (!state.agentFolderOpenId) {
    return;
  }

  const folder = getAgentWorkspace().folders.find((entry) => entry.id === state.agentFolderOpenId);
  if (folder) {
    void loadAgentFolderContents(folder.name);
  }
}

function createAgentFolderIcon() {
  const icon = document.createElement("span");
  icon.className = "agent-folder-icon";
  const svg = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    "aria-hidden": "true",
    focusable: "false",
  });
  svg.append(
    createSvgElement("path", {
      d: "M3.5 7.6a2 2 0 0 1 2-2h3.2a2 2 0 0 1 1.5.7l1 1.2h7.3a2 2 0 0 1 2 2v7.9a2 2 0 0 1-2 2h-13a2 2 0 0 1-2-2Z",
    }),
    createSvgElement("path", { d: "M3.5 11.2h17" }),
  );
  icon.append(svg);
  icon.setAttribute("aria-hidden", "true");
  return icon;
}

function createAgentFolderBody(folder) {
  const body = document.createElement("div");
  body.className = "agent-folder-body";

  const contents = agentFolderContents.get(folder.name);
  if (!contents || contents.status === "loading") {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note";
    note.textContent = "Opening folder…";
    body.append(note);
    return body;
  }

  if (contents.status === "error") {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note is-error";
    note.textContent = contents.message;
    body.append(note);
    return body;
  }

  if (!contents.items.length) {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note";
    note.textContent = "This folder is empty. Files land here after the action runs.";
    body.append(note);
    return body;
  }

  const list = document.createElement("ul");
  list.className = "agent-folder-file-list";
  for (const file of contents.items) {
    const href = normalizeAgentNotificationHref(file?.url);
    const name = normalizeAgentTextItem(file?.name, "");
    if (!href || !name) {
      continue;
    }

    const row = document.createElement("li");
    const link = document.createElement("a");
    link.className = "agent-folder-file";
    link.href = href;
    link.target = "_blank";
    link.rel = "noopener noreferrer";

    const label = document.createElement("span");
    label.className = "agent-folder-file-name";
    label.textContent = name;

    const size = document.createElement("span");
    size.className = "agent-folder-file-size";
    size.textContent = formatAgentFolderFileSize(file?.size);

    link.append(label, size);
    row.append(link);
    list.append(row);
  }
  body.append(list);
  return body;
}

function createAgentFolderItem(folder) {
  const item = document.createElement("article");
  const type = getAgentFolderTypeOption(folder?.type);
  const isOpen = state.agentFolderOpenId === folder.id;
  item.className = `agent-folder-item is-${type.value}`;
  item.classList.toggle("is-open", isOpen);
  item.dataset.agentFolderId = folder.id;
  item.setAttribute("role", "listitem");

  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = "agent-folder-item-open";
  openButton.dataset.agentFolderOpen = folder.id;
  openButton.setAttribute("aria-expanded", String(isOpen));
  openButton.setAttribute("aria-label", `${isOpen ? "Close" : "Open"} folder: ${folder.name}`);

  const copy = document.createElement("span");
  copy.className = "agent-folder-copy";
  const title = document.createElement("strong");
  title.textContent = folder.name;

  const meta = document.createElement("span");
  meta.className = "agent-folder-meta";
  meta.textContent = `${type.label} · ${formatAgentFolderItemCount(folder.itemCount)}`;
  copy.append(title, meta);

  const time = document.createElement("span");
  time.className = "agent-folder-time";
  time.textContent = formatAgentFolderTime(folder);

  openButton.append(createAgentFolderIcon(), copy, time);
  item.append(openButton);

  if (isOpen) {
    item.append(createAgentFolderBody(folder));
  }
  return item;
}

function renderAgentFolders() {
  if (!elements.agentFolderList) {
    return;
  }

  const agent = getAgentWorkspace();
  agent.folderSort = normalizeAgentFolderSort(agent.folderSort || state.agentFolderSort);
  state.agentFolderSort = normalizeAgentFolderSort(state.agentFolderSort || agent.folderSort);
  const folders = getFilteredAgentFolders(agent);
  const totalFolders = Array.isArray(agent.folders) ? agent.folders.length : 0;
  if (
    state.agentFolderOpenId
    && !folders.some((folder) => folder.id === state.agentFolderOpenId)
  ) {
    state.agentFolderOpenId = "";
  }

  if (elements.agentFolderCount) {
    elements.agentFolderCount.textContent = String(totalFolders);
  }
  if (elements.agentFolderSearchInput && elements.agentFolderSearchInput.value !== state.agentFolderSearch) {
    elements.agentFolderSearchInput.value = state.agentFolderSearch;
  }
  if (elements.agentFolderSortSelect && elements.agentFolderSortSelect.value !== state.agentFolderSort) {
    elements.agentFolderSortSelect.value = state.agentFolderSort;
  }
  syncAgentFolderDisclosureControls();

  if (!folders.length) {
    const empty = document.createElement("p");
    empty.className = "agent-action-empty";
    empty.textContent = state.agentFolderSearch ? "No matching folders." : "No folders yet.";
    elements.agentFolderList.replaceChildren(empty);
    return;
  }

  elements.agentFolderList.replaceChildren(
    ...folders.map(createAgentFolderItem),
  );
}

function syncAgentPanelModeControls() {
  const mode = normalizeAgentPanelMode(state.agentPanelMode);
  elements.agentActionsListView?.classList.toggle("is-hidden", mode !== "actions");
  elements.agentChatsListView?.classList.toggle("is-hidden", mode !== "chats");
  elements.agentFoldersListView?.classList.toggle("is-hidden", mode !== "folders");
  elements.agentActionDetailView?.classList.add("is-hidden");
  elements.agentPanelModeSwitch?.setAttribute("data-agent-panel-current-mode", mode);

  for (const [button, buttonMode] of getAgentPanelModeControls()) {
    if (!button) {
      continue;
    }
    const selected = mode === buttonMode;
    button.classList.toggle("is-active", selected);
    button.setAttribute("aria-selected", String(selected));
    button.tabIndex = selected ? 0 : -1;
  }
}

function createAgentList(items, className, itemClassName) {
  const list = document.createElement("div");
  list.className = className;

  for (const item of items) {
    const row = document.createElement("div");
    row.className = itemClassName;

    const title = document.createElement("strong");
    title.textContent = item.label || item.name || "Item";

    const detail = document.createElement("p");
    detail.textContent = item.detail || item.purpose || "";

    row.append(title, detail);
    list.append(row);
  }

  return list;
}

function renderAgentProposalCard() {
  if (!elements.agentProposalCard) {
    return;
  }

  const proposal = getActiveAgentProposal();
  if (!proposal) {
    const empty = document.createElement("div");
    empty.className = "agent-empty-panel";
    const eyebrow = document.createElement("p");
    eyebrow.className = "eyebrow";
    eyebrow.textContent = "Plan";
    const title = document.createElement("h2");
    title.textContent = "No plan yet";
    const copy = document.createElement("p");
    copy.textContent = "Send a request and the agent will turn it into an approval-ready plan.";
    empty.append(eyebrow, title, copy);
    elements.agentProposalCard.replaceChildren(empty);
    return;
  }

  const head = document.createElement("div");
  head.className = "agent-proposal-head";

  const copyBlock = document.createElement("div");
  const eyebrow = document.createElement("p");
  eyebrow.className = "eyebrow";
  eyebrow.textContent = "Proposed plan";
  const title = document.createElement("h2");
  title.textContent = getAgentProposalPurposeTitle(proposal);
  const summary = document.createElement("p");
  summary.textContent = proposal.summary;
  copyBlock.append(eyebrow, title, summary);

  const status = document.createElement("span");
  status.className = "feature-status";
  status.textContent = getProposalReadinessLabel(proposal);
  head.append(copyBlock, status);

  const skillsTitle = document.createElement("h3");
  skillsTitle.textContent = "Skills";
  const skills = createAgentList(proposal.skills, "agent-mini-list", "agent-mini-row");

  const helpersTitle = document.createElement("h3");
  helpersTitle.textContent = "Helper agents";
  const helpers = createAgentList(
    proposal.helpers.map((helper) => ({
      label: helper.name,
      detail: helper.purpose,
    })),
    "agent-mini-list",
    "agent-mini-row",
  );

  const questions = document.createElement("div");
  questions.className = "agent-question-block";
  const questionsTitle = document.createElement("h3");
  questionsTitle.textContent = "Questions before it runs";
  const questionList = document.createElement("ul");
  if (proposal.questions.length) {
    for (const question of proposal.questions) {
      const item = document.createElement("li");
      item.textContent = question;
      questionList.append(item);
    }
  } else {
    const item = document.createElement("li");
    item.textContent = "No missing details; ready for approval.";
    questionList.append(item);
  }
  questions.append(questionsTitle, questionList);

  const actions = document.createElement("div");
  actions.className = "agent-proposal-actions";

  const approveButton = document.createElement("button");
  approveButton.className = "primary-button small";
  approveButton.type = "button";
  approveButton.dataset.agentApproveProposal = proposal.id;
  approveButton.textContent = proposal.approved ? "Approved" : proposal.primaryActionLabel;
  approveButton.disabled = proposal.approved;

  const setupButton = document.createElement("button");
  setupButton.className = "ghost-button small";
  setupButton.type = "button";
  setupButton.dataset.agentOpenSetup = proposal.id;
  setupButton.textContent = getProposalSetupLabel(proposal);

  const changeButton = document.createElement("button");
  changeButton.className = "ghost-button small";
  changeButton.type = "button";
  changeButton.dataset.agentRequestChanges = proposal.id;
  changeButton.textContent = "Adjust plan";

  actions.append(approveButton, setupButton, changeButton);

  if (proposal.missingCredential) {
    const requirement = getAgentProposalRequiredConnection(proposal);
    const credential = document.createElement("div");
    credential.className = "agent-credential-callout";
    const credentialCopy = document.createElement("p");
    credentialCopy.textContent = requirement && !isAgentProposalRequiredConnectionReady(requirement)
      ? getAgentRequiredConnectionCalloutText(requirement)
      : `${proposal.missingCredential} may be required. If you do not know how to get it, I can help.`;
    const helpButton = document.createElement("button");
    helpButton.className = "ghost-button small";
    helpButton.type = "button";
    if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
      helpButton.dataset.agentOpenSetup = proposal.id;
      helpButton.textContent = requirement.actionLabel || "Open setup";
    } else {
      helpButton.dataset.agentCredentialHelp = proposal.id;
      helpButton.textContent = "Help me get it";
    }
    credential.append(credentialCopy, helpButton);
    elements.agentProposalCard.replaceChildren(head, skillsTitle, skills, helpersTitle, helpers, questions, credential, actions);
    return;
  }

  elements.agentProposalCard.replaceChildren(head, skillsTitle, skills, helpersTitle, helpers, questions, actions);
}

function renderAgentHelpers() {
  if (!elements.agentHelperList || !elements.agentHelperCount) {
    return;
  }

  const agent = getAgentWorkspace();
  elements.agentHelperCount.textContent = String(agent.helpers.length);

  if (!agent.helpers.length) {
    const empty = document.createElement("p");
    empty.className = "agent-helper-empty";
    empty.textContent = "Approved helper agents will appear here.";
    elements.agentHelperList.replaceChildren(empty);
    return;
  }

  const rows = agent.helpers.map((helper) => {
    const row = document.createElement("article");
    row.className = "agent-helper-row";

    const copy = document.createElement("div");
    const title = document.createElement("h3");
    title.textContent = helper.name;
    const purpose = document.createElement("p");
    purpose.textContent = helper.purpose;
    copy.append(title, purpose);

    const status = document.createElement("span");
    status.className = "feature-status";
    status.textContent = helper.status;

    row.append(copy, status);
    return row;
  });

  elements.agentHelperList.replaceChildren(...rows);
}

function normalizeScheduledAction(action = {}) {
  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  return {
    id: Math.max(0, Number(action.id || 0)),
    actionType: String(action.actionType || "").trim(),
    channel: String(action.channel || "").trim().toLowerCase(),
    recipientRef: String(action.recipientRef || "").trim(),
    runAt: String(action.runAt || "").trim(),
    timezone: String(action.timezone || "").trim(),
    status: String(action.status || "pending").trim().toLowerCase() || "pending",
    attemptCount: Math.max(0, Number(action.attemptCount || 0)),
    providerMessageId: String(action.providerMessageId || "").trim(),
    payload: { ...payload },
    lastError: String(action.lastError || "").trim(),
    claimedAt: String(action.claimedAt || "").trim(),
    completedAt: String(action.completedAt || "").trim(),
    createdAt: String(action.createdAt || "").trim(),
    updatedAt: String(action.updatedAt || "").trim(),
  };
}

function normalizeSourceAction(action = {}) {
  const sourceType = String(action.sourceType || "").trim().toLowerCase();
  const id = Math.max(0, Number(action.id || 0));
  const statusText = String(action.status || "active").trim().toLowerCase();
  const normalizedStatus = statusText === "cancelled" || statusText === "canceled"
    ? "cancelled"
    : statusText === "paused" || statusText === "stopped"
      ? "paused"
      : "running";
  const payload = {
    source: "source_action",
    sourceActionId: id,
    title: "Source action",
    preview: sourceType === "file" ? String(action.fileName || "Attached file") : String(action.sourceUrl || "Source URL"),
    sourceType,
    sourceUrl: String(action.sourceUrl || "").trim(),
    fileName: String(action.fileName || "").trim(),
    mimeType: String(action.mimeType || "").trim(),
    frequency: formatSourceActionFrequency(action.intervalMinutes),
    lastRunAt: String(action.lastRunAt || "").trim(),
    lastRunStatus: String(action.lastRunStatus || "").trim(),
    nextRunAt: String(action.nextRunAt || "").trim(),
    lastContentHash: String(action.lastContentHash || "").trim(),
    lastContentSize: Number(action.lastContentSize || 0),
    lastHttpStatus: action.lastHttpStatus,
    runCount: Number(action.runCount || 0),
  };
  return {
    id: `source:${id}`,
    actionType: "agent_source_action",
    channel: "source",
    recipientRef: "",
    runAt: String(action.nextRunAt || "").trim(),
    timezone: String(action.timezone || getWorkspaceTimeZone()).trim(),
    status: normalizedStatus,
    attemptCount: Number(action.runCount || 0),
    providerMessageId: "",
    payload,
    local: true,
    lastError: String(action.lastError || "").trim(),
    claimedAt: String(action.claimedAt || "").trim(),
    completedAt: normalizedStatus === "cancelled" ? String(action.updatedAt || "") : "",
    createdAt: String(action.createdAt || "").trim(),
    updatedAt: String(action.updatedAt || "").trim(),
  };
}

function formatSourceActionFrequency(intervalMinutes) {
  const amount = Math.max(1, Number(intervalMinutes || 1440));
  if (amount < 60) return `every ${amount} minutes`;
  if (amount % (24 * 60) === 0) {
    const days = amount / (24 * 60);
    return days === 1 ? "daily" : `every ${days} days`;
  }
  if (amount % 60 === 0) {
    const hours = amount / 60;
    return hours === 1 ? "hourly" : `every ${hours} hours`;
  }
  return `every ${amount} minutes`;
}

function normalizeAgentActionTypeLabel(value) {
  return capitalizeWords(String(value || "")
    .replace(/^agent[_-]+/, "")
    .replace(/[_-]+/g, " ")
    .trim());
}

function isAgentProposalLocalAction(action) {
  return Boolean(
    action?.payload?.source === "agent_proposal"
    || String(action?.id || "").startsWith("proposal:")
  );
}

function isAgentFeatureLiveAction(action) {
  return Boolean(
    action?.payload?.source === "feature"
    || String(action?.id || "").startsWith("feature:")
  );
}

function isAgentLocalAction(action) {
  return Boolean(
    isAgentProposalLocalAction(action)
    || isAgentFeatureLiveAction(action)
    || (action?.local === true && String(action?.actionType || "").startsWith("agent_"))
  );
}

function normalizeScheduledActionStatusClass(status) {
  const normalized = String(status || "pending").trim().toLowerCase();
  return ["pending", "running", "paused", "manual_only", "sent", "delivered", "read", "failed", "cancelled"].includes(normalized)
    ? normalized
    : "unknown";
}

function agentActionFrequencyLooksRecurring(value) {
  return /\b(?:every|hourly|daily|weekly|monthly|recurring|scheduled)\b/i.test(String(value || ""))
    || /\b\d+\s*(?:minutes?|hours?|days?|weeks?|months?)\b/i.test(String(value || ""));
}

function getAgentActionPresentationStatus(action, status = action?.status) {
  const rawStatus = normalizeScheduledActionStatusClass(status);
  if (!isAgentLocalAction(action)) {
    return rawStatus;
  }
  if (["sent", "delivered", "read", "failed", "cancelled"].includes(rawStatus)) {
    return rawStatus;
  }

  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const runMode = String(payload.runMode || payload.run_mode || payload.mode || "").trim().toLowerCase();
  const manualOnly = normalizeMonitorManualOnly(payload.manualOnly, false)
    || rawStatus === "manual_only"
    || ["manual", "manual_only", "on_demand", "on-demand"].includes(runMode);
  if (manualOnly) {
    return "manual_only";
  }

  const recurring = ["running", "paused"].includes(rawStatus)
    || ["recurring", "scheduled", "auto", "automatic", "background"].includes(runMode)
    || agentActionFrequencyLooksRecurring(payload.frequency)
    || agentActionFrequencyLooksRecurring(payload.schedule);
  if (!recurring) {
    return rawStatus;
  }

  const lifecycleStatus = normalizeMonitorActionLifecycleStatus(
    payload.actionLifecycleStatus
      || payload.action_lifecycle_status
      || payload.lifecycleStatus
      || payload.lifecycle_status
      || rawStatus,
  );
  if (lifecycleStatus === "removed") {
    return "cancelled";
  }
  return lifecycleStatus === "paused" || rawStatus === "paused" ? "paused" : "running";
}

function getAgentActionSourceActionId(action) {
  return Math.max(0, Number(action?.payload?.sourceActionId || 0));
}

function getAgentActionBackendFeatureId(action) {
  return String(action?.payload?.backendFeatureId || "").trim()
    || getAgentFeatureIdFromLocalActionId(action?.id);
}

function getAgentActionLifecycleBusyKey(action) {
  const sourceActionId = getAgentActionSourceActionId(action);
  if (sourceActionId) {
    return `source:${sourceActionId}`;
  }
  const featureId = getAgentActionBackendFeatureId(action);
  if (featureId) {
    return `feature:${featureId}`;
  }
  return String(action?.id || "").trim();
}

function isAgentActionLifecycleBusy(action) {
  const key = getAgentActionLifecycleBusyKey(action);
  return Boolean(key && agentActionLifecycleBusy.has(key));
}

function getAgentLocalActionSettingsBusyKey(action) {
  return String(action?.id || "").trim();
}

function setAgentLocalActionSettingsBusy(action, busy = true) {
  const key = getAgentLocalActionSettingsBusyKey(action);
  if (!key) {
    return;
  }
  if (busy) {
    agentLocalActionSettingsBusy.add(key);
  } else {
    agentLocalActionSettingsBusy.delete(key);
  }
}

function isAgentLocalActionSettingsBusy(action) {
  const key = getAgentLocalActionSettingsBusyKey(action);
  return Boolean(key && agentLocalActionSettingsBusy.has(key));
}

function isAgentLocalActionRunBusy(action) {
  return Boolean(
    isAgentProposalLocalAction(action)
    && localActionRunBusy.has(String(action?.id || "").trim()),
  );
}

function isAgentLifecycleActionPaused(action) {
  return getScheduledActionStatusClass(action?.status, action) === "paused";
}

function canToggleAgentActionLifecycle(action) {
  if (!isAgentLocalAction(action) || getAgentActionPresentationStatus(action) === "manual_only") {
    return false;
  }
  const statusClass = getScheduledActionStatusClass(action?.status, action);
  if (!["running", "paused"].includes(statusClass)) {
    return false;
  }
  return Boolean(
    getAgentActionSourceActionId(action)
    || getAgentActionBackendFeatureId(action)
    || isAgentProposalLocalAction(action)
  );
}

function getAgentProposalFieldValue(proposal, key) {
  const fields = proposal?.fields && typeof proposal.fields === "object" ? proposal.fields : {};
  return String(fields[key] || "").trim();
}

function getAgentProposalExecutionSettings(proposal) {
  return proposal?.executionPlan?.settings && typeof proposal.executionPlan.settings === "object"
    ? proposal.executionPlan.settings
    : {};
}

function getAgentProposalLifecycleStatus(proposal) {
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const executionPlan = proposal?.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {};
  const settings = executionPlan.settings && typeof executionPlan.settings === "object" ? executionPlan.settings : {};
  return normalizeMonitorActionLifecycleStatus(
    details.actionLifecycleStatus
      || details.action_lifecycle_status
      || executionPlan.actionLifecycleStatus
      || executionPlan.action_lifecycle_status
      || settings.actionLifecycleStatus
      || settings.action_lifecycle_status,
  );
}

function setAgentProposalLifecycleStatus(proposal, lifecycleStatus) {
  if (!proposal) {
    return;
  }
  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    actionLifecycleStatus: normalizedStatus,
  };
  proposal.executionPlan = {
    ...(proposal.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {}),
    actionLifecycleStatus: normalizedStatus,
    settings: {
      ...(proposal.executionPlan?.settings && typeof proposal.executionPlan.settings === "object" ? proposal.executionPlan.settings : {}),
      actionLifecycleStatus: normalizedStatus,
    },
  };
  proposal.updatedAt = new Date().toISOString();
}

function agentWebMonitorTextSuggestsManualOnly(value) {
  return /\b(?:manual(?:ly)?|manual[ _-]?only|on[ -]?demand|when i (?:ask|choose|want)|when (?:the )?user clicks?|run only when|run now)\b/i
    .test(String(value || ""));
}

function agentTextSuggestsOneTimeRun(value) {
  return /\b(?:just once|only once|one[-\s]?time|one[-\s]?off|run once|single run)\b/i
    .test(String(value || ""));
}

function getAgentProposalWebMonitorManualOnly(proposal, backendFeature = null) {
  if (proposal?.type !== "web-monitor") {
    return false;
  }

  const requestedFrequency = extractAgentFrequencyField(proposal?.requestText || "");
  if (backendFeature && isMonitorFeature(backendFeature)) {
    if (normalizeMonitorManualOnly(getSavedFeatureSettings(backendFeature).manualOnly, false)) {
      return true;
    }
    if (!requestedFrequency) {
      return true;
    }
  }

  const settings = getAgentProposalExecutionSettings(proposal);
  if (Object.prototype.hasOwnProperty.call(settings, "manualOnly")) {
    if (normalizeMonitorManualOnly(settings.manualOnly, false)) {
      return true;
    }
    if (!requestedFrequency) {
      return true;
    }
  }
  if (Object.prototype.hasOwnProperty.call(settings, "manual_only")) {
    if (normalizeMonitorManualOnly(settings.manual_only, false)) {
      return true;
    }
    if (!requestedFrequency) {
      return true;
    }
  }

  const runMode = String(
    settings.runMode
    || settings.run_mode
    || settings.mode
    || proposal?.executionPlan?.runMode
    || proposal?.executionPlan?.run_mode
    || "",
  ).trim().toLowerCase();
  if (["manual", "manual_only", "on_demand", "on-demand"].includes(runMode)) {
    return true;
  }

  return [
    settings.frequency,
    proposal?.executionPlan?.frequency,
    getAgentProposalFieldValue(proposal, "frequency"),
    proposal?.summary,
    proposal?.requestText,
  ].some(agentWebMonitorTextSuggestsManualOnly) || !requestedFrequency;
}

function getAgentProposalManualOnly(proposal, backendFeature = null) {
  if (proposal?.type === "web-monitor") {
    return getAgentProposalWebMonitorManualOnly(proposal, backendFeature);
  }

  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const settings = getAgentProposalExecutionSettings(proposal);
  const explicitManual = [
    details.manualOnly,
    details.manual_only,
    settings.manualOnly,
    settings.manual_only,
  ].find((value) => value !== undefined && value !== null && value !== "");
  if (explicitManual !== undefined) {
    return normalizeMonitorManualOnly(explicitManual, false);
  }

  const runMode = String(
    details.runMode
    || details.run_mode
    || settings.runMode
    || settings.run_mode
    || proposal?.executionPlan?.runMode
    || proposal?.executionPlan?.run_mode
    || "",
  ).trim().toLowerCase();
  if (["manual", "manual_only", "on_demand", "on-demand"].includes(runMode)) {
    return true;
  }

  // Calendar summaries are currently created as user-triggered actions. A
  // recurring cadence can still be chosen later in the shared editor.
  if (proposal?.type === "calendar-summary" && !extractAgentFrequencyField(proposal?.requestText || "")) {
    return true;
  }

  const cadenceFields = [
    settings.frequency,
    proposal?.executionPlan?.frequency,
    getAgentProposalFieldValue(proposal, "frequency"),
    getAgentProposalFieldValue(proposal, "schedule"),
  ];
  const manualTexts = [...cadenceFields, proposal?.summary, proposal?.requestText];
  if (manualTexts.some(agentWebMonitorTextSuggestsManualOnly) || manualTexts.some(agentTextSuggestsOneTimeRun)) {
    return true;
  }

  // A month-based batch job (August receipts, last month's invoices) is a
  // one-off unless a cadence was actually chosen. Making it live by default
  // would silently keep re-running work the user asked for once.
  if (agentContextSuggestsMonthlyBatchTask(proposal)) {
    return ![...cadenceFields, proposal?.requestText].some((text) => Boolean(extractAgentFrequencyField(text)));
  }

  return false;
}

function applyAgentProposalManualMode(proposal) {
  if (!proposal || proposal.type === "scheduled-message") {
    return false;
  }
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    manualOnly: true,
    runMode: "manual",
  };
  proposal.executionPlan = {
    ...(proposal.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {}),
    manualOnly: true,
    runMode: "manual",
    frequency: "manual only",
  };
  proposal.fields = {
    ...getAgentProposalFieldMap(proposal),
    frequency: "manual only",
  };
  if (proposal.type === "email-digest") {
    proposal.fields.schedule = "manual only";
  }
  syncAgentProposalFieldCompatibility(proposal);
  normalizeAgentMonthlyBatchProposalFields(proposal, { frequency: "manual" });
  proposal.revision = Math.max(1, Number(proposal.revision || 1)) + 1;
  proposal.updatedAt = new Date().toISOString();
  updateAgentProposalSummaryFromFields(proposal);
  return true;
}

function isGenericAgentPurposeTitle(value) {
  return AGENT_GENERIC_CUSTOM_TITLE_PATTERN.test(String(value || "").trim());
}

function getAgentPurposeTextFromProposal(proposal, extra = {}) {
  const fields = getAgentProposalFieldMap(proposal);
  const pieces = [
    extra.result,
    fields.result,
    fields.mailbox,
    fields.sourceFileName,
    fields.sourceUrl,
    fields.watchQuery,
    fields.calendar,
    proposal?.requestText,
    proposal?.summary,
    extra.preview,
    extra.summary,
  ];
  return pieces
    .map((piece) => String(piece || "").trim())
    .filter(Boolean)
    .join(" ");
}

function getAgentPurposeTextFromAction(action) {
  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const pieces = [
    payload.result,
    payload.preview,
    payload.summary,
    payload.mailbox,
    payload.sourceFileName,
    payload.sourceUrl,
    payload.watchQuery,
    payload.calendar,
  ];
  return pieces
    .map((piece) => String(piece || "").trim())
    .filter(Boolean)
    .join(" ");
}

function formatAgentDerivedPurposeTitle(value) {
  const clean = String(value || "")
    .replace(/\s+/g, " ")
    .replace(/^[\s:;,.!?-]+|[\s:;,.!?-]+$/g, "")
    .trim();
  if (!clean) {
    return "";
  }
  const words = clean
    .split(/\s+/)
    .filter((word) => !/^(?:my|the|a|an|all|some|any|please)$/i.test(word))
    .slice(0, 4);
  if (!words.length) {
    return "";
  }
  const phrase = words.join(" ").toLowerCase();
  const title = capitalizeWords(phrase);
  return /\b(?:agent|assistant|helper|collector|summari[sz]er|digest|monitor|report|tracker)\b/i.test(title)
    ? title
    : `${title} helper`;
}

function getAgentPurposeTitleFromText(text) {
  const value = String(text || "").trim();
  const lower = value.toLowerCase();
  if (!lower) {
    return "";
  }
  const has = (pattern) => pattern.test(lower);
  if (has(/\breceipts?\b/)) {
    return "Receipt collector";
  }
  if (has(/\binvoices?\b/)) {
    return "Invoice collector";
  }
  if (has(/\bstatements?\b/)) {
    return "Statement collector";
  }
  if (has(/\b(?:expenses?|transactions?|bills?)\b/)) {
    return "Expense collector";
  }
  if (has(/\b(?:bookkeeping|reconciliation)\b/)) {
    return "Bookkeeping helper";
  }
  if (has(/\b(?:gmail|email|emails|mailbox|inbox|mail)\b/) && has(/\b(?:summar(?:y|ize|ise)|digest|brief|overview)\b/)) {
    return "Email summarizer";
  }
  if (has(/\b(?:drive|docs?|documents?|files?|pdfs?|spreadsheets?)\b/)) {
    return has(/\b(?:summar(?:y|ize|ise)|digest|brief|overview)\b/)
      ? "Document summarizer"
      : "Drive file collector";
  }
  if (has(/\b(?:calendar|meetings?|agenda|appointments?)\b/) && has(/\b(?:summar(?:y|ize|ise)|brief|overview|review|list|show)\b/)) {
    return "Meeting summary";
  }
  if (has(/\b(?:watch|monitor|deadline|alert|web|search|opportunit|event)\b/)) {
    return "Web monitor";
  }
  if (has(/\b(?:whatsapp|reply|approval|lead|customer message)\b/)) {
    return has(/\b(?:reply|approval)\b/) ? "WhatsApp reply helper" : "WhatsApp helper";
  }
  if (has(/\b(?:re-?engage|follow[- ]?up|past customer|quiet conversation|dormant)\b/)) {
    return "Customer follow-up";
  }

  const cleaned = value
    .replace(/^\s*(?:please\s+)?(?:can you|could you|i want you to|i need you to|i need to|help me(?:\s+to)?)\s+/i, "")
    .replace(/^\s*(?:pull|fetch|find|collect|gather|get|search|summari[sz]e|prepare|create|make|generate|build|watch|monitor|check|send|read|organize|sort|list|show)\s+/i, "")
    .replace(/^\s*(?:all|my|the|a|an)\s+/i, "")
    .replace(new RegExp(`\\s+(?:from|for|in|during)\\s+(?:${AGENT_MONTH_NAME_PATTERN}|\\d{4}|this|next|last)\\b[\\s\\S]*$`, "i"), "")
    .replace(/\s+every\b[\s\S]*$/i, "")
    .trim();
  return formatAgentDerivedPurposeTitle(cleaned);
}

function getAgentProposalPurposeTitle(proposal, extra = {}) {
  if (!proposal) {
    return "";
  }
  const explicitTitle = String(proposal.title || extra.title || "").trim();
  if (proposal.type !== "custom" && explicitTitle) {
    return explicitTitle;
  }
  return getAgentPurposeTitleFromText(getAgentPurposeTextFromProposal(proposal, extra))
    || (explicitTitle && !isGenericAgentPurposeTitle(explicitTitle) ? explicitTitle : "")
    || "Workflow helper";
}

function getAgentProposalLocalActionTitle(proposal) {
  if (proposal?.type === "web-monitor") {
    return "Web monitor";
  }
  if (proposal?.type === "email-digest") {
    return "Email digest";
  }
  if (proposal?.type === "calendar-summary") {
    return "Meeting summary";
  }
  if (proposal?.type === "whatsapp-replies") {
    return "WhatsApp helper";
  }
  if (proposal?.type === "reengagement") {
    return "Customer follow-up";
  }
  if (proposal?.type === "source-action") {
    return "Source action";
  }
  if (proposal?.type === "custom") {
    return getAgentProposalPurposeTitle(proposal);
  }
  return proposal?.title || proposal?.helpers?.[0]?.name || "Agent helper";
}

function getAgentProposalLocalActionPreview(proposal) {
  if (proposal?.type === "web-monitor") {
    const pieces = [
      getAgentProposalFieldValue(proposal, "watchQuery"),
      getAgentProposalFieldValue(proposal, "location"),
      getAgentProposalFieldValue(proposal, "timeWindow"),
    ].filter(Boolean);
    return pieces.length ? pieces.join(" · ") : proposal.summary;
  }
  return proposal?.summary || proposal?.helpers?.[0]?.purpose || "";
}

function getSignedInDeliveryEmail() {
  return normalizeEmail(authSession?.email || activeEmail || "");
}

function formatAgentPlatformAddress(platform, value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  if (normalizeAgentDeliveryChannel(platform) === "whatsapp" && /^\+?[\d\s().-]{7,}$/.test(text)) {
    const digits = text.replace(/\D/g, "");
    return digits ? `+${digits}` : text;
  }
  return text;
}

function getConnectedPlatformAddress(platform) {
  const normalized = normalizeAgentDeliveryChannel(platform) || String(platform || "").trim().toLowerCase();
  if (normalized === "email") {
    return getSignedInDeliveryEmail();
  }

  if (normalized === "whatsapp") {
    const savedConnection = state.whatsappConnection
      ? normalizeFeatureWhatsApp(state.whatsappConnection)
      : null;
    const savedAddress = formatAgentPlatformAddress(
      "whatsapp",
      savedConnection?.owner_wa_id || savedConnection?.display_phone_number,
    );
    if (savedAddress) {
      return savedAddress;
    }

    const featureCandidates = [
      getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID),
      ...(Array.isArray(clientState?.features) ? clientState.features.filter((feature) => isWhatsAppFeature(feature)) : []),
    ].filter(Boolean);
    for (const feature of featureCandidates) {
      const configs = [feature.whatsapp, feature.savedWhatsApp, feature.saved_whatsapp]
        .map((config) => normalizeFeatureWhatsApp(config || {}));
      for (const config of configs) {
        const address = formatAgentPlatformAddress("whatsapp", config.owner_wa_id || config.display_phone_number);
        if (address) {
          return address;
        }
      }
    }
  }

  const connection = getPlatformConnectionByPlatform(normalized);
  const metadata = connection?.metadata && typeof connection.metadata === "object" ? connection.metadata : {};
  return formatAgentPlatformAddress(normalized, metadata.account || metadata.workspace || metadata.label);
}

// Every action reports back through the in-app notification centre. Other
// channels are not wired up, so the editors keep delivery fixed here instead of
// offering a picker that cannot change anything.
const AGENT_ACTION_DELIVERY_CHANNEL = "portal";

function getAgentDeliveryOptionItems() {
  return [
    { value: "portal", label: "Notifications" },
    { value: "email", label: "Email", address: getConnectedPlatformAddress("email") },
    { value: "telegram", label: "Telegram", address: getConnectedPlatformAddress("telegram") },
    { value: "whatsapp", label: "WhatsApp", address: getConnectedPlatformAddress("whatsapp") },
  ].map((option) => ({
    ...option,
    label: option.address ? `${option.label} (${option.address})` : option.label,
  }));
}

function getAgentDeliveryOptionsSignature() {
  return getAgentDeliveryOptionItems()
    .map((option) => `${option.value}:${option.label}`)
    .join("|");
}

function getAgentProposalDeliveryChannel(proposal) {
  if (proposal?.type === "whatsapp-replies") {
    return normalizeAgentDeliveryChannel(getAgentProposalFieldValue(proposal, "deliveryChannel")) || "portal";
  }
  const settings = getAgentProposalExecutionSettings(proposal);
  return normalizeAgentDeliveryChannel(settings.deliveryChannel)
    || normalizeAgentDeliveryChannel(getAgentProposalFieldValue(proposal, "deliveryChannel"))
    || normalizeAgentDeliveryChannel(proposal?.requestText || "")
    || "portal";
}

function getAgentProposalDeliveryTarget(proposal, deliveryChannel = "") {
  const explicitTarget = String(
    proposal?.executionPlan?.deliveryTarget
    || proposal?.executionPlan?.settings?.deliveryTarget
    || proposal?.executionPlan?.action?.recipientRef
    || "",
  ).trim();
  const normalizedChannel = normalizeAgentDeliveryChannel(deliveryChannel);
  if (normalizedChannel === "email") {
    return validateEmail(explicitTarget) ? normalizeEmail(explicitTarget) : getSignedInDeliveryEmail();
  }
  return explicitTarget && explicitTarget !== "owner"
    ? explicitTarget
    : getConnectedPlatformAddress(normalizedChannel);
}

function formatAgentDeliveryTargetDetail(deliveryChannel = "", deliveryTarget = "") {
  const channelLabel = formatAgentScheduledMessageChannel(deliveryChannel);
  const targetLabel = String(deliveryTarget || "").trim();
  const normalizedChannel = normalizeAgentDeliveryChannel(deliveryChannel);
  const targetIsChannel = normalizedChannel && normalizeAgentDeliveryChannel(targetLabel) === normalizedChannel;
  return targetLabel && !targetIsChannel ? `${channelLabel} (${targetLabel})` : channelLabel;
}

function formatAgentDeliveryTargetSentence(deliveryChannel = "", deliveryTarget = "") {
  const channelLabel = formatAgentScheduledMessageChannel(deliveryChannel);
  const targetLabel = String(deliveryTarget || "").trim();
  return targetLabel ? `by ${channelLabel} to ${targetLabel}` : `by ${channelLabel}`;
}

function createAgentProposalLocalAction(proposal) {
  if (!proposal || !proposal.approved || proposal.type === "scheduled-message") {
    return null;
  }

  const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
  const deliveryTarget = getAgentProposalDeliveryTarget(proposal, deliveryChannel);
  const deliveryLabel = formatAgentDeliveryTargetDetail(deliveryChannel, deliveryTarget);
  const approvedAt = String(proposal.approvedAt || proposal.updatedAt || proposal.createdAt || new Date().toISOString());
  const backendFeatureId = String(proposal.executionPlan?.backendFeatureId || proposal.relatedFeatureId || "").trim();
  const backendFeature = backendFeatureId ? getFeatureById(backendFeatureId) : null;
  const backendFeatureActive = backendFeatureId ? isFeatureActivated(backendFeature) : false;
  const manualOnly = getAgentProposalManualOnly(proposal, backendFeature);
  const lifecycleStatus = getAgentProposalLifecycleStatus(proposal);
  const runSchedule = getAgentProposalRunSchedule(proposal, manualOnly);
  const status = backendFeatureId
    ? (backendFeatureActive ? (manualOnly ? "manual_only" : "running") : (manualOnly ? "cancelled" : "paused"))
    : (
      lifecycleStatus === "removed"
        ? "cancelled"
        : lifecycleStatus === "paused" && !manualOnly
          ? "paused"
          : (proposal.missingCredential ? "pending" : (manualOnly ? "manual_only" : "running"))
    );
  return {
    id: `proposal:${proposal.id}`,
    actionType: `agent_${String(proposal.type || "helper").replace(/[^a-zA-Z0-9]+/g, "_")}`,
    channel: deliveryChannel || "agent",
    recipientRef: deliveryTarget || deliveryChannel,
    runAt: approvedAt,
    timezone: normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC",
    status,
    attemptCount: 0,
    providerMessageId: "",
    payload: {
      source: "agent_proposal",
      proposalId: proposal.id,
      proposalType: proposal.type,
      backendFeatureId,
      backendFeatureActive,
      title: getAgentProposalLocalActionTitle(proposal),
      preview: getAgentProposalLocalActionPreview(proposal),
      summary: proposal.summary,
      watchQuery: getAgentProposalFieldValue(proposal, "watchQuery"),
      location: getAgentProposalFieldValue(proposal, "location"),
      timeWindow: getAgentProposalFieldValue(proposal, "timeWindow"),
      manualRunMonth: getAgentProposalFieldValue(proposal, "manualRunMonth"),
      outputFolder: getAgentProposalFieldValue(proposal, "outputFolder"),
      result: getAgentProposalFieldValue(proposal, "result"),
      frequency: manualOnly
        ? "manual only"
        : (proposal.executionPlan?.frequency || getAgentProposalFieldValue(proposal, "frequency")),
      manualOnly,
      actionLifecycleStatus: lifecycleStatus,
      runDate: runSchedule.runDate,
      runTime: runSchedule.runTime,
      runTimezone: runSchedule.timezone,
      nextRunAt: runSchedule.nextRunAt,
      deliveryChannel,
      deliveryTarget,
      deliveryLabel,
      initialRunStatus: String(proposal.executionPlan?.initialRunStatus || "").trim(),
      initialRunMessage: String(proposal.executionPlan?.initialRunMessage || "").trim(),
      initialRunError: String(proposal.executionPlan?.initialRunError || "").trim(),
    },
    local: true,
    lastError: backendFeatureId && !backendFeatureActive && manualOnly ? "This manual action is available when you choose Run now." : "",
    claimedAt: "",
    completedAt: backendFeatureId && !backendFeatureActive && manualOnly ? String(backendFeature?.deactivatedAt || proposal.updatedAt || approvedAt) : "",
    createdAt: approvedAt,
    updatedAt: String(proposal.updatedAt || approvedAt),
  };
}

function getAgentProposalLocalActions() {
  return getAgentWorkspace().proposals
    .map(createAgentProposalLocalAction)
    .filter(Boolean);
}

function getMonitorFeatureLiveActionPreview(feature, settings = getSavedFeatureSettings(feature)) {
  const watchItems = normalizeMonitorWatchItems(settings.watchItems);
  if (watchItems.length) {
    return watchItems.join(" · ");
  }
  return String(feature?.description || "Saved web monitor").trim();
}

function getMonitorFeatureDeliveryTarget(settings = {}, deliveryChannel = "") {
  const explicitTarget = String(settings.deliveryTarget || settings.recipientRef || "").trim();
  if (explicitTarget && explicitTarget !== "owner") {
    return explicitTarget;
  }
  if (deliveryChannel === "email") {
    return getSignedInDeliveryEmail();
  }
  if (deliveryChannel === "telegram") {
    return String(settings.telegramChatId || "").trim() || getConnectedPlatformAddress("telegram");
  }
  return getConnectedPlatformAddress(deliveryChannel);
}

function getMonitorFeatureActionLifecycleStatus(settings = {}) {
  return normalizeMonitorActionLifecycleStatus(
    settings.actionLifecycleStatus
      || settings.action_lifecycle_status
      || settings.lifecycleStatus
      || settings.lifecycle_status,
  );
}

function hasMonitorFeatureActionSettings(feature, settings = getSavedFeatureSettings(feature)) {
  return Boolean(
    normalizeMonitorWatchItems(settings.watchItems).length
    || String(feature?.settingsSavedAt || feature?.setupStatus?.settingsSavedAt || "").trim()
    || String(feature?.activatedAt || feature?.deactivatedAt || "").trim()
  );
}

function createMonitorFeatureLiveAction(feature) {
  if (!feature || !isMonitorFeature(feature)) {
    return null;
  }

  const settings = getSavedFeatureSettings(feature);
  const lifecycleStatus = getMonitorFeatureActionLifecycleStatus(settings);
  const backendFeatureActive = isFeatureActivated(feature);
  if (!backendFeatureActive && (lifecycleStatus === "removed" || !hasMonitorFeatureActionSettings(feature, settings))) {
    return null;
  }
  const manualOnly = normalizeMonitorManualOnly(settings.manualOnly);
  const deliveryChannel = normalizeAgentDeliveryChannel(settings.deliveryChannel) || "email";
  const deliveryTarget = getMonitorFeatureDeliveryTarget(settings, deliveryChannel);
  const nextRunAt = manualOnly
    ? ""
    : (
      resolveMonitorNextRunAt(feature)
      || String(feature.nextRunAt || feature.setupStatus?.nextRunAt || "").trim()
      || String(feature.lastRunAt || feature.setupStatus?.lastRunAt || "").trim()
      || String(feature.activatedAt || feature.settingsSavedAt || feature.setupStatus?.settingsSavedAt || "").trim()
      || new Date().toISOString()
    );
  const createdAt = String(feature.activatedAt || feature.settingsSavedAt || feature.setupStatus?.settingsSavedAt || nextRunAt).trim();
  const updatedAt = String(feature.lastRunAt || feature.setupStatus?.lastRunAt || feature.settingsSavedAt || createdAt).trim();
  const watchItems = normalizeMonitorWatchItems(settings.watchItems);
  const deliveryLabel = formatAgentDeliveryTargetDetail(deliveryChannel, deliveryTarget);

  return {
    id: `feature:${feature.id}`,
    actionType: "agent_web_monitor",
    channel: deliveryChannel,
    recipientRef: deliveryTarget || deliveryChannel,
    runAt: nextRunAt,
    timezone: getMonitorScheduleTimezone(feature),
    status: manualOnly ? "manual_only" : (backendFeatureActive ? "running" : "paused"),
    attemptCount: 0,
    providerMessageId: "",
    payload: {
      source: "feature",
      backendFeatureId: feature.id,
      backendFeatureActive,
      title: "Web monitor",
      preview: getMonitorFeatureLiveActionPreview(feature, settings),
      summary: String(feature.description || "").trim(),
      watchItems,
      frequency: formatAgentWebMonitorFrequency(settings),
      manualOnly,
      actionLifecycleStatus: lifecycleStatus,
      deliveryChannel,
      deliveryTarget,
      deliveryLabel,
      lastRunAt: String(feature.lastRunAt || feature.setupStatus?.lastRunAt || "").trim(),
      lastRunStatus: String(feature.lastRunStatus || feature.setupStatus?.lastRunStatus || "").trim(),
      nextRunAt,
    },
    local: true,
    lastError: backendFeatureActive ? "" : "This action is paused.",
    claimedAt: "",
    completedAt: "",
    createdAt,
    updatedAt,
  };
}

function getAgentFeatureLiveActions() {
  return clientState.features
    .map(createMonitorFeatureLiveAction)
    .filter(Boolean);
}

function getRenderableAgentActions() {
  const backendActions = Array.isArray(state.scheduledActions) ? state.scheduledActions : [];
  const sourceActions = Array.isArray(state.sourceActions) ? state.sourceActions.map(normalizeSourceAction) : [];
  const proposalActions = getAgentProposalLocalActions();
  const proposalFeatureIds = new Set(
    proposalActions
      .map((action) => String(action.payload?.backendFeatureId || "").trim())
      .filter(Boolean),
  );
  const featureActions = getAgentFeatureLiveActions()
    .filter((action) => !proposalFeatureIds.has(String(action.payload?.backendFeatureId || "").trim()));
  return [
    ...featureActions,
    ...proposalActions,
    ...sourceActions,
    ...backendActions,
  ];
}

function isActiveAgentActionStatus(status, action = null) {
  return ["pending", "running", "manual_only", "paused"].includes(getScheduledActionStatusClass(status, action));
}

function canCancelAgentAction(action) {
  return isActiveAgentActionStatus(action?.status, action);
}

function appendAgentActionButton(actions, options = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = String(options.className || "ghost-button small").trim();
  button.textContent = String(options.text || "").trim();
  button.disabled = Boolean(options.disabled);
  button.setAttribute("aria-busy", String(Boolean(options.busy)));
  if (options.ariaLabel) {
    button.setAttribute("aria-label", options.ariaLabel);
  }
  const dataset = options.dataset && typeof options.dataset === "object" ? options.dataset : {};
  Object.entries(dataset).forEach(([key, value]) => {
    button.dataset[key] = String(value);
  });
  actions.append(button);
  return button;
}

function createAgentActionSavingIndicator(message = "Saving action…") {
  const status = document.createElement("span");
  status.className = "agent-action-detail-saving is-saving";
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  const spinner = document.createElement("span");
  spinner.className = "agent-action-editor-status-spinner";
  spinner.setAttribute("aria-hidden", "true");
  const text = document.createElement("span");
  text.textContent = message;
  status.append(spinner, text);
  return status;
}

function createAgentActionDetailActions(action) {
  if (!canCancelAgentAction(action)) {
    return null;
  }

  const actions = document.createElement("div");
  actions.className = "agent-action-detail-actions";
  if (isAgentLocalActionSettingsBusy(action)) {
    actions.append(createAgentActionSavingIndicator());
    return actions;
  }

  const featureId = getAgentActionBackendFeatureId(action);
  const sourceActionId = getAgentActionSourceActionId(action);
  const paused = isAgentLifecycleActionPaused(action);
  const lifecycleBusy = isAgentActionLifecycleBusy(action);
  if (sourceActionId && !paused) {
    appendAgentActionButton(actions, {
      className: "primary-button small agent-action-run-button",
      text: "Run now",
      ariaLabel: "Run source action now",
      dataset: { agentRunSourceAction: sourceActionId },
    });
  }
  if (isAgentProposalLocalAction(action) && action.payload?.manualOnly) {
    const actionId = String(action.id || "");
    const isBusy = localActionRunBusy.has(actionId);
    const backendFeatureId = String(action.payload?.backendFeatureId || "").trim();
    const dataset = {};
    if (backendFeatureId && action.actionType === "agent_web_monitor") {
      dataset.agentRunMonitorAction = backendFeatureId;
    } else {
      dataset.agentRunLocalAction = actionId;
    }
    appendAgentActionButton(actions, {
      className: "primary-button small agent-action-run-button",
      text: isBusy ? "Running…" : "Run now",
      disabled: isBusy,
      busy: isBusy,
      ariaLabel: `Run ${getScheduledActionTitle(action)} now`,
      dataset,
    });
  }
  if (isAgentFeatureLiveAction(action) && action.actionType === "agent_web_monitor" && featureId && !paused) {
    const isBusy = monitorActionRunBusy.has(featureId);
    appendAgentActionButton(actions, {
      className: "primary-button small agent-action-run-button",
      text: isBusy ? "Running…" : "Run now",
      disabled: isBusy,
      busy: isBusy,
      ariaLabel: `${isBusy ? "Running" : "Run"} ${getScheduledActionTitle(action)} now`,
      dataset: { agentRunMonitorAction: featureId },
    });
  }

  if (canToggleAgentActionLifecycle(action)) {
    const actionId = String(action.id || "");
    const nextLabel = paused ? "Start" : "Stop";
    const busyText = paused ? "Starting…" : "Stopping…";
    const dataset = {};
    if (sourceActionId) {
      dataset[paused ? "agentResumeSourceAction" : "agentStopSourceAction"] = sourceActionId;
    } else {
      dataset[paused ? "agentResumeLocalAction" : "agentStopLocalAction"] = actionId;
    }
    appendAgentActionButton(actions, {
      className: `${paused ? "primary-button agent-action-start-button" : "ghost-button agent-action-stop-button"} small`,
      text: lifecycleBusy ? busyText : nextLabel,
      disabled: lifecycleBusy,
      busy: lifecycleBusy,
      ariaLabel: `${nextLabel} ${getScheduledActionTitle(action)}`,
      dataset,
    });
  }

  if (isAgentLocalAction(action)) {
    if (sourceActionId) {
      appendAgentActionButton(actions, {
        className: "ghost-button small agent-action-danger-button",
        text: "Remove action",
        ariaLabel: "Remove source action",
        dataset: { agentRemoveSourceAction: sourceActionId },
      });
      return actions;
    }
    appendAgentActionButton(actions, {
      className: "ghost-button small agent-action-danger-button",
      text: "Remove action",
      ariaLabel: `Remove ${getScheduledActionTitle(action)}`,
      dataset: { agentRemoveLocalAction: String(action.id || "") },
    });
  } else {
    appendAgentActionButton(actions, {
      className: "ghost-button small agent-action-danger-button",
      text: "Cancel action",
      ariaLabel: `Cancel ${getScheduledActionTitle(action)}`,
      dataset: { agentCancelScheduledAction: String(action.id || "") },
    });
  }

  return actions;
}

function getScheduledActionStatusLabel(status, action = null) {
  const labels = {
    pending: "Scheduled",
    running: "Sending",
    paused: "Paused",
    sent: "Sent",
    delivered: "Delivered",
    read: "Read",
    failed: "Failed",
    cancelled: "Cancelled",
  };
  const normalized = getScheduledActionStatusClass(status, action);
  if (isAgentLocalAction(action)) {
    if (normalized === "manual_only") {
      return "Manual";
    }
    if (normalized === "running") {
      return "Live";
    }
    if (normalized === "paused") {
      return "Stopped";
    }
    if (normalized === "pending") {
      return "Ready";
    }
  }
  return labels[normalized] || capitalizeWords(normalized.replace(/[_-]+/g, " ")) || "Unknown";
}

function getScheduledActionStatusClass(status, action = null) {
  return action ? getAgentActionPresentationStatus(action, status) : normalizeScheduledActionStatusClass(status);
}

function getScheduledActionTitle(action) {
  const payloadTitle = String(action?.payload?.title || "").trim();
  if (payloadTitle && !isGenericAgentPurposeTitle(payloadTitle)) {
    return payloadTitle;
  }
  if (isAgentLocalAction(action)) {
    const proposal = getAgentLocalActionProposal(action);
    const proposalTitle = proposal ? getAgentProposalLocalActionTitle(proposal) : "";
    if (proposalTitle && !isGenericAgentPurposeTitle(proposalTitle)) {
      return proposalTitle;
    }
    const payloadPurposeTitle = getAgentPurposeTitleFromText(getAgentPurposeTextFromAction(action));
    if (payloadPurposeTitle) {
      return payloadPurposeTitle;
    }
    return normalizeAgentActionTypeLabel(action?.actionType) || "Agent helper";
  }
  if (payloadTitle) {
    return payloadTitle;
  }
  const channel = formatAgentScheduledMessageChannel(action?.channel);
  if (String(action?.actionType || "").trim() === "send_message") {
    return `${channel} message`;
  }
  return "Scheduled action";
}

function formatScheduledActionDate(value, timeZone = "") {
  const text = String(value || "").trim();
  if (!text) {
    return "Not available";
  }
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return text;
  }
  const normalizedTimeZone = normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined;
  const options = {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    timeZone: normalizedTimeZone,
  };
  if (parsed.getFullYear() !== new Date().getFullYear()) {
    options.year = "numeric";
  }
  return new Intl.DateTimeFormat(undefined, options).format(parsed);
}

function createScheduledActionStatus(action) {
  const status = document.createElement("span");
  const statusClass = getScheduledActionStatusClass(action.status, action);
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const isRunBusy = isAgentLocalActionRunBusy(action)
    || Boolean(
      isAgentFeatureLiveAction(action)
      && action.actionType === "agent_web_monitor"
      && featureId
      && monitorActionRunBusy.has(featureId),
    );
  const isLifecycleBusy = isAgentActionLifecycleBusy(action);
  status.className = `agent-action-status is-${isRunBusy ? "run-busy" : isLifecycleBusy ? "lifecycle-busy" : statusClass}`;
  status.textContent = isRunBusy
    ? "Running"
    : isLifecycleBusy
      ? (isAgentLifecycleActionPaused(action) ? "Starting" : "Stopping")
      : getScheduledActionStatusLabel(action.status, action);
  return status;
}

function getScheduledActionItemTimeValue(action) {
  return isActiveAgentActionStatus(action.status, action)
    ? action.runAt
    : (action.completedAt || action.updatedAt);
}

function getScheduledActionCreatedTime(action) {
  const value = action?.createdAt || action?.created_at || action?.payload?.createdAt || action?.payload?.created_at;
  const parsed = new Date(value).getTime();
  return Number.isNaN(parsed) ? Number.NEGATIVE_INFINITY : parsed;
}

function sortScheduledActionsByCreatedAt(actions) {
  return actions
    .map((action, index) => ({ action, index }))
    .sort((left, right) => {
      const createdDifference = getScheduledActionCreatedTime(right.action) - getScheduledActionCreatedTime(left.action);
      return createdDifference || left.index - right.index;
    })
    .map((entry) => entry.action);
}

function formatAgentActionChoiceCreated(action) {
  const createdTime = getScheduledActionCreatedTime(action);
  if (!Number.isFinite(createdTime)) {
    return "";
  }
  return formatScheduledActionDate(new Date(createdTime).toISOString(), action?.timezone);
}

function getAgentActionChoices() {
  const active = sortScheduledActionsByCreatedAt(
    getRenderableAgentActions().filter((action) => isActiveAgentActionStatus(action.status, action)),
  );
  return active
    .slice(0, AGENT_ACTION_CHOICE_LIMIT)
    .map((action) => ({
      id: String(action.id || ""),
      name: getScheduledActionTitle(action),
      status: getScheduledActionStatusLabel(action.status, action),
      created: formatAgentActionChoiceCreated(action),
    }))
    .filter((choice) => Boolean(choice.name));
}

function getAgentActionChoiceValue(choice) {
  // A picked choice goes back to the agent as ordinary chat text. The rendered
  // list already numbers repeated titles, so the name on its own names one
  // action.
  return `The “${String(choice?.name || "").trim()}” action`;
}

function buildAgentActionContext() {
  return getAgentActionChoices().map((choice) => ({
    name: choice.name,
    status: choice.status,
    created: choice.created,
  }));
}

function getScheduledActionItemSignature(action) {
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const statusClass = getScheduledActionStatusClass(action.status, action);
  const hideTime = Boolean(action.payload?.manualOnly) || statusClass === "paused";
  return JSON.stringify([
    action.id,
    getScheduledActionTitle(action),
    statusClass,
    getScheduledActionStatusLabel(action.status, action),
    hideTime ? "" : formatScheduledActionDate(getScheduledActionItemTimeValue(action), action.timezone),
    String(action.payload?.frequency || ""),
    String(action.payload?.manualRunMonth || ""),
    String(action.payload?.outputFolder || ""),
    String(action.payload?.result || ""),
    String(action.payload?.lastRunAt || ""),
    String(action.payload?.lastRunStatus || ""),
    String(action.payload?.nextRunAt || ""),
    Array.isArray(action.payload?.watchItems) ? action.payload.watchItems.join("|") : "",
    getAgentDeliveryOptionsSignature(),
    String(monitorActionRunBusy.has(featureId)),
    String(isAgentActionLifecycleBusy(action)),
    String(isAgentLocalActionSettingsBusy(action)),
    String(isAgentLocalActionRunBusy(action)),
  ]);
}

function getScheduledActionListSignature(actions, emptyMessage) {
  if (!actions.length) {
    return JSON.stringify(["empty", emptyMessage]);
  }
  return JSON.stringify(actions.map(getScheduledActionItemSignature));
}

function getScheduledActionDomKey(action, index = 0) {
  const id = String(action?.id || "").trim();
  if (id) {
    return id;
  }
  return `anonymous:${index}:${getScheduledActionItemSignature(action)}`;
}

function shouldAnimateScheduledActionEntries(container) {
  return container.dataset.agentActionListMounted === "true"
    && !state.scheduledActionsLoading
    && !state.sourceActionsLoading
    && !scheduledActionsRefreshPromise
    && !sourceActionsRefreshPromise;
}

function applyScheduledActionItemEnteringState(item) {
  if (!item) {
    return;
  }
  item.classList.add("is-entering");
  item.addEventListener("animationend", () => {
    item.classList.remove("is-entering");
  }, { once: true });
}

function renderScheduledActionItemContent(item, action) {
  const statusClass = getScheduledActionStatusClass(action.status, action);
  item.className = `agent-action-item is-${statusClass}`;
  item.dataset.agentScheduledActionId = String(action.id || "");
  item.dataset.agentActionItemSignature = getScheduledActionItemSignature(action);
  if (agentActionSpotlightId && String(action.id || "") === agentActionSpotlightId) {
    item.classList.add("is-spotlighted");
  }

  const isExpanded = state.selectedScheduledActionId === String(action.id);
  if (isExpanded) {
    item.classList.add("is-expanded");
  }

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "agent-action-item-trigger";
  trigger.dataset.agentScheduledActionTrigger = String(action.id || "");
  trigger.setAttribute("aria-expanded", String(isExpanded));
  trigger.setAttribute("aria-controls", `agent-action-expansion-${String(action.id || "")}`);
  trigger.setAttribute("aria-label", `${isExpanded ? "Collapse" : "Open"} ${getScheduledActionTitle(action)}, ${getScheduledActionStatusLabel(action.status, action)}`);

  const head = document.createElement("span");
  head.className = "agent-action-item-head";
  const title = document.createElement("strong");
  title.textContent = getScheduledActionTitle(action);
  head.append(title, createScheduledActionStatus(action));

  const time = document.createElement("span");
  time.className = "agent-action-item-time";
  const hideTime = Boolean(action.payload?.manualOnly) || statusClass === "paused";
  time.textContent = hideTime
    ? ""
    : formatScheduledActionDate(
      getScheduledActionItemTimeValue(action),
      action.timezone,
    );
  time.hidden = hideTime;

  trigger.append(head, time);

  const expansion = document.createElement("div");
  expansion.id = `agent-action-expansion-${String(action.id || "")}`;
  expansion.className = "agent-action-item-expansion";
  expansion.setAttribute("role", "region");
  expansion.setAttribute("aria-label", `${getScheduledActionTitle(action)} details`);
  expansion.setAttribute("aria-hidden", String(!isExpanded));
  expansion.inert = !isExpanded;

  const expansionInner = document.createElement("div");
  expansionInner.className = "agent-action-item-expansion-inner";
  expansionInner.append(createScheduledActionDetail(action));
  expansion.append(expansionInner);

  item.replaceChildren(trigger, expansion);
}

function createScheduledActionItem(action, options = {}) {
  const item = document.createElement("article");
  renderScheduledActionItemContent(item, action);
  if (options.entering) {
    applyScheduledActionItemEnteringState(item);
  }
  return item;
}

function createScheduledActionEmpty(message) {
  const empty = document.createElement("p");
  empty.className = "agent-action-empty";
  empty.textContent = message;
  return empty;
}

function createAgentLoadingRow(message) {
  const loading = document.createElement("div");
  loading.className = "agent-loading-row";
  loading.setAttribute("role", "status");
  loading.setAttribute("aria-live", "polite");

  const spinner = document.createElement("span");
  spinner.className = "agent-loading-spinner";
  spinner.setAttribute("aria-hidden", "true");

  const text = document.createElement("span");
  text.textContent = message;
  loading.append(spinner, text);
  return loading;
}

function renderScheduledActionLoadingList(container, message) {
  const signature = JSON.stringify(["loading", message]);
  if (container.dataset.agentActionListSignature === signature) {
    return;
  }
  container.dataset.agentActionListSignature = signature;
  container.replaceChildren(createAgentLoadingRow(message));
  container.dataset.agentActionListMounted = "true";
}

function renderScheduledActionList(container, actions, emptyMessage) {
  const signature = getScheduledActionListSignature(actions, emptyMessage);
  if (container.dataset.agentActionListSignature === signature) {
    return;
  }

  const existingItemsByKey = new Map();
  for (const item of container.querySelectorAll("[data-agent-action-key]")) {
    existingItemsByKey.set(item.dataset.agentActionKey, item);
  }

  const animateNewEntries = shouldAnimateScheduledActionEntries(container);
  const nextItems = actions.length
    ? actions.map((action, index) => {
      const key = getScheduledActionDomKey(action, index);
      const existingItem = existingItemsByKey.get(key);
      if (existingItem) {
        existingItemsByKey.delete(key);
        if (existingItem.dataset.agentActionItemSignature !== getScheduledActionItemSignature(action)) {
          renderScheduledActionItemContent(existingItem, action);
        }
        existingItem.dataset.agentActionKey = key;
        return existingItem;
      }

      const item = createScheduledActionItem(action, { entering: animateNewEntries });
      item.dataset.agentActionKey = key;
      return item;
    })
    : [createScheduledActionEmpty(emptyMessage)];

  container.dataset.agentActionListSignature = signature;
  container.replaceChildren(...nextItems);
  container.dataset.agentActionListMounted = "true";
}

function setScheduledActionItemExpandedState(item, isExpanded) {
  if (!item) {
    return;
  }

  item.classList.toggle("is-expanded", isExpanded);
  const trigger = item.querySelector("[data-agent-scheduled-action-trigger]");
  const expansion = item.querySelector(".agent-action-item-expansion");
  const actionTitle = item.querySelector(".agent-action-item-head strong")?.textContent || "Action";
  trigger?.setAttribute("aria-expanded", String(isExpanded));
  trigger?.setAttribute("aria-label", `${isExpanded ? "Collapse" : "Open"} ${actionTitle}`);
  expansion?.setAttribute("aria-hidden", String(!isExpanded));
  if (expansion) {
    expansion.inert = !isExpanded;
  }
}

function syncScheduledActionSelection() {
  const selectedActionId = String(state.selectedScheduledActionId || "");
  for (const item of document.querySelectorAll("[data-agent-scheduled-action-id]")) {
    setScheduledActionItemExpandedState(
      item,
      Boolean(selectedActionId) && item.dataset.agentScheduledActionId === selectedActionId,
    );
  }
}

function preserveAgentActionsScrollPosition(scrollTop) {
  const scrollContainer = elements.agentActionsPanelBody;
  if (!scrollContainer || !Number.isFinite(scrollTop)) {
    return;
  }

  scrollContainer.scrollTop = scrollTop;
  window.requestAnimationFrame(() => {
    scrollContainer.scrollTop = scrollTop;
  });
}

function selectScheduledAction(actionId) {
  const normalizedActionId = String(actionId || "");
  const scrollContainer = elements.agentActionsPanelBody;
  const scrollTop = scrollContainer?.scrollTop;
  state.selectedScheduledActionId = state.selectedScheduledActionId === normalizedActionId
    ? ""
    : normalizedActionId;

  const selectedItem = Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]"))
    .find((item) => item.dataset.agentScheduledActionId === state.selectedScheduledActionId);
  const previousItem = Array.from(document.querySelectorAll(".agent-action-item.is-expanded"))[0];
  if (selectedItem || previousItem) {
    // Keep the existing DOM nodes so the card can animate from its current
    // height. Replacing the list here would make the new card appear already
    // open and would also invite the browser to re-anchor the scroll view.
    syncScheduledActionSelection();
    preserveAgentActionsScrollPosition(scrollTop);
    return;
  }

  renderAgentActions();
  preserveAgentActionsScrollPosition(scrollTop);
}

function shouldReduceAgentMotion() {
  return Boolean(
    window.matchMedia
    && window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  );
}

function findAgentActionItem(actionId) {
  const normalizedActionId = String(actionId || "").trim();
  if (!normalizedActionId) {
    return null;
  }
  return Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]"))
    .find((item) => item.dataset.agentScheduledActionId === normalizedActionId) || null;
}

function clearAgentActionSpotlight() {
  agentActionSpotlightId = "";
  if (agentActionSpotlightTimer !== null) {
    window.clearTimeout(agentActionSpotlightTimer);
    agentActionSpotlightTimer = null;
  }
  for (const item of document.querySelectorAll(".agent-action-item.is-spotlighted")) {
    item.classList.remove("is-spotlighted");
  }
  elements.agentPanelActionsModeButton?.classList.remove("is-guided");
}

function applyAgentActionSpotlight(actionId) {
  const normalizedActionId = String(actionId || "").trim();
  const item = findAgentActionItem(normalizedActionId);
  if (!item) {
    return false;
  }

  item.classList.remove("is-spotlighted");
  // Restart the shimmer when the user taps the same "here" link twice.
  void item.offsetWidth;
  item.classList.add("is-spotlighted");
  const focusTarget = item.querySelector("[data-agent-scheduled-action-trigger]") || item;
  if (typeof focusTarget.focus === "function") {
    focusTarget.focus({ preventScroll: true });
  }

  if (agentActionSpotlightTimer !== null) {
    window.clearTimeout(agentActionSpotlightTimer);
  }
  agentActionSpotlightTimer = window.setTimeout(clearAgentActionSpotlight, shouldReduceAgentMotion() ? 1800 : 2600);
  return true;
}

function guideAgentActionsTab() {
  elements.agentPanelActionsModeButton?.classList.remove("is-guided");
  void elements.agentPanelActionsModeButton?.offsetWidth;
  elements.agentPanelActionsModeButton?.classList.add("is-guided");
  if (agentActionSpotlightTimer !== null) {
    window.clearTimeout(agentActionSpotlightTimer);
  }
  agentActionSpotlightTimer = window.setTimeout(clearAgentActionSpotlight, shouldReduceAgentMotion() ? 1800 : 3600);
}

function showAgentActionInPanel(actionId) {
  const normalizedActionId = String(actionId || "").trim();
  if (!normalizedActionId) {
    return false;
  }

  const targetAction = getRenderableAgentActions()
    .find((action) => String(action.id || "") === normalizedActionId);
  agentActionSpotlightId = normalizedActionId;
  state.selectedScheduledActionId = "";
  if (targetAction && !isActiveAgentActionStatus(targetAction.status, targetAction)) {
    state.agentHistoryExpanded = true;
  }

  setAgentToolsOpen(true);
  setAgentPanelMode("actions");

  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(() => {
      const item = findAgentActionItem(normalizedActionId);
      if (!item) {
        guideAgentActionsTab();
        return;
      }
      item.scrollIntoView({
        behavior: shouldReduceAgentMotion() ? "auto" : "smooth",
        block: "center",
        inline: "nearest",
      });
      applyAgentActionSpotlight(normalizedActionId);
    });
  });
  return true;
}

function handleScheduledActionListClick(event) {
  const target = getEventTargetElement(event);
  const scheduledActionTrigger = target?.closest("[data-agent-scheduled-action-trigger]");
  if (!scheduledActionTrigger) {
    return;
  }
  const actionId = scheduledActionTrigger.dataset.agentScheduledActionTrigger || "";
  if (!actionId) {
    return;
  }
  event.preventDefault();
  event.stopPropagation();
  selectScheduledAction(actionId);
}

function createScheduledActionDetailRow(label, value) {
  const row = document.createElement("div");
  row.className = "agent-action-detail-row";
  const term = document.createElement("dt");
  term.textContent = label;
  const description = document.createElement("dd");
  description.textContent = value || "Not available";
  row.append(term, description);
  return row;
}

function getScheduledActionDetailSignature(action) {
  const messageText = String(
    action.payload?.preview
    || action.payload?.summary
    || action.payload?.messageText
    || action.payload?.text
    || "",
  ).trim();
  return JSON.stringify([
    action.id,
    getScheduledActionTitle(action),
    getScheduledActionStatusClass(action.status, action),
    getScheduledActionStatusLabel(action.status, action),
    messageText,
    formatScheduledActionDate(action.runAt, action.timezone),
    action.timezone || getWorkspaceTimeZone(),
    formatAgentScheduledMessageChannel(action.channel),
    String(action.attemptCount),
    formatScheduledActionDate(action.createdAt, action.timezone),
    action.completedAt ? formatScheduledActionDate(action.completedAt, action.timezone) : "",
    action.providerMessageId,
    action.lastError,
    String(action.payload?.backendFeatureActive ?? ""),
    String(action.payload?.manualOnly ?? ""),
    monitorActionRunBusy.has(String(action.payload?.backendFeatureId || "").trim()),
    localActionRunBusy.has(String(action.id || "").trim()),
    isAgentLocalActionSettingsBusy(action),
    String(action.payload?.initialRunStatus || ""),
    String(action.payload?.initialRunMessage || ""),
    String(action.payload?.initialRunError || ""),
    String(action.payload?.deliveryTarget || ""),
    String(action.payload?.deliveryLabel || ""),
    String(action.payload?.manualRunMonth || ""),
    String(action.payload?.result || ""),
    String(action.payload?.lastRunAt || ""),
    String(action.payload?.lastRunStatus || ""),
    String(action.payload?.nextRunAt || ""),
    Array.isArray(action.payload?.watchItems) ? action.payload.watchItems.join("|") : "",
  ]);
}

function getAgentMonitorEditorFrequencyValue(settings = {}) {
  const normalized = normalizeFeatureMonitorSettings(settings);
  if (normalized.manualOnly) {
    return "manual";
  }
  if (normalized.intervalMinutes) {
    return `minutes:${normalized.intervalMinutes}`;
  }
  return `days:${normalized.intervalDays}`;
}

function getAgentMonitorEditorFrequencyOptions(settings = {}) {
  const options = [
    { value: "manual", label: "Run manually" },
    { value: "minutes:5", label: "Every 5 minutes" },
    { value: "minutes:15", label: "Every 15 minutes" },
    { value: "minutes:60", label: "Hourly" },
    { value: "days:1", label: "Daily" },
    { value: "days:7", label: "Weekly" },
    { value: "days:30", label: "Monthly" },
  ];
  const currentValue = getAgentMonitorEditorFrequencyValue(settings);
  if (!options.some((option) => option.value === currentValue)) {
    options.push({ value: currentValue, label: formatAgentWebMonitorFrequency(settings) });
  }
  return options;
}

// What the editor's date and hour mean to the saved settings: the first run,
// and the hour every run after it lands on.
function getAgentMonitorEditorScheduleSettings(draft = {}, frequencyValue = "") {
  const frequency = String(frequencyValue || draft.frequency || "").trim();
  if (frequency === "manual") {
    return { scheduleStartAt: "", scheduleTimeLocal: "" };
  }
  const timezone = normalizeMonitorScheduleTimezone(draft.scheduleTimezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
  const runTime = normalizeAgentActionRunTime(draft.runTime);
  const runDate = normalizeAgentActionRunDate(draft.runDate) || getAgentActionDefaultRunDate(frequency, runTime, timezone);
  return {
    scheduleStartAt: resolveAgentActionNextRunAt({ frequency, runDate, runTime, timezone }),
    scheduleTimeLocal: runTime,
    scheduleTimezone: timezone,
  };
}

function getAgentMonitorEditorRunSchedule(feature, settings = {}) {
  const timezone = getMonitorScheduleTimezone(feature);
  const frequency = getAgentMonitorEditorFrequencyValue(settings);
  const parts = getMonitorZonedDateTimeParts(
    normalizeMonitorScheduleStartAt(settings.scheduleStartAt) || resolveMonitorNextRunAt(feature),
    timezone,
  );
  if (parts) {
    return {
      frequency,
      timezone,
      runDate: formatAgentActionRunDate(parts),
      runTime: normalizeAgentActionRunTime(`${parts.hour}:${parts.minute}`),
    };
  }
  const runTime = normalizeAgentActionRunTime(settings.scheduleTimeLocal);
  return {
    frequency,
    timezone,
    runTime,
    runDate: getAgentActionDefaultRunDate(frequency, runTime, timezone),
  };
}

function getAgentMonitorEditorFrequencySettings(value, currentSettings = {}) {
  const normalizedValue = String(value || "").trim().toLowerCase();
  if (normalizedValue === "manual") {
    return {
      manualOnly: true,
      runMode: "manual",
      intervalMinutes: 0,
    };
  }

  const [unit, rawAmount] = normalizedValue.split(":");
  const amount = Math.max(1, Number.parseInt(rawAmount, 10) || 1);
  return {
    manualOnly: false,
    runMode: "recurring",
    intervalMinutes: unit === "minutes" ? amount : 0,
    intervalDays: unit === "days" ? amount : currentSettings.intervalDays,
  };
}

function setAgentMonitorEditorStatus(editor, message, isError = false) {
  if (!editor?.status) {
    return;
  }
  setAgentActionEditorStatusElement(editor.status, message, isError, message === "Saving changes…");
}

function scheduleAgentMonitorAutoSave(action, draft, form, options = {}) {
  const editor = form?._agentMonitorEditor;
  if (!editor) {
    return;
  }
  if (editor.saveTimer) {
    window.clearTimeout(editor.saveTimer);
  }
  if (options.status !== false) {
    setAgentMonitorEditorStatus(editor, "Saving changes…");
  }
  setAgentLocalActionSettingsBusy(action, true);
  updateAgentLocalActionDom(action);
  const delayMs = Number.isFinite(options.delayMs) ? Math.max(0, Number(options.delayMs)) : 220;
  editor.saveTimer = window.setTimeout(() => {
    editor.saveTimer = null;
    void saveAgentMonitorActionSettings(action, draft, form).catch(() => {});
  }, delayMs);
}

function updateAgentMonitorActionFrequency(action, settings) {
  const actionId = String(action?.id || "");
  const item = Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]"))
    .find((candidate) => candidate.dataset.agentScheduledActionId === actionId);
  if (!item) {
    return;
  }
  const frequencyTerm = Array.from(item.querySelectorAll("dt"))
    .find((term) => term.textContent === "Frequency");
  if (frequencyTerm?.nextElementSibling) {
    frequencyTerm.nextElementSibling.textContent = formatAgentWebMonitorFrequency(settings);
  }
}

function createAgentMonitorEditor(action) {
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const feature = getFeatureById(featureId);
  if (!feature || !isMonitorFeature(feature)) {
    return null;
  }

  const currentSettings = getSelectedFeatureSettings(feature);
  const runSchedule = getAgentMonitorEditorRunSchedule(feature, currentSettings);
  const draft = {
    watchItems: normalizeMonitorWatchItems(
      currentSettings.watchItems.length
        ? currentSettings.watchItems
        : (action?.payload?.watchItems || []),
    ),
    frequency: getAgentMonitorEditorFrequencyValue(currentSettings),
    runDate: runSchedule.runDate,
    runTime: runSchedule.runTime,
    scheduleTimezone: runSchedule.timezone,
    deliveryChannel: AGENT_ACTION_DELIVERY_CHANNEL,
  };

  const form = document.createElement("form");
  form.className = "agent-action-editor";
  form.dataset.agentMonitorEditForm = featureId;

  const topicsField = document.createElement("div");
  topicsField.className = "agent-action-editor-field";
  const topicsLabel = document.createElement("span");
  topicsLabel.className = "agent-action-editor-label";
  topicsLabel.textContent = "Topics to watch";
  const topicsList = document.createElement("div");
  topicsList.className = "agent-action-editor-topics";
  topicsList.setAttribute("role", "list");
  const topicEntry = document.createElement("div");
  topicEntry.className = "agent-action-editor-topic-entry";
  const topicInput = document.createElement("input");
  topicInput.type = "text";
  topicInput.className = "agent-action-editor-input";
  topicInput.placeholder = "Add a topic or tag";
  topicInput.setAttribute("aria-label", "Add a topic or tag");
  const addTopicButton = document.createElement("button");
  addTopicButton.type = "button";
  addTopicButton.className = "ghost-button small agent-action-editor-add";
  addTopicButton.textContent = "Add";
  topicEntry.append(topicInput, addTopicButton);
  topicsField.append(topicsLabel, topicsList, topicEntry);

  const frequencyField = document.createElement("label");
  frequencyField.className = "agent-action-editor-field";
  const frequencyLabel = document.createElement("span");
  frequencyLabel.className = "agent-action-editor-label";
  frequencyLabel.textContent = "Frequency";
  const frequencySelect = document.createElement("select");
  frequencySelect.className = "agent-action-editor-select";
  frequencySelect.setAttribute("aria-label", "Monitor frequency");
  for (const option of getAgentMonitorEditorFrequencyOptions(currentSettings)) {
    const optionElement = document.createElement("option");
    optionElement.value = option.value;
    optionElement.textContent = option.label;
    frequencySelect.append(optionElement);
  }
  frequencySelect.value = draft.frequency;
  frequencyField.append(frequencyLabel, wrapAgentActionEditorSelect(frequencySelect));

  const runDate = createAgentLocalActionEditorField("Run date", draft.runDate, { inputType: "date" });
  const runTime = createAgentLocalActionEditorField("Run time", draft.runTime, { inputType: "time" });
  const runScheduleRow = document.createElement("div");
  runScheduleRow.className = "agent-action-editor-field-row";
  runScheduleRow.append(runDate.field, runTime.field);
  const runScheduleNote = document.createElement("p");
  runScheduleNote.className = "agent-action-editor-note";

  const syncRunScheduleFields = () => {
    const showFields = draft.frequency !== "manual";
    runScheduleRow.hidden = !showFields;
    runScheduleNote.hidden = !showFields;
    runDate.input.disabled = !showFields;
    runTime.input.disabled = !showFields;
    if (!showFields) {
      return;
    }
    runDate.input.value = draft.runDate;
    runTime.input.value = draft.runTime;
    const nextRunAt = resolveAgentActionNextRunAt(draft);
    runScheduleNote.textContent = nextRunAt
      ? `Next run ${formatScheduledActionDate(nextRunAt, draft.scheduleTimezone)}`
      : "Pick the date and hour this monitor should run.";
  };

  const status = createAgentActionEditorStatusElement("agent-action-editor-status", "p");
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  status.hidden = true;

  const renderTopics = () => {
    topicsList.replaceChildren();
    if (!draft.watchItems.length) {
      const empty = document.createElement("span");
      empty.className = "agent-action-editor-empty";
      empty.textContent = "Add at least one topic.";
      topicsList.append(empty);
      return;
    }
    draft.watchItems.forEach((item, index) => {
      const chip = document.createElement("span");
      chip.className = "agent-action-editor-chip";
      chip.setAttribute("role", "listitem");
      const label = document.createElement("span");
      label.className = "agent-action-editor-chip-label";
      label.textContent = item;
      const removeButton = document.createElement("button");
      removeButton.type = "button";
      removeButton.className = "agent-action-editor-chip-remove";
      removeButton.dataset.agentMonitorEditorRemove = String(index);
      removeButton.setAttribute("aria-label", `Remove ${item}`);
      removeButton.textContent = "×";
      chip.append(label, removeButton);
      topicsList.append(chip);
    });
  };

  const addTopics = () => {
    const nextItems = normalizeMonitorWatchItems(topicInput.value);
    if (!nextItems.length) {
      topicInput.focus();
      return;
    }
    draft.watchItems = normalizeMonitorWatchItems([...draft.watchItems, ...nextItems]);
    topicInput.value = "";
    renderTopics();
    topicInput.focus();
    scheduleAgentMonitorAutoSave(action, draft, form);
  };

  addTopicButton.addEventListener("click", addTopics);
  topicInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      addTopics();
    }
  });
  topicsList.addEventListener("click", (event) => {
    const removeButton = getEventTargetElement(event)?.closest("[data-agent-monitor-editor-remove]");
    if (!removeButton) {
      return;
    }
    const index = Number.parseInt(removeButton.dataset.agentMonitorEditorRemove, 10);
    if (Number.isInteger(index)) {
      draft.watchItems.splice(index, 1);
      renderTopics();
      scheduleAgentMonitorAutoSave(action, draft, form);
    }
  });
  frequencySelect.addEventListener("change", () => {
    draft.frequency = frequencySelect.value;
    syncRunScheduleFields();
    scheduleAgentMonitorAutoSave(action, draft, form);
  });
  runDate.input.addEventListener("change", () => {
    const chosenRunDate = normalizeAgentActionRunDate(runDate.input.value);
    if (!chosenRunDate) {
      runDate.input.value = draft.runDate;
      return;
    }
    draft.runDate = chosenRunDate;
    syncRunScheduleFields();
    scheduleAgentMonitorAutoSave(action, draft, form);
  });
  runTime.input.addEventListener("change", () => {
    const chosenRunTime = normalizeAgentActionRunTime(runTime.input.value, "");
    if (!chosenRunTime) {
      runTime.input.value = draft.runTime;
      return;
    }
    draft.runTime = chosenRunTime;
    syncRunScheduleFields();
    scheduleAgentMonitorAutoSave(action, draft, form);
  });
  form._agentMonitorEditor = {
    draft,
    frequencySelect,
    status,
    saveTimer: null,
    savePromise: null,
    saveQueued: false,
  };
  form.append(topicsField, frequencyField, runScheduleRow, runScheduleNote, status);
  renderTopics();
  syncRunScheduleFields();
  return form;
}

async function saveAgentMonitorActionSettings(action, draft, form) {
  const editor = form?._agentMonitorEditor;
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const feature = getFeatureById(featureId);
  if (!editor || !feature || !isMonitorFeature(feature)) {
    return null;
  }
  if (editor.savePromise) {
    editor.saveQueued = true;
    return editor.savePromise;
  }
  if (featureConfigBusy && featureConfigSavePromise) {
    try {
      await featureConfigSavePromise;
    } catch {
      // Continue with the latest monitor edit after the other save settles.
    }
  }

  const watchItems = normalizeMonitorWatchItems(draft.watchItems);
  if (!watchItems.length) {
    setAgentMonitorEditorStatus(editor, "Add at least one topic before saving.", true);
    setAgentLocalActionSettingsBusy(action, false);
    updateAgentLocalActionDom(action);
    return null;
  }

  const currentSettings = getSelectedFeatureSettings(feature);
  const currentLifecycleStatus = normalizeMonitorActionLifecycleStatus(
    action?.payload?.actionLifecycleStatus
      || currentSettings.actionLifecycleStatus
      || currentSettings.action_lifecycle_status,
  );
  const nextSettings = buildMonitorSettingsForSave(feature, {
    ...currentSettings,
    watchItems,
    ...getAgentMonitorEditorFrequencySettings(editor.frequencySelect?.value, currentSettings),
    ...getAgentMonitorEditorScheduleSettings(draft, editor.frequencySelect?.value),
    deliveryChannel: AGENT_ACTION_DELIVERY_CHANNEL,
    actionLifecycleStatus: currentLifecycleStatus,
  });
  setAgentMonitorEditorStatus(editor, "Saving changes…");

  let currentSavePromise = null;
  currentSavePromise = (async () => {
    featureConfigBusy = true;
    try {
      const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/config`, {
        method: "POST",
        body: {
          prompt: { ...feature.prompt },
          settings: nextSettings,
        },
      });
      applyServerFeatureStates([response.feature || {}], { persist: true });
      state.paymentStatus = response.paymentStatus || state.paymentStatus;
      updateAgentMonitorActionFrequency(action, nextSettings);
      if (action?.payload) {
        const deliveryChannel = normalizeAgentDeliveryChannel(nextSettings.deliveryChannel) || AGENT_ACTION_DELIVERY_CHANNEL;
        const deliveryTarget = getMonitorFeatureDeliveryTarget(nextSettings, deliveryChannel);
        action.payload.actionLifecycleStatus = nextSettings.actionLifecycleStatus;
        action.payload.manualOnly = normalizeMonitorManualOnly(nextSettings.manualOnly);
        action.payload.frequency = formatAgentWebMonitorFrequency(nextSettings);
        action.payload.deliveryChannel = deliveryChannel;
        action.payload.deliveryTarget = deliveryTarget;
        action.payload.deliveryLabel = formatAgentDeliveryTargetDetail(deliveryChannel, deliveryTarget);
        action.channel = deliveryChannel;
        action.recipientRef = deliveryTarget || deliveryChannel;
        action.status = action.payload.manualOnly
          ? "manual_only"
          : (nextSettings.actionLifecycleStatus === "paused" ? "paused" : "running");
      }
      setAgentMonitorEditorStatus(editor, "Saved");
      setStatus("Monitor settings saved.");
      return response;
    } catch (error) {
      setAgentMonitorEditorStatus(editor, formatApiErrorMessage(error, "We couldn’t save the monitor settings."), true);
      setStatus("Couldn’t save the monitor settings.");
      throw error;
    } finally {
      featureConfigBusy = false;
      setAgentLocalActionSettingsBusy(action, false);
      updateAgentLocalActionDom(action);
      if (editor.savePromise === currentSavePromise) {
        editor.savePromise = null;
      }
      if (featureConfigSavePromise === currentSavePromise) {
        featureConfigSavePromise = null;
      }
      if (editor.saveQueued) {
        editor.saveQueued = false;
        scheduleAgentMonitorAutoSave(action, draft, form, { delayMs: 0, status: false });
      }
    }
  })();
  editor.savePromise = currentSavePromise;
  featureConfigSavePromise = currentSavePromise;
  return currentSavePromise;
}

function getAgentLocalActionProposal(action) {
  const proposalId = String(action?.payload?.proposalId || "").trim();
  if (!proposalId) {
    return null;
  }
  return getAgentWorkspace().proposals.find((proposal) => proposal.id === proposalId) || null;
}

// A cadence alone never says when a task actually runs: "Monthly" leaves the
// day and the hour a mystery. Every scheduled action therefore carries a run
// date and a run time, and the moment it next fires is derived from the two.
const AGENT_ACTION_DEFAULT_RUN_TIME = "09:00";

function normalizeAgentActionRunTime(value, fallback = AGENT_ACTION_DEFAULT_RUN_TIME) {
  return normalizeMonitorScheduleTime(value, fallback);
}

function normalizeAgentActionRunDate(value) {
  const text = String(value || "").trim();
  const match = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(text);
  if (!match) {
    return "";
  }
  const year = Number.parseInt(match[1], 10);
  const month = Number.parseInt(match[2], 10);
  const day = Number.parseInt(match[3], 10);
  if (month < 1 || month > 12 || day < 1 || day > 31) {
    return "";
  }
  const parsed = new Date(Date.UTC(year, month - 1, day));
  if (parsed.getUTCFullYear() !== year || parsed.getUTCMonth() + 1 !== month || parsed.getUTCDate() !== day) {
    return "";
  }
  return formatAgentActionRunDate({ year, month, day });
}

function formatAgentActionRunDate(parts) {
  if (!parts || !Number.isFinite(parts.year)) {
    return "";
  }
  return [
    String(parts.year).padStart(4, "0"),
    String(parts.month).padStart(2, "0"),
    String(parts.day).padStart(2, "0"),
  ].join("-");
}

function parseAgentActionRunDateParts(value) {
  const runDate = normalizeAgentActionRunDate(value);
  if (!runDate) {
    return null;
  }
  const [year, month, day] = runDate.split("-").map((part) => Number.parseInt(part, 10));
  return { year, month, day };
}

// Keep the same day of the month where the month has one: a run on the 31st
// lands on the 30th of a shorter month rather than skidding into the next one.
function addAgentActionRunMonths(parts, months) {
  const targetMonthIndex = (parts.month - 1) + months;
  const year = parts.year + Math.floor(targetMonthIndex / 12);
  const month = ((targetMonthIndex % 12) + 12) % 12 + 1;
  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return { year, month, day: Math.min(parts.day, daysInMonth) };
}

function buildAgentActionRunMoment(runDate, runTime, timezone = getWorkspaceTimeZone()) {
  const parts = parseAgentActionRunDateParts(runDate);
  const time = normalizeAgentActionRunTime(runTime, "");
  if (!parts || !time) {
    return null;
  }
  const [hour, minute] = time.split(":").map((part) => Number.parseInt(part, 10));
  const moment = buildMonitorDateInTimeZone({ ...parts, hour, minute, second: 0 }, timezone);
  return moment && !Number.isNaN(moment.getTime()) ? moment : null;
}

function getAgentActionFrequencyIntervalMinutes(frequency) {
  const value = String(frequency || "").trim().toLowerCase();
  const scaled = /^(minutes|days):(\d+)$/.exec(value);
  if (scaled) {
    const amount = Math.max(1, Number.parseInt(scaled[2], 10) || 1);
    return scaled[1] === "minutes" ? amount : amount * 24 * 60;
  }
  if (/month/.test(value)) {
    return 0;
  }
  if (/week/.test(value)) {
    return 7 * 24 * 60;
  }
  if (/hour/.test(value)) {
    return 60;
  }
  if (/minute/.test(value)) {
    return 15;
  }
  return 24 * 60;
}

function isAgentActionMonthlyFrequency(frequency) {
  const value = String(frequency || "").trim().toLowerCase();
  return /month/.test(value) || value === "days:30";
}

function getAgentActionTodayRunDate(timezone = getWorkspaceTimeZone(), now = new Date()) {
  return formatAgentActionRunDate(getMonitorZonedDateTimeParts(now, timezone));
}

// The first slot a task can honestly claim: today when the hour is still
// ahead, tomorrow once it has passed, and the first of next month for a
// monthly batch that reports on the month it just closed.
function getAgentActionDefaultRunDate(frequency, runTime, timezone = getWorkspaceTimeZone(), now = new Date()) {
  const parts = getMonitorZonedDateTimeParts(now, timezone);
  if (!parts) {
    return "";
  }
  if (isAgentActionMonthlyFrequency(frequency)) {
    return formatAgentActionRunDate({ ...addAgentActionRunMonths({ ...parts, day: 1 }, 1) });
  }
  const today = formatAgentActionRunDate(parts);
  const todayMoment = buildAgentActionRunMoment(today, runTime, timezone);
  if (todayMoment && todayMoment.getTime() > now.getTime()) {
    return today;
  }
  return formatAgentActionRunDate(addMonitorUtcDays(parts, 1));
}

// The chosen date and hour are the first run; once they are behind us the next
// slot follows the cadence from there.
function resolveAgentActionNextRunAt(schedule = {}, now = new Date()) {
  const timezone = normalizeMonitorScheduleTimezone(schedule.timezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
  const firstMoment = buildAgentActionRunMoment(schedule.runDate, schedule.runTime, timezone);
  if (!firstMoment) {
    return "";
  }
  const currentTime = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date();
  if (firstMoment.getTime() > currentTime.getTime()) {
    return firstMoment.toISOString();
  }

  const intervalMinutes = getAgentActionFrequencyIntervalMinutes(schedule.frequency);
  if (intervalMinutes) {
    const intervalMs = intervalMinutes * 60 * 1000;
    const cycles = Math.floor((currentTime.getTime() - firstMoment.getTime()) / intervalMs) + 1;
    return new Date(firstMoment.getTime() + cycles * intervalMs).toISOString();
  }

  let parts = parseAgentActionRunDateParts(schedule.runDate);
  for (let step = 1; parts && step <= 120; step += 1) {
    const candidate = buildAgentActionRunMoment(
      formatAgentActionRunDate(addAgentActionRunMonths(parts, step)),
      schedule.runTime,
      timezone,
    );
    if (candidate && candidate.getTime() > currentTime.getTime()) {
      return candidate.toISOString();
    }
  }
  return "";
}

function getAgentLocalActionFrequencyValue(action, proposal) {
  if (getAgentProposalManualOnly(proposal)) {
    return "manual";
  }
  // A recurring receipts/invoices job collects the previous month, so an
  // unknown cadence means monthly here rather than the generic daily default.
  const fallbackFrequency = agentContextSuggestsMonthlyBatchTask(proposal) ? "monthly" : "daily";
  const raw = String(
    action?.payload?.frequency
    || getAgentProposalFieldValue(proposal, "frequency")
    || getAgentProposalFieldValue(proposal, "schedule")
    || proposal?.executionPlan?.frequency
    || fallbackFrequency,
  ).trim().toLowerCase();
  if (/hour/.test(raw)) return "hourly";
  if (/week/.test(raw)) return "weekly";
  if (/month/.test(raw)) return "monthly";
  if (/15\s*minutes?/.test(raw)) return "minutes:15";
  if (/5\s*minutes?/.test(raw)) return "minutes:5";
  if (/minute/.test(raw)) return "minutes:15";
  return fallbackFrequency;
}

function getAgentLocalActionFrequencyOptions() {
  return [
    { value: "manual", label: "Run manually" },
    { value: "minutes:5", label: "Every 5 minutes" },
    { value: "minutes:15", label: "Every 15 minutes" },
    { value: "hourly", label: "Hourly" },
    { value: "daily", label: "Daily" },
    { value: "weekly", label: "Weekly" },
    { value: "monthly", label: "Monthly" },
  ];
}

// The date and hour a saved action next runs, defaulted when the action was
// approved before it was asked for one.
function getAgentProposalRunSchedule(proposal, manualOnly = getAgentProposalManualOnly(proposal)) {
  const timezone = getWorkspaceTimeZone();
  if (manualOnly) {
    return { frequency: "manual", runDate: "", runTime: "", timezone, nextRunAt: "" };
  }
  const frequency = getAgentLocalActionFrequencyValue(null, proposal);
  const runTime = normalizeAgentActionRunTime(
    getAgentProposalFieldValue(proposal, "runTime") || proposal?.executionPlan?.runTime,
  );
  const runDate = normalizeAgentActionRunDate(
    getAgentProposalFieldValue(proposal, "runDate") || proposal?.executionPlan?.runDate,
  ) || getAgentActionDefaultRunDate(frequency, runTime, timezone);
  return {
    frequency,
    runDate,
    runTime,
    timezone,
    nextRunAt: resolveAgentActionNextRunAt({ frequency, runDate, runTime, timezone }),
  };
}

const AGENT_CALENDAR_SUMMARY_DATE_RANGE_OPTIONS = [
  { value: "today", label: "today" },
  { value: "tomorrow", label: "tomorrow" },
  { value: "this week", label: "this week" },
  { value: "next week", label: "next week" },
  { value: "this month", label: "this month" },
  { value: "next month", label: "next month" },
];

function normalizeAgentCalendarSummaryDateRangeValue(value) {
  const text = String(value || "").trim().replace(/\s+/g, " ");
  if (!text) {
    return "";
  }
  const option = AGENT_CALENDAR_SUMMARY_DATE_RANGE_OPTIONS.find((candidate) => (
    candidate.value.toLowerCase() === text.toLowerCase()
    || candidate.label.toLowerCase() === text.toLowerCase()
  ));
  return option?.value || text;
}

function getAgentCalendarSummaryDateRangeOptions(currentValue = "") {
  const options = AGENT_CALENDAR_SUMMARY_DATE_RANGE_OPTIONS.map((option) => ({
    ...option,
    preview: formatAgentTimeWindowPreview(option.value),
  }));
  const normalizedCurrentValue = normalizeAgentCalendarSummaryDateRangeValue(currentValue);
  if (normalizedCurrentValue && !options.some((option) => option.value === normalizedCurrentValue)) {
    options.push({
      value: normalizedCurrentValue,
      label: normalizedCurrentValue,
      preview: formatAgentTimeWindowPreview(normalizedCurrentValue),
    });
  }
  return options;
}

function getAgentWorkspaceDateParts(timeZone = getWorkspaceTimeZone()) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined,
    year: "numeric",
    month: "numeric",
    day: "numeric",
  }).formatToParts(new Date());
  const year = Number.parseInt(parts.find((part) => part.type === "year")?.value || "", 10);
  const month = Number.parseInt(parts.find((part) => part.type === "month")?.value || "", 10);
  const day = Number.parseInt(parts.find((part) => part.type === "day")?.value || "", 10);
  return Number.isInteger(year) && Number.isInteger(month) && Number.isInteger(day)
    ? new Date(Date.UTC(year, month - 1, day))
    : new Date();
}

function addAgentCalendarDays(date, amount) {
  const next = new Date(date.getTime());
  next.setUTCDate(next.getUTCDate() + Number(amount || 0));
  return next;
}

function getAgentDateRangeFromTimeWindow(value, timeZone = getWorkspaceTimeZone()) {
  const text = String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!text) {
    return null;
  }

  const today = getAgentWorkspaceDateParts(timeZone);
  const daysSinceMonday = (today.getUTCDay() + 6) % 7;
  let start = null;
  let end = null;
  if (text === "today") {
    start = today;
    end = today;
  } else if (text === "tomorrow") {
    start = addAgentCalendarDays(today, 1);
    end = start;
  } else if (text === "this week" || text === "next week" || text === "last week") {
    const weekOffset = text === "next week" ? 7 : text === "last week" ? -7 : 0;
    start = addAgentCalendarDays(today, -daysSinceMonday + weekOffset);
    end = addAgentCalendarDays(start, 6);
  } else if (text === "next month") {
    start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth() + 1, 1));
    end = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 0));
  } else if (text === "this month") {
    start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
    end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth() + 1, 0));
  }

  return start && end ? { start, end } : null;
}

function getAgentOrdinalDay(day) {
  const numericDay = Number(day);
  const suffix = numericDay % 100 >= 11 && numericDay % 100 <= 13
    ? "th"
    : ({ 1: "st", 2: "nd", 3: "rd" }[numericDay % 10] || "th");
  return `${numericDay}${suffix}`;
}

function formatAgentTimeWindowPreview(value, timeZone = getWorkspaceTimeZone()) {
  const range = getAgentDateRangeFromTimeWindow(value, timeZone);
  if (!range) {
    return "";
  }

  const startMonth = range.start.toLocaleString("en-US", { month: "short", timeZone: "UTC" });
  const endMonth = range.end.toLocaleString("en-US", { month: "short", timeZone: "UTC" });
  const sameYear = range.start.getUTCFullYear() === range.end.getUTCFullYear();
  const sameMonth = sameYear && range.start.getUTCMonth() === range.end.getUTCMonth();
  const sameDay = sameMonth && range.start.getUTCDate() === range.end.getUTCDate();
  const monthEndDay = new Date(Date.UTC(
    range.start.getUTCFullYear(),
    range.start.getUTCMonth() + 1,
    0,
  )).getUTCDate();
  const fullCalendarMonth = sameMonth
    && range.start.getUTCDate() === 1
    && range.end.getUTCDate() === monthEndDay;
  const startLabel = getAgentOrdinalDay(range.start.getUTCDate());
  const endLabel = getAgentOrdinalDay(range.end.getUTCDate());
  if (sameDay) {
    return `${startLabel} ${startMonth}`;
  }
  if (fullCalendarMonth) {
    return `${startMonth} ${range.start.getUTCFullYear()}`;
  }
  return sameMonth
    ? `${startLabel} to ${endLabel}`
    : `${startLabel} ${startMonth} to ${endLabel} ${endMonth}`;
}

function formatAgentLocalActionFrequency(value) {
  const option = getAgentLocalActionFrequencyOptions().find((candidate) => candidate.value === value);
  return option?.label || "Daily";
}

function wrapAgentActionEditorSelect(select) {
  const wrapper = document.createElement("span");
  wrapper.className = "agent-action-editor-select-wrap";
  wrapper.append(select);
  return wrapper;
}

function resizeAgentActionEditorTextarea(input) {
  if (!input || input.tagName !== "TEXTAREA") {
    return;
  }
  input.style.height = "auto";
  const borderBlock = Math.max(0, input.offsetHeight - input.clientHeight);
  input.style.height = `${input.scrollHeight + borderBlock}px`;
}

function scheduleAgentActionEditorTextareaResize(input) {
  resizeAgentActionEditorTextarea(input);
  window.requestAnimationFrame(() => resizeAgentActionEditorTextarea(input));
}

function createAgentActionEditorStatusElement(className = "agent-action-editor-status", tagName = "p") {
  const status = document.createElement(tagName);
  status.className = className;
  status.hidden = true;
  const spinner = document.createElement("span");
  spinner.className = "agent-action-editor-status-spinner";
  spinner.setAttribute("aria-hidden", "true");
  const text = document.createElement("span");
  text.className = "agent-action-editor-status-text";
  status._agentActionEditorStatusText = text;
  status.append(spinner, text);
  return status;
}

function setAgentActionEditorStatusElement(status, message, isError = false, isSaving = false) {
  if (!status) {
    return;
  }
  const text = status._agentActionEditorStatusText || status.querySelector?.(".agent-action-editor-status-text");
  status.hidden = !message;
  status.classList.toggle("is-error", isError);
  status.classList.toggle("is-saving", Boolean(isSaving && !isError));
  if (text) {
    text.textContent = message;
  } else {
    status.textContent = message;
  }
}

function createAgentActionEditorLabelRow(labelText) {
  const labelRow = document.createElement("span");
  labelRow.className = "agent-action-editor-label-row";
  const label = document.createElement("span");
  label.className = "agent-action-editor-label";
  label.textContent = labelText;
  const fieldStatus = createAgentActionEditorStatusElement("agent-action-editor-field-status", "span");
  fieldStatus.setAttribute("aria-hidden", "true");
  labelRow.append(label, fieldStatus);
  return { labelRow, label, fieldStatus };
}

function setAgentActionEditorFieldStatus(field, message = "", isError = false, isSaving = false) {
  if (!field) {
    return;
  }
  if (field._agentActionEditorStatusTimer) {
    window.clearTimeout(field._agentActionEditorStatusTimer);
    field._agentActionEditorStatusTimer = null;
  }
  field.classList.toggle("is-saving", Boolean(isSaving && !isError));
  setAgentActionEditorStatusElement(field._agentActionEditorFieldStatus, message, isError, isSaving);
}

function clearAgentActionEditorFieldStatusSoon(field) {
  if (!field) {
    return;
  }
  if (field._agentActionEditorStatusTimer) {
    window.clearTimeout(field._agentActionEditorStatusTimer);
  }
  field._agentActionEditorStatusTimer = window.setTimeout(() => {
    field._agentActionEditorStatusTimer = null;
    const status = field._agentActionEditorFieldStatus;
    if (status && !status.classList.contains("is-saving") && !status.classList.contains("is-error")) {
      setAgentActionEditorFieldStatus(field);
    }
  }, 1400);
}

function createAgentLocalActionEditorField(labelText, value, options = {}) {
  const field = document.createElement("label");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  const input = options.select
    ? document.createElement("select")
    : options.multiline
      ? document.createElement("textarea")
      : document.createElement("input");
  input.className = options.select
    ? "agent-action-editor-select"
    : `agent-action-editor-input${options.multiline ? " agent-action-editor-textarea" : ""}`;
  input.value = String(value || "");
  input.setAttribute("aria-label", labelText);
  if (!options.select && !options.multiline) {
    input.type = options.inputType || "text";
    if (input.type === "text") {
      input.placeholder = options.placeholder || "Enter a value";
    }
    if (options.min) {
      input.min = options.min;
    }
  }
  if (options.multiline) {
    input.rows = Number(options.rows || 1);
    input.placeholder = options.placeholder || "Enter a value";
    input.addEventListener("input", () => resizeAgentActionEditorTextarea(input));
  }
  if (options.select) {
    for (const option of options.options || []) {
      const optionElement = document.createElement("option");
      optionElement.value = option.value;
      optionElement.textContent = option.label;
      input.append(optionElement);
    }
    input.value = String(value || options.options?.[0]?.value || "");
  }
  field.append(labelRow, options.select ? wrapAgentActionEditorSelect(input) : input);
  return { field, input };
}

// One tag per calendar inside the connected account, not one tag per account.
// A Google connection holds the owner's own calendar plus every calendar shared
// with it - Family, a partner's, a team's - and an action reads the ones ticked
// here. The calendars come from the connection itself; the address box below
// stays for a calendar that was shared but never added to the account's list.
function createAgentCalendarTagsField(labelText, value) {
  const field = document.createElement("div");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  label.id = createAgentId("agent-calendar-tags-label");
  const input = document.createElement("input");
  input.type = "hidden";
  input.value = formatAgentCalendarFieldValue(value);

  const sourceList = document.createElement("div");
  sourceList.className = "agent-calendar-sources";
  sourceList.setAttribute("aria-labelledby", label.id);

  const entry = document.createElement("div");
  entry.className = "agent-action-editor-topic-entry";
  const entryInput = document.createElement("input");
  entryInput.type = "text";
  entryInput.className = "agent-action-editor-input";
  entryInput.placeholder = "Add a calendar email address";
  entryInput.setAttribute("aria-label", "Add a calendar email address");
  entryInput.autocomplete = "off";
  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.className = "ghost-button small agent-action-editor-add";
  addButton.textContent = "Add";
  entry.append(entryInput, addButton);

  const hint = document.createElement("p");
  hint.className = "agent-action-editor-hint";

  function getTags() {
    return getAgentCalendarSelectionIds(input.value);
  }

  function getSources() {
    return Array.isArray(state.agentCalendarSources) ? state.agentCalendarSources : [];
  }

  function setHint(message, isError = false) {
    hint.textContent = message;
    hint.classList.toggle("is-error", Boolean(isError));
    hint.hidden = !message;
  }

  function resetHint() {
    if (!getConnectedCalendarTagLabel()) {
      setHint("Connect Google Calendar so this action has a calendar to read.");
      return;
    }
    if (state.agentCalendarSourcesError) {
      setHint(state.agentCalendarSourcesError, true);
      return;
    }
    setHint("");
  }

  // What to call a saved ID the account no longer lists, so a calendar that was
  // removed or typed by hand still shows as something this action reads.
  function getFallbackTagLabel(tag) {
    if (tag !== AGENT_CALENDAR_PRIMARY_ID) {
      return tag;
    }
    return getConnectedCalendarTagLabel() || "The connected calendar";
  }

  function commitTags(tags) {
    const nextValue = tags.join(", ");
    if (nextValue === input.value) {
      renderSources();
      return;
    }
    input.value = nextValue;
    renderSources();
    input.dispatchEvent(new Event("change", { bubbles: true }));
  }

  function toggleTag(tag) {
    const tags = getTags();
    if (tags.includes(tag)) {
      // Reading nothing is not a setting anyone means to choose, so the last
      // calendar stays ticked until another one is.
      if (tags.length <= 1) {
        setHint("This action needs at least one calendar to read.", true);
        return;
      }
      resetHint();
      commitTags(tags.filter((existing) => existing !== tag));
      return;
    }
    if (tags.length >= AGENT_CALENDAR_TAG_LIMIT) {
      setHint(`This action reads up to ${AGENT_CALENDAR_TAG_LIMIT} calendars.`, true);
      return;
    }
    resetHint();
    commitTags([...tags, tag]);
  }

  function addTag() {
    const address = entryInput.value.trim().toLowerCase();
    if (!address) {
      entryInput.focus();
      return;
    }
    if (!isAgentCalendarAddressTag(address)) {
      setHint("Add a calendar as an email address, like alex@example.com.", true);
      entryInput.focus();
      return;
    }
    const tags = getTags();
    if (tags.some((tag) => tag.toLowerCase().includes(address.toLowerCase()))) {
      setHint("That calendar is already on the list.", true);
      entryInput.focus();
      return;
    }
    if (tags.length >= AGENT_CALENDAR_TAG_LIMIT) {
      setHint(`This action reads up to ${AGENT_CALENDAR_TAG_LIMIT} calendars.`, true);
      return;
    }
    entryInput.value = "";
    resetHint();
    commitTags([...tags, address]);
    entryInput.focus();
  }

  function createCalendarChip(calendar, tags) {
    const selected = tags.includes(calendar.id);
    const atLimit = !selected && tags.length >= AGENT_CALENDAR_TAG_LIMIT;
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = `agent-action-editor-chip is-selectable${selected ? " is-selected" : ""}`;
    chip.dataset.agentCalendarToggle = calendar.id;
    chip.setAttribute("aria-pressed", selected ? "true" : "false");
    chip.disabled = atLimit;
    const mark = document.createElement("span");
    mark.className = "agent-action-editor-chip-mark";
    mark.setAttribute("aria-hidden", "true");
    mark.textContent = selected ? "✓" : "+";
    const chipLabel = document.createElement("span");
    chipLabel.className = "agent-action-editor-chip-label";
    chipLabel.textContent = calendar.label;
    chip.append(mark, chipLabel);
    return chip;
  }

  function createRemovableChip(tag) {
    const chip = document.createElement("span");
    chip.className = "agent-action-editor-chip";
    chip.setAttribute("role", "listitem");
    const chipLabel = document.createElement("span");
    chipLabel.className = "agent-action-editor-chip-label";
    chipLabel.textContent = getFallbackTagLabel(tag);
    chip.append(chipLabel);
    if (getTags().length <= 1) {
      // The one calendar left is not removable, the same way it is not
      // untickable above.
      chip.classList.add("is-fixed");
      chip.title = tag === AGENT_CALENDAR_PRIMARY_ID
        ? "The calendar of the connected Google account."
        : "The only calendar this action reads.";
      return chip;
    }
    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "agent-action-editor-chip-remove";
    removeButton.dataset.agentCalendarTagRemove = tag;
    removeButton.setAttribute("aria-label", `Remove ${getFallbackTagLabel(tag)}`);
    removeButton.textContent = "×";
    chip.append(removeButton);
    return chip;
  }

  function createSourceGroup(heading, note) {
    const group = document.createElement("div");
    group.className = "agent-calendar-source";
    group.setAttribute("role", "group");
    const name = document.createElement("p");
    name.className = "agent-calendar-source-name";
    name.textContent = heading;
    name.id = createAgentId("agent-calendar-source");
    group.setAttribute("aria-labelledby", name.id);
    const chips = document.createElement("div");
    chips.className = "agent-action-editor-topics";
    group.append(name, chips);
    if (note) {
      const noteLine = document.createElement("p");
      noteLine.className = "agent-calendar-source-note";
      noteLine.textContent = note;
      group.append(noteLine);
    }
    return { group, chips };
  }

  function renderSources() {
    const tags = getTags();
    const sources = getSources();
    const listed = new Set();
    sourceList.replaceChildren();

    if (!getConnectedCalendarTagLabel()) {
      const empty = document.createElement("span");
      empty.className = "agent-action-editor-empty";
      empty.textContent = "No calendar connected yet.";
      sourceList.append(empty);
      entryInput.disabled = true;
      addButton.disabled = true;
      return;
    }

    if (!sources.length && state.agentCalendarSourcesLoading) {
      const loading = document.createElement("span");
      loading.className = "agent-action-editor-empty";
      loading.textContent = "Loading the calendars in this account…";
      sourceList.append(loading);
    }

    for (const source of sources) {
      const { group, chips } = createSourceGroup(getAgentCalendarSourceHeading(source), source.message);
      for (const calendar of source.calendars) {
        listed.add(calendar.id);
        chips.append(createCalendarChip(calendar, tags));
      }
      if (!source.calendars.length) {
        // Without a list to tick, the account's own calendar and any address
        // added by hand are still shown, so the action never looks empty.
        chips.setAttribute("role", "list");
        for (const tag of tags) {
          listed.add(tag);
          chips.append(createRemovableChip(tag));
        }
      }
      sourceList.append(group);
    }

    const unlisted = tags.filter((tag) => !listed.has(tag));
    if (unlisted.length && !(state.agentCalendarSourcesLoading && !sources.length)) {
      // A calendar the account no longer lists is still read, so it is named
      // here rather than quietly dropped from the action. With no account to
      // sit under - the calendars could not be loaded at all - these are all
      // the action reads, so they take the connection's own name.
      const heading = sources.length ? "Also reading" : getConnectedCalendarTagLabel();
      const { group, chips } = createSourceGroup(heading, "");
      chips.setAttribute("role", "list");
      for (const tag of unlisted) {
        chips.append(createRemovableChip(tag));
      }
      sourceList.append(group);
    }

    entryInput.disabled = tags.length >= AGENT_CALENDAR_TAG_LIMIT;
    addButton.disabled = entryInput.disabled;
  }

  addButton.addEventListener("click", addTag);
  entryInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      addTag();
    }
  });
  entryInput.addEventListener("input", () => {
    if (hint.classList.contains("is-error")) {
      resetHint();
    }
  });
  sourceList.addEventListener("click", (event) => {
    const target = getEventTargetElement(event);
    const removeButton = target?.closest("[data-agent-calendar-tag-remove]");
    if (removeButton) {
      const remaining = getTags().filter((tag) => tag !== String(removeButton.dataset.agentCalendarTagRemove || ""));
      if (!remaining.length) {
        setHint("This action needs at least one calendar to read.", true);
        return;
      }
      resetHint();
      commitTags(remaining);
      return;
    }
    const toggle = target?.closest("[data-agent-calendar-toggle]");
    if (toggle) {
      toggleTag(String(toggle.dataset.agentCalendarToggle || ""));
    }
  });

  function render() {
    resetHint();
    renderSources();
  }

  const renderer = { field, render, attached: false };
  agentCalendarFieldRenderers.add(renderer);
  render();
  void refreshAgentCalendarSources();
  field.append(labelRow, sourceList, entry, hint, input);
  return { field, input };
}

function createAgentCalendarSummaryDateRangeField(labelText, value) {
  const options = getAgentCalendarSummaryDateRangeOptions(value);
  const field = document.createElement("div");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  label.id = createAgentId("agent-date-range-label");
  const input = document.createElement("input");
  input.type = "hidden";
  input.value = normalizeAgentCalendarSummaryDateRangeValue(value) || options[0]?.value || "";
  const dropdown = document.createElement("span");
  dropdown.className = "agent-date-range-dropdown";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-date-range-dropdown-button";
  button.setAttribute("aria-haspopup", "listbox");
  button.setAttribute("aria-expanded", "false");
  const selectedLabel = document.createElement("span");
  selectedLabel.className = "agent-date-range-dropdown-button-label";
  const selectedPreview = document.createElement("span");
  selectedPreview.className = "agent-date-range-dropdown-button-meta";
  selectedPreview.setAttribute("aria-live", "polite");
  const chevron = document.createElement("span");
  chevron.className = "agent-date-range-dropdown-chevron";
  chevron.setAttribute("aria-hidden", "true");
  button.append(selectedLabel, selectedPreview, chevron);
  const menu = document.createElement("div");
  menu.id = createAgentId("agent-date-range-menu");
  menu.className = "agent-date-range-dropdown-menu";
  menu.setAttribute("role", "listbox");
  menu.setAttribute("aria-labelledby", label.id);
  menu.hidden = true;
  button.setAttribute("aria-controls", menu.id);

  const optionButtons = options.map((option) => {
    const optionButton = document.createElement("button");
    optionButton.type = "button";
    optionButton.className = "agent-date-range-dropdown-option";
    optionButton.setAttribute("role", "option");
    optionButton.dataset.value = option.value;
    const optionLabel = document.createElement("span");
    optionLabel.className = "agent-date-range-dropdown-option-label";
    optionLabel.textContent = option.label;
    const optionPreview = document.createElement("span");
    optionPreview.className = "agent-date-range-dropdown-option-meta";
    optionPreview.textContent = option.preview || "";
    optionPreview.hidden = !optionPreview.textContent;
    optionButton.append(optionLabel, optionPreview);
    optionButton.addEventListener("click", () => {
      if (input.value !== option.value) {
        input.value = option.value;
        updateSelectedDateRangeOption();
        input.dispatchEvent(new Event("change", { bubbles: true }));
      } else {
        updateSelectedDateRangeOption();
      }
      setDateRangeDropdownOpen(false);
      button.focus();
    });
    menu.append(optionButton);
    return optionButton;
  });

  const getSelectedOption = () => (
    options.find((option) => option.value === input.value)
    || { value: input.value, label: input.value || options[0]?.label || "", preview: formatAgentTimeWindowPreview(input.value) }
  );

  function updateSelectedDateRangeOption() {
    const selectedOption = getSelectedOption();
    selectedLabel.textContent = selectedOption.label;
    selectedPreview.textContent = selectedOption.preview || "";
    selectedPreview.hidden = !selectedPreview.textContent;
    button.setAttribute(
      "aria-label",
      selectedOption.preview
        ? `${labelText}: ${selectedOption.label}, ${selectedOption.preview}`
        : `${labelText}: ${selectedOption.label}`,
    );
    for (const optionButton of optionButtons) {
      const isSelected = optionButton.dataset.value === input.value;
      optionButton.classList.toggle("is-selected", isSelected);
      optionButton.setAttribute("aria-selected", String(isSelected));
    }
  }

  function setDateRangeDropdownOpen(isOpen) {
    menu.hidden = !isOpen;
    dropdown.classList.toggle("is-open", isOpen);
    button.setAttribute("aria-expanded", String(isOpen));
    document[isOpen ? "addEventListener" : "removeEventListener"]("click", closeDateRangeDropdownOnOutsideClick);
  }

  function closeDateRangeDropdownOnOutsideClick(event) {
    if (!field.contains(event.target)) {
      setDateRangeDropdownOpen(false);
    }
  }

  function focusDateRangeOption(offset = 0) {
    const selectedIndex = Math.max(0, optionButtons.findIndex((optionButton) => optionButton.dataset.value === input.value));
    const nextIndex = Math.max(0, Math.min(optionButtons.length - 1, selectedIndex + offset));
    optionButtons[nextIndex]?.focus();
  }

  button.addEventListener("click", () => setDateRangeDropdownOpen(menu.hidden));
  button.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" || event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      setDateRangeDropdownOpen(true);
      focusDateRangeOption();
    }
  });
  menu.addEventListener("keydown", (event) => {
    const currentIndex = optionButtons.indexOf(document.activeElement);
    if (event.key === "Escape") {
      event.preventDefault();
      setDateRangeDropdownOpen(false);
      button.focus();
    } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const direction = event.key === "ArrowDown" ? 1 : -1;
      const nextIndex = Math.max(0, Math.min(optionButtons.length - 1, currentIndex + direction));
      optionButtons[nextIndex]?.focus();
    } else if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      optionButtons[event.key === "Home" ? 0 : optionButtons.length - 1]?.focus();
    }
  });

  updateSelectedDateRangeOption();
  dropdown.append(button, menu);
  field.append(labelRow, dropdown, input);
  return { field, input };
}

function updateAgentLocalActionDom(action) {
  const item = Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]") )
    .find((candidate) => candidate.dataset.agentScheduledActionId === String(action?.id || ""));
  if (!item) {
    return;
  }
  const statusClass = getScheduledActionStatusClass(action.status, action);
  item.className = `agent-action-item is-${statusClass}${state.selectedScheduledActionId === String(action.id) ? " is-expanded" : ""}${agentActionSpotlightId && String(action.id || "") === agentActionSpotlightId ? " is-spotlighted" : ""}`;
  item.dataset.agentActionItemSignature = getScheduledActionItemSignature(action);
  const status = item.querySelector(".agent-action-status");
  const lifecycleBusy = isAgentActionLifecycleBusy(action);
  const runBusy = isAgentLocalActionRunBusy(action);
  if (status) {
    status.className = `agent-action-status is-${runBusy ? "run-busy" : lifecycleBusy ? "lifecycle-busy" : statusClass}`;
    status.textContent = runBusy
      ? "Running"
      : lifecycleBusy
        ? (isAgentLifecycleActionPaused(action) ? "Starting" : "Stopping")
        : getScheduledActionStatusLabel(action.status, action);
  }
  const time = item.querySelector(".agent-action-item-time");
  if (time) {
    const hideTime = Boolean(action.payload?.manualOnly) || statusClass === "paused";
    time.textContent = hideTime
      ? ""
      : formatScheduledActionDate(getScheduledActionItemTimeValue(action), action.timezone);
    time.hidden = hideTime;
  }
  for (const term of item.querySelectorAll("dt")) {
    const label = String(term.textContent || "").trim();
    const value = term.nextElementSibling;
    if (!value) continue;
    if (label === "Delivery") {
      value.textContent = action.payload?.deliveryLabel
        || formatAgentDeliveryTargetDetail(action.payload?.deliveryChannel || action.channel, action.payload?.deliveryTarget || action.recipientRef)
        || "As configured";
    }
    if (label === "Frequency") {
      value.textContent = action.payload?.frequency || "As configured";
    }
    if (label === "Date range") {
      value.textContent = action.payload?.timeWindow || "Not available";
    }
  }
  const currentActions = item.querySelector(".agent-action-detail-actions");
  const nextActions = createAgentActionDetailActions(action);
  if (currentActions && nextActions) {
    currentActions.replaceWith(nextActions);
  } else if (!currentActions && nextActions) {
    item.querySelector(".agent-action-detail-card")?.append(nextActions);
  } else if (currentActions) {
    currentActions.remove();
  }
}

function setAgentLocalActionEditorStatus(editor, message, isError = false, isSaving = false, changedField = null) {
  if (!editor?.status) return;
  if (isSaving) {
    if (editor.activeField && editor.activeField !== changedField) {
      setAgentActionEditorFieldStatus(editor.activeField);
    }
    editor.activeField = changedField || editor.activeField || null;
    setAgentActionEditorFieldStatus(editor.activeField, "Saving", false, true);
  } else if (editor.activeField) {
    const completedField = editor.activeField;
    const fieldMessage = isError ? "Error" : message === "Saved" ? "Saved" : "";
    setAgentActionEditorFieldStatus(completedField, fieldMessage, isError, false);
    editor.activeField = null;
    if (fieldMessage && !isError) {
      clearAgentActionEditorFieldStatusSoon(completedField);
    }
  }
  setAgentActionEditorStatusElement(editor.status, message, isError, isSaving);
}

function shouldShowAgentManualRunMonthField(proposal, draft = {}) {
  return agentContextSuggestsMonthlyBatchTask(proposal, draft.result || "");
}

function shouldAllowAgentManualRunMonthChoice(proposal, draft = {}) {
  return shouldShowAgentManualRunMonthField(proposal, draft)
    && String(draft.frequency || "").trim().toLowerCase() === "manual";
}

function isAgentProposalReceiptCollector(proposal, draft = {}) {
  if (!isAgentProposalCustomGoogleBatchRunner(proposal)) {
    return false;
  }
  return /\breceipts?\b/i.test(getAgentQuestionContextText(proposal, draft.result || getAgentProposalFieldValue(proposal, "result")));
}

function formatAgentReceiptFolderMonth(value) {
  const normalizedValue = parseAgentManualRunMonthValue(value);
  const match = normalizedValue.match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return "";
  }
  const year = Number.parseInt(match[1], 10);
  const monthIndex = Number.parseInt(match[2], 10) - 1;
  const date = new Date(Date.UTC(year, monthIndex, 1));
  const monthLabel = new Intl.DateTimeFormat("en-US", {
    month: "short",
    timeZone: "UTC",
  }).format(date).replace(/\./g, "");
  return `${monthLabel}${year}`;
}

function normalizeAgentReceiptOutputFolder(value = "") {
  const raw = String(value || "").trim().replace(/\\/g, "/");
  if (!raw) {
    return "";
  }
  const segments = raw
    .split("/")
    .map((segment) => segment.trim().replace(/[^a-zA-Z0-9 ._{}-]+/g, "-").replace(/^[ ._-]+|[ ._-]+$/g, ""))
    .filter(Boolean)
    .slice(0, 8);
  return segments.length ? `${segments.join("/")}/` : "";
}

function isAgentGeneratedReceiptOutputFolder(value = "") {
  return /^Receipts\/(?:\{RunMonth\}|[A-Z][a-z]{2}\d{4}|Unsorted)\/?$/i.test(String(value || "").trim());
}

function getAgentMonthlyBatchOutputFolder(proposal, draft = {}) {
  if (!isAgentProposalReceiptCollector(proposal, draft)) {
    return "";
  }
  const fields = getAgentProposalFieldMap(proposal);
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const settings = getAgentProposalExecutionSettings(proposal);
  const rawValue = Object.prototype.hasOwnProperty.call(draft, "outputFolder")
    ? draft.outputFolder
    : (fields.outputFolder || details.outputFolder || settings.outputFolder || "");
  const isManual = String(draft.frequency || "").trim().toLowerCase() === "manual"
    || (!String(draft.frequency || "").trim() && getAgentProposalManualOnly(proposal));
  const runMonthLabel = isManual
    ? formatAgentReceiptFolderMonth(getAgentProposalManualRunMonthValue(proposal, draft))
    : "{RunMonth}";
  const generatedFolder = isManual
    ? `Receipts/${runMonthLabel || "Unsorted"}/`
    : AGENT_RECEIPT_RECURRING_OUTPUT_FOLDER;
  const rawText = String(rawValue || "").trim();
  if (!rawText || isAgentGeneratedReceiptOutputFolder(rawText)) {
    return generatedFolder;
  }
  const normalizedFolder = normalizeAgentReceiptOutputFolder(
    isManual ? rawText.replace(/\{RunMonth\}/gi, runMonthLabel || "Unsorted") : rawText,
  );
  return normalizedFolder || generatedFolder;
}

function getAgentCustomGoogleBatchRunLabel(proposal) {
  const fields = getAgentProposalFieldMap(proposal);
  const frequencyText = String(fields.frequency || proposal?.executionPlan?.frequency || "").trim().toLowerCase();
  if (!getAgentProposalManualOnly(proposal) && /\bmonth(?:ly)?\b/.test(frequencyText)) {
    return "the previous month";
  }
  return formatAgentManualRunMonthLabel(getAgentProposalManualRunMonthValue(proposal));
}

function applyAgentLocalActionDraftState(action, draft, options = {}) {
  const proposal = getAgentLocalActionProposal(action);
  if (!proposal) {
    return null;
  }
  const fields = { ...getAgentProposalFieldMap(proposal) };
  const frequencyLabel = formatAgentLocalActionFrequency(draft.frequency);
  const manualOnly = draft.frequency === "manual";
  const previousLifecycleStatus = getAgentProposalLifecycleStatus(proposal);
  const lifecycleStatus = manualOnly ? "active" : previousLifecycleStatus;
  if (manualOnly) {
    fields.frequency = "manual only";
    fields.schedule = "manual only";
  } else {
    fields.frequency = frequencyLabel;
    if (proposal.type === "email-digest") fields.schedule = frequencyLabel;
  }
  if (draft.deliveryChannel) fields.deliveryChannel = formatAgentScheduledMessageChannel(draft.deliveryChannel);
  for (const key of ["calendar", "timeWindow", "mailbox", "mailboxAccount", "inactivityPeriod", "result", "outputFolder"]) {
    if (Object.prototype.hasOwnProperty.call(draft, key)) {
      const value = String(draft[key] || "").trim();
      if (value) fields[key] = value;
    }
  }
  const runTimezone = getWorkspaceTimeZone();
  const runTime = manualOnly ? "" : normalizeAgentActionRunTime(draft.runTime);
  const runSchedule = {
    frequency: draft.frequency,
    runDate: manualOnly
      ? ""
      : (normalizeAgentActionRunDate(draft.runDate) || getAgentActionDefaultRunDate(draft.frequency, runTime, runTimezone)),
    runTime,
    timezone: runTimezone,
  };
  runSchedule.nextRunAt = manualOnly ? "" : resolveAgentActionNextRunAt(runSchedule);
  if (runSchedule.runDate) {
    fields.runDate = runSchedule.runDate;
    fields.runTime = runSchedule.runTime;
  } else {
    delete fields.runDate;
    delete fields.runTime;
  }
  const canChooseRunMonth = shouldAllowAgentManualRunMonthChoice(proposal, draft);
  if (canChooseRunMonth) {
    fields.manualRunMonth = getAgentProposalManualRunMonthValue(proposal, draft);
  } else if (fields.manualRunMonth) {
    delete fields.manualRunMonth;
  }

  proposal.fields = normalizeAgentFieldValues(fields);
  normalizeAgentMonthlyBatchProposalFields(proposal, {
    ...draft,
    manualRunMonth: canChooseRunMonth ? fields.manualRunMonth : "",
    result: fields.result,
  });
  const savedManualRunMonth = canChooseRunMonth
    ? (proposal.fields.manualRunMonth || fields.manualRunMonth || "")
    : "";
  const savedOutputFolder = getAgentMonthlyBatchOutputFolder(proposal, {
    ...draft,
    manualRunMonth: savedManualRunMonth,
  });
  if (savedOutputFolder) {
    proposal.fields.outputFolder = savedOutputFolder;
  }
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    frequency: frequencyLabel,
    actionLifecycleStatus: lifecycleStatus,
    manualRunMonth: savedManualRunMonth,
    outputFolder: savedOutputFolder,
    runDate: runSchedule.runDate,
    runTime: runSchedule.runTime,
    timezone: runSchedule.timezone,
    nextRunAt: runSchedule.nextRunAt,
  };
  proposal.executionPlan = {
    ...(proposal.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {}),
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    frequency: frequencyLabel,
    actionLifecycleStatus: lifecycleStatus,
    manualRunMonth: savedManualRunMonth,
    outputFolder: savedOutputFolder,
    runDate: runSchedule.runDate,
    runTime: runSchedule.runTime,
    timezone: runSchedule.timezone,
    nextRunAt: runSchedule.nextRunAt,
    settings: {
      ...(proposal.executionPlan?.settings && typeof proposal.executionPlan.settings === "object" ? proposal.executionPlan.settings : {}),
      manualOnly,
      runMode: manualOnly ? "manual" : "recurring",
      actionLifecycleStatus: lifecycleStatus,
      manualRunMonth: savedManualRunMonth,
      outputFolder: savedOutputFolder,
      runDate: runSchedule.runDate,
      runTime: runSchedule.runTime,
      scheduleTimezone: runSchedule.timezone,
      nextRunAt: runSchedule.nextRunAt,
    },
  };
  const previousDeliveryChannel = normalizeAgentDeliveryChannel(action.payload?.deliveryChannel || action.channel);
  const nextDeliveryTarget = previousDeliveryChannel === draft.deliveryChannel
    ? String(action.payload?.deliveryTarget || action.recipientRef || "").trim()
    : getConnectedPlatformAddress(draft.deliveryChannel);
  proposal.executionPlan.deliveryTarget = nextDeliveryTarget;
  proposal.executionPlan.settings.deliveryTarget = nextDeliveryTarget;
  proposal.executionPlan.action = {
    ...(proposal.executionPlan.action && typeof proposal.executionPlan.action === "object" ? proposal.executionPlan.action : {}),
    recipientRef: nextDeliveryTarget || draft.deliveryChannel,
  };
  proposal.updatedAt = new Date().toISOString();
  updateAgentProposalSummaryFromFields(proposal);
  if (proposal.type === "custom") {
    proposal.title = getAgentProposalPurposeTitle(proposal);
  }
  action.payload.manualOnly = manualOnly;
  action.payload.actionLifecycleStatus = lifecycleStatus;
  action.payload.frequency = manualOnly ? "manual only" : frequencyLabel;
  action.payload.title = getAgentProposalLocalActionTitle(proposal);
  action.payload.summary = proposal.summary;
  action.payload.preview = getAgentProposalLocalActionPreview(proposal);
  action.payload.manualRunMonth = savedManualRunMonth;
  action.payload.outputFolder = savedOutputFolder;
  action.payload.runDate = runSchedule.runDate;
  action.payload.runTime = runSchedule.runTime;
  action.payload.runTimezone = runSchedule.timezone;
  action.payload.nextRunAt = runSchedule.nextRunAt;
  action.payload.deliveryChannel = draft.deliveryChannel;
  action.payload.deliveryTarget = nextDeliveryTarget;
  action.payload.deliveryLabel = formatAgentDeliveryTargetDetail(draft.deliveryChannel, nextDeliveryTarget || action.recipientRef);
  action.recipientRef = nextDeliveryTarget || draft.deliveryChannel;
  for (const key of ["calendar", "timeWindow", "mailbox", "mailboxAccount", "inactivityPeriod", "result", "outputFolder"]) {
    if (Object.prototype.hasOwnProperty.call(draft, key)) action.payload[key] = String(draft[key] || "").trim();
  }
  if (savedOutputFolder) {
    action.payload.outputFolder = savedOutputFolder;
  }
  if (action.payload.result !== proposal.fields.result && proposal.fields.result) {
    action.payload.result = proposal.fields.result;
  }
  action.channel = draft.deliveryChannel || action.channel;
  action.status = manualOnly ? "manual_only" : (lifecycleStatus === "paused" ? "paused" : "running");
  if (options.persist !== false) {
    persistClientState();
  }
  return { proposal, manualOnly, frequencyLabel, lifecycleStatus };
}

function scheduleAgentLocalActionAutoSave(action, draft, form, changedField = null, options = {}) {
  const editor = form?._agentLocalActionEditor;
  if (!editor) return;
  if (editor.saveTimer) window.clearTimeout(editor.saveTimer);
  setAgentLocalActionEditorStatus(editor, "Saving changes…", false, true, changedField);
  editor.saveTimer = window.setTimeout(() => {
    editor.saveTimer = null;
    const proposal = getAgentLocalActionProposal(action);
    if (!proposal) {
      setAgentLocalActionSettingsBusy(action, false);
      updateAgentLocalActionDom(action);
      setAgentLocalActionEditorStatus(editor, "Couldn’t save changes.", true);
      return;
    }
    applyAgentLocalActionDraftState(action, draft);
    setAgentLocalActionSettingsBusy(action, false);
    updateAgentLocalActionDom(action);
    setAgentLocalActionEditorStatus(editor, "Saved");
    if (options.renderOnSave) {
      renderAgentActions();
    }
  }, 260);
}

function createAgentLocalActionEditor(action) {
  const proposal = getAgentLocalActionProposal(action);
  if (!proposal || !isAgentProposalLocalAction(action)) return null;

  const savedRunSchedule = getAgentProposalRunSchedule(proposal, false);
  const draft = {
    frequency: getAgentLocalActionFrequencyValue(action, proposal),
    runDate: normalizeAgentActionRunDate(action.payload?.runDate) || savedRunSchedule.runDate,
    runTime: normalizeAgentActionRunTime(action.payload?.runTime || savedRunSchedule.runTime),
    manualRunMonth: getAgentProposalManualRunMonthValue(proposal),
    outputFolder: getAgentProposalFieldValue(proposal, "outputFolder") || action.payload?.outputFolder || "",
    mailboxAccount: getAgentProposalFieldValue(proposal, "mailboxAccount") || action.payload?.mailboxAccount || "",
    deliveryChannel: AGENT_ACTION_DELIVERY_CHANNEL,
  };
  const form = document.createElement("form");
  form.className = "agent-action-editor";
  form.addEventListener("submit", (event) => event.preventDefault());

  const typeFields = {
    "calendar-summary": [
      ["Calendars", "calendar", ""],
      ["Date range", "timeWindow", "e.g. next week"],
    ],
    "email-digest": [["Mailbox", "mailbox", "Gmail or Outlook"]],
    reengagement: [["Quiet period", "inactivityPeriod", "e.g. 30 days"]],
    custom: [["Result", "result", "What should this action produce?", { multiline: true }]],
  };
  let resultControl = null;
  for (const [label, key, placeholder, fieldOptions = {}] of typeFields[proposal.type] || []) {
    draft[key] = getAgentProposalFieldValue(proposal, key);
    if (key === "result") {
      draft[key] = getAgentMonthlyBatchResultText(proposal, draft) || draft[key];
    }
    const editorFieldOptions = { placeholder, ...fieldOptions };
    if (key === "calendar") {
      draft[key] = formatAgentCalendarFieldValue(draft[key]);
      const control = createAgentCalendarTagsField(label, draft[key]);
      control.input.addEventListener("change", () => {
        draft[key] = control.input.value;
        scheduleAgentLocalActionAutoSave(action, draft, form, control.field);
      });
      form.append(control.field);
      continue;
    }
    if (key === "timeWindow") {
      draft[key] = normalizeAgentCalendarSummaryDateRangeValue(draft[key] || "next week");
      const control = createAgentCalendarSummaryDateRangeField(label, draft[key]);
      control.input.addEventListener("change", () => {
        draft[key] = control.input.value;
        scheduleAgentLocalActionAutoSave(action, draft, form, control.field);
      });
      form.append(control.field);
      continue;
    }
    const control = createAgentLocalActionEditorField(label, draft[key], editorFieldOptions);
    control.input.addEventListener(editorFieldOptions.select ? "change" : "input", () => {
      draft[key] = control.input.value;
      if (key === "result") {
        syncOutputFolderField();
      }
      scheduleAgentLocalActionAutoSave(action, draft, form, control.field);
    });
    form.append(control.field);
    if (key === "result") {
      resultControl = control;
    }
    if (fieldOptions.multiline) {
      scheduleAgentActionEditorTextareaResize(control.input);
    }
  }

  const frequency = createAgentLocalActionEditorField(
    "Frequency",
    draft.frequency,
    { select: true, options: getAgentLocalActionFrequencyOptions() },
  );
  frequency.input.addEventListener("change", () => {
    draft.frequency = frequency.input.value;
    if (shouldAllowAgentManualRunMonthChoice(proposal, draft) && !draft.manualRunMonth) {
      draft.manualRunMonth = getAgentProposalManualRunMonthValue(proposal, draft);
    }
    syncRunScheduleFields();
    syncManualRunMonthField();
    refreshMonthlyBatchResultField();
    syncOutputFolderField();
    applyAgentLocalActionDraftState(action, draft, { persist: false });
    setAgentLocalActionSettingsBusy(action, true);
    updateAgentLocalActionDom(action);
    scheduleAgentLocalActionAutoSave(action, draft, form, frequency.field, { renderOnSave: true });
  });
  form.append(frequency.field);

  const runDate = createAgentLocalActionEditorField("Run date", draft.runDate, { inputType: "date" });
  const runTime = createAgentLocalActionEditorField("Run time", draft.runTime, { inputType: "time" });
  const runScheduleRow = document.createElement("div");
  runScheduleRow.className = "agent-action-editor-field-row";
  runScheduleRow.append(runDate.field, runTime.field);
  const runScheduleNote = document.createElement("p");
  runScheduleNote.className = "agent-action-editor-note";
  // A saved date is the client's own choice; only an untouched one keeps
  // following the cadence when the cadence changes.
  let runScheduleTouched = Boolean(normalizeAgentActionRunDate(
    action.payload?.runDate || getAgentProposalFieldValue(proposal, "runDate"),
  ));
  runDate.input.addEventListener("change", () => {
    const chosenRunDate = normalizeAgentActionRunDate(runDate.input.value);
    if (!chosenRunDate) {
      runDate.input.value = draft.runDate;
      return;
    }
    runScheduleTouched = true;
    draft.runDate = chosenRunDate;
    syncRunScheduleFields();
    scheduleAgentLocalActionAutoSave(action, draft, form, runDate.field, { renderOnSave: true });
  });
  runTime.input.addEventListener("change", () => {
    const chosenRunTime = normalizeAgentActionRunTime(runTime.input.value, "");
    if (!chosenRunTime) {
      runTime.input.value = draft.runTime;
      return;
    }
    runScheduleTouched = true;
    draft.runTime = chosenRunTime;
    syncRunScheduleFields();
    scheduleAgentLocalActionAutoSave(action, draft, form, runTime.field, { renderOnSave: true });
  });
  form.append(runScheduleRow, runScheduleNote);

  const manualRunMonth = createAgentLocalActionEditorField(
    "Run month",
    draft.manualRunMonth,
    { select: true, options: getAgentManualRunMonthOptions(draft.manualRunMonth) },
  );
  manualRunMonth.input.addEventListener("change", () => {
    draft.manualRunMonth = parseAgentManualRunMonthValue(manualRunMonth.input.value) || manualRunMonth.input.value;
    refreshMonthlyBatchResultField();
    syncOutputFolderField();
    applyAgentLocalActionDraftState(action, draft, { persist: false });
    setAgentLocalActionSettingsBusy(action, true);
    updateAgentLocalActionDom(action);
    scheduleAgentLocalActionAutoSave(action, draft, form, manualRunMonth.field, { renderOnSave: true });
  });
  form.append(manualRunMonth.field);

  const outputFolder = createAgentLocalActionEditorField(
    "Save folder",
    draft.outputFolder,
    { placeholder: "Receipts/Aug2026/" },
  );
  let outputFolderTouched = Boolean(draft.outputFolder && !isAgentGeneratedReceiptOutputFolder(draft.outputFolder));
  outputFolder.input.addEventListener("input", () => {
    outputFolderTouched = true;
    draft.outputFolder = outputFolder.input.value;
    scheduleAgentLocalActionAutoSave(action, draft, form, outputFolder.field);
  });
  form.append(outputFolder.field);

  const mailboxAccount = createAgentLocalActionEditorField(
    "Read mailbox",
    draft.mailboxAccount,
    { select: true, options: getAgentMailboxAccountOptions(draft.mailboxAccount) },
  );
  mailboxAccount.input.addEventListener("change", () => {
    draft.mailboxAccount = mailboxAccount.input.value;
    scheduleAgentLocalActionAutoSave(action, draft, form, mailboxAccount.field);
  });
  // Only worth showing once there is a choice to make.
  mailboxAccount.field.hidden = getConnectedEmailConnections().length < 2;
  form.append(mailboxAccount.field);

  function syncRunScheduleFields() {
    const showFields = draft.frequency !== "manual";
    runScheduleRow.hidden = !showFields;
    runScheduleNote.hidden = !showFields;
    runDate.input.disabled = !showFields;
    runTime.input.disabled = !showFields;
    if (!showFields) {
      return;
    }
    draft.runTime = normalizeAgentActionRunTime(draft.runTime);
    draft.runDate = runScheduleTouched
      ? (normalizeAgentActionRunDate(draft.runDate) || getAgentActionDefaultRunDate(draft.frequency, draft.runTime))
      : getAgentActionDefaultRunDate(draft.frequency, draft.runTime);
    runDate.input.value = draft.runDate;
    runTime.input.value = draft.runTime;
    const nextRunAt = resolveAgentActionNextRunAt({ ...draft, timezone: getWorkspaceTimeZone() });
    runScheduleNote.textContent = nextRunAt
      ? `Next run ${formatScheduledActionDate(nextRunAt, getWorkspaceTimeZone())}`
      : "Pick the date and hour this action should run.";
  }

  function setManualRunMonthOptions(options, selectedValue) {
    const nextOptions = (Array.isArray(options) ? options : []).filter((option) => option?.value);
    const signature = nextOptions.map((option) => `${option.value}:${option.label}`).join("|");
    if (manualRunMonth.input.dataset.agentMonthOptionsSignature !== signature) {
      manualRunMonth.input.replaceChildren();
      for (const option of nextOptions) {
        const optionElement = document.createElement("option");
        optionElement.value = option.value;
        optionElement.textContent = option.label;
        manualRunMonth.input.append(optionElement);
      }
      manualRunMonth.input.dataset.agentMonthOptionsSignature = signature;
    }
    manualRunMonth.input.value = selectedValue || nextOptions[0]?.value || "";
  }

  function syncManualRunMonthField() {
    const showField = shouldShowAgentManualRunMonthField(proposal, draft);
    const canChooseMonth = shouldAllowAgentManualRunMonthChoice(proposal, draft);
    manualRunMonth.field.hidden = !showField;
    manualRunMonth.input.disabled = !canChooseMonth;
    if (!showField) {
      return;
    }
    if (!canChooseMonth) {
      setManualRunMonthOptions([{ value: "previous-month", label: "Previous month" }], "previous-month");
      return;
    }

    draft.manualRunMonth = parseAgentManualRunMonthValue(draft.manualRunMonth) || getAgentProposalManualRunMonthValue(proposal, draft);
    setManualRunMonthOptions(getAgentManualRunMonthOptions(draft.manualRunMonth), draft.manualRunMonth);
  }

  function syncOutputFolderField() {
    const showField = isAgentProposalReceiptCollector(proposal, draft);
    outputFolder.field.hidden = !showField;
    outputFolder.input.disabled = !showField;
    if (!showField) {
      return;
    }
    if (!outputFolderTouched || isAgentGeneratedReceiptOutputFolder(draft.outputFolder)) {
      draft.outputFolder = getAgentMonthlyBatchOutputFolder(proposal, draft);
      outputFolder.input.value = draft.outputFolder;
    }
  }

  function refreshMonthlyBatchResultField() {
    if (!resultControl) {
      return;
    }
    const nextResult = getAgentMonthlyBatchResultText(proposal, draft);
    if (!nextResult || resultControl.input.value === nextResult) {
      return;
    }
    draft.result = nextResult;
    resultControl.input.value = nextResult;
    scheduleAgentActionEditorTextareaResize(resultControl.input);
  }
  syncRunScheduleFields();
  syncManualRunMonthField();
  refreshMonthlyBatchResultField();
  syncOutputFolderField();

  const status = createAgentActionEditorStatusElement("agent-action-editor-status", "p");
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  form.append(status);
  form._agentLocalActionEditor = { draft, status, frequencySelect: frequency.input, saveTimer: null, activeField: null };
  return form;
}

function getSourceActionEditorFrequencyValue(action) {
  const raw = String(action?.payload?.frequency || "daily").toLowerCase();
  if (/5\s*minutes?/.test(raw)) return "minutes:5";
  if (/15\s*minutes?/.test(raw)) return "minutes:15";
  if (/hour/.test(raw)) return "minutes:60";
  if (/week/.test(raw)) return "days:7";
  if (/month/.test(raw)) return "days:30";
  return "days:1";
}

function getSourceActionEditorFrequencyOptions() {
  return [
    { value: "minutes:5", label: "Every 5 minutes", intervalMinutes: 5 },
    { value: "minutes:15", label: "Every 15 minutes", intervalMinutes: 15 },
    { value: "minutes:60", label: "Hourly", intervalMinutes: 60 },
    { value: "days:1", label: "Daily", intervalMinutes: 1440 },
    { value: "days:7", label: "Weekly", intervalMinutes: 10080 },
    { value: "days:30", label: "Monthly", intervalMinutes: 43200 },
  ];
}

// The date and hour a source check is next due, read back from the schedule
// the server is holding so the fields open on the real answer.
function getSourceActionEditorRunSchedule(action) {
  const timezone = getWorkspaceTimeZone();
  const frequency = getSourceActionEditorFrequencyValue(action);
  const parts = getMonitorZonedDateTimeParts(
    String(action?.payload?.nextRunAt || action?.runAt || "").trim(),
    timezone,
  );
  if (!parts) {
    const runTime = AGENT_ACTION_DEFAULT_RUN_TIME;
    return { frequency, timezone, runTime, runDate: getAgentActionDefaultRunDate(frequency, runTime, timezone) };
  }
  return {
    frequency,
    timezone,
    runDate: formatAgentActionRunDate(parts),
    runTime: normalizeAgentActionRunTime(`${parts.hour}:${parts.minute}`),
  };
}

function createSourceActionEditor(action) {
  const sourceActionId = Number(action?.payload?.sourceActionId || 0);
  if (!sourceActionId) return null;
  const form = document.createElement("form");
  form.className = "agent-action-editor";
  form.addEventListener("submit", (event) => event.preventDefault());
  const draft = getSourceActionEditorRunSchedule(action);
  const frequency = createAgentLocalActionEditorField(
    "Frequency",
    draft.frequency,
    { select: true, options: getSourceActionEditorFrequencyOptions() },
  );
  const runDate = createAgentLocalActionEditorField("Run date", draft.runDate, { inputType: "date" });
  const runTime = createAgentLocalActionEditorField("Run time", draft.runTime, { inputType: "time" });
  const runScheduleRow = document.createElement("div");
  runScheduleRow.className = "agent-action-editor-field-row";
  runScheduleRow.append(runDate.field, runTime.field);
  const status = createAgentActionEditorStatusElement("agent-action-editor-status", "p");
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  form.append(frequency.field, runScheduleRow, status);
  let saveTimer = null;
  const saveSchedule = (changedField) => {
    if (saveTimer) window.clearTimeout(saveTimer);
    setAgentActionEditorStatusElement(status, "Saving changes…", false, true);
    setAgentActionEditorFieldStatus(changedField, "Saving", false, true);
    setAgentLocalActionSettingsBusy(action, true);
    updateAgentLocalActionDom(action);
    saveTimer = window.setTimeout(async () => {
      const selected = getSourceActionEditorFrequencyOptions().find((option) => option.value === frequency.input.value);
      if (!selected) {
        setAgentActionEditorStatusElement(status, "Choose a frequency.", true);
        setAgentActionEditorFieldStatus(changedField, "Error", true);
        setAgentLocalActionSettingsBusy(action, false);
        updateAgentLocalActionDom(action);
        return;
      }
      const nextRunAt = resolveAgentActionNextRunAt({
        frequency: selected.value,
        runDate: draft.runDate,
        runTime: draft.runTime,
        timezone: draft.timezone,
      });
      try {
        const response = await apiRequest(`/api/source-actions/${encodeURIComponent(String(sourceActionId))}/settings`, {
          method: "POST",
          body: { intervalMinutes: selected.intervalMinutes, nextRunAt },
        });
        setAgentActionEditorStatusElement(status, "Saved");
        setAgentActionEditorFieldStatus(changedField, "Saved");
        clearAgentActionEditorFieldStatusSoon(changedField);
        if (response.action) {
          state.sourceActions = state.sourceActions.map((candidate) => (
            Number(candidate.id || 0) === sourceActionId ? response.action : candidate
          ));
          renderAgentActions();
        }
      } catch (error) {
        setAgentActionEditorStatusElement(status, formatApiErrorMessage(error, "Couldn’t save the source schedule."), true);
        setAgentActionEditorFieldStatus(changedField, "Error", true);
      } finally {
        setAgentLocalActionSettingsBusy(action, false);
        updateAgentLocalActionDom(action);
      }
    }, 260);
  };
  frequency.input.addEventListener("change", () => {
    draft.frequency = frequency.input.value;
    saveSchedule(frequency.field);
  });
  runDate.input.addEventListener("change", () => {
    const chosenRunDate = normalizeAgentActionRunDate(runDate.input.value);
    if (!chosenRunDate) {
      runDate.input.value = draft.runDate;
      return;
    }
    draft.runDate = chosenRunDate;
    saveSchedule(runDate.field);
  });
  runTime.input.addEventListener("change", () => {
    const chosenRunTime = normalizeAgentActionRunTime(runTime.input.value, "");
    if (!chosenRunTime) {
      runTime.input.value = draft.runTime;
      return;
    }
    draft.runTime = chosenRunTime;
    runTime.input.value = chosenRunTime;
    saveSchedule(runTime.field);
  });
  return form;
}

function createScheduledActionDetail(action) {
  const card = document.createElement("div");
  card.className = "agent-action-detail-card";

  const messageText = String(action.payload?.messageText || action.payload?.text || "").trim();
  if (messageText) {
    const message = document.createElement("p");
    message.className = "agent-action-message";
    message.textContent = `“${messageText}”`;
    card.append(message);
  }

  if (isAgentLocalAction(action)) {
    const payload = action.payload && typeof action.payload === "object" ? action.payload : {};
    const isFeatureAction = isAgentFeatureLiveAction(action);
    const isSourceAction = payload.source === "source_action";
    if (isSourceAction) {
      const sourceStatusClass = getScheduledActionStatusClass(action.status, action);
      const sourceDetails = document.createElement("dl");
      sourceDetails.className = "agent-action-detail-grid";
      sourceDetails.append(
        createScheduledActionDetailRow("Source", payload.sourceType === "file" ? (payload.fileName || "Attached file") : (payload.sourceUrl || "URL")),
        createScheduledActionDetailRow("Frequency", payload.frequency || "As configured"),
        createScheduledActionDetailRow(
          sourceStatusClass === "paused" ? "Status" : "Next check",
          sourceStatusClass === "paused"
            ? "Stopped until you start it"
            : formatScheduledActionDate(payload.nextRunAt || action.runAt, action.timezone),
        ),
      );
      if (payload.lastRunAt) {
        sourceDetails.append(createScheduledActionDetailRow("Last check", `${formatScheduledActionDate(payload.lastRunAt, action.timezone)} · ${capitalizeWords(payload.lastRunStatus || "success")}`));
      }
      card.append(sourceDetails);
      const note = document.createElement("p");
      note.className = "agent-action-note";
      note.textContent = sourceStatusClass === "paused"
        ? "This source action is stopped. Start it when you want it to continue checking on its schedule."
        : "This phase checks and records the source. Content interpretation will be added next.";
      card.append(note);
      const editor = createSourceActionEditor(action);
      if (editor) card.append(editor);
      if (action.lastError) {
        const error = document.createElement("div");
        error.className = "agent-action-error";
        const title = document.createElement("strong");
        title.textContent = "Last check failed";
        const message = document.createElement("p");
        message.textContent = action.lastError;
        error.append(title, message);
        card.append(error);
      }
      const sourceControls = createAgentActionDetailActions(action);
      if (sourceControls) card.append(sourceControls);
      return card;
    }
    if (payload.initialRunError) {
      const error = document.createElement("div");
      error.className = "agent-action-error";
      const errorTitle = document.createElement("strong");
      errorTitle.textContent = payload.manualOnly ? "Setup needs attention" : "First check failed";
      const errorMessage = document.createElement("p");
      errorMessage.textContent = String(payload.initialRunError);
      error.append(errorTitle, errorMessage);
      card.append(error);
    } else if (payload.initialRunMessage) {
      const runNote = document.createElement("div");
      runNote.className = "agent-action-note";
      const runTitle = document.createElement("strong");
      runTitle.textContent = payload.manualOnly ? "Ready to run" : "First check";
      const runMessage = document.createElement("p");
      runMessage.textContent = String(payload.initialRunMessage);
      runNote.append(runTitle, runMessage);
      card.append(runNote);
    }

    if (isFeatureAction) {
      const editor = createAgentMonitorEditor(action);
      if (editor) {
        card.append(editor);
      }
    } else if (isAgentProposalLocalAction(action)) {
      const editor = createAgentLocalActionEditor(action);
      if (editor) {
        card.append(editor);
      }
    }

    const localActions = createAgentActionDetailActions(action);
    if (localActions) {
      card.append(localActions);
    }
    return card;
  }

  const details = document.createElement("dl");
  details.className = "agent-action-detail-grid";
  details.append(
    createScheduledActionDetailRow("Scheduled for", formatScheduledActionDate(action.runAt, action.timezone)),
    createScheduledActionDetailRow("Timezone", action.timezone || getWorkspaceTimeZone()),
    createScheduledActionDetailRow("Channel", formatAgentScheduledMessageChannel(action.channel)),
    createScheduledActionDetailRow("Attempts", String(action.attemptCount)),
    createScheduledActionDetailRow("Created", formatScheduledActionDate(action.createdAt, action.timezone)),
  );
  if (action.completedAt) {
    details.append(createScheduledActionDetailRow("Completed", formatScheduledActionDate(action.completedAt, action.timezone)));
  }
  if (action.providerMessageId) {
    details.append(createScheduledActionDetailRow("Provider reference", action.providerMessageId));
  }
  card.append(details);

  if (action.lastError) {
    const error = document.createElement("div");
    error.className = "agent-action-error";
    const errorTitle = document.createElement("strong");
    errorTitle.textContent = "What went wrong";
    const errorMessage = document.createElement("p");
    errorMessage.textContent = action.lastError;
    error.append(errorTitle, errorMessage);
    card.append(error);
  } else {
    const notes = {
      pending: ["Waiting to run", "This action is queued and will run automatically at the scheduled time."],
      running: ["Sending now", "The action has started and is waiting for WhatsApp to respond."],
      paused: ["Stopped", "This action is stopped until you start it."],
      sent: ["Accepted by WhatsApp", "WhatsApp accepted the message. Waiting for a delivery update."],
      delivered: ["Delivered", "WhatsApp confirmed that the message reached the recipient."],
      read: ["Read", "WhatsApp confirmed that the message was opened."],
      cancelled: ["Cancelled", "This action will not run."],
    };
    const noteCopy = notes[action.status];
    if (noteCopy) {
      const note = document.createElement("div");
      note.className = "agent-action-note";
      const noteTitle = document.createElement("strong");
      noteTitle.textContent = noteCopy[0];
      const noteMessage = document.createElement("p");
      noteMessage.textContent = noteCopy[1];
      note.append(noteTitle, noteMessage);
      card.append(note);
    }
  }
  const actionControls = createAgentActionDetailActions(action);
  if (actionControls) {
    card.append(actionControls);
  }
  return card;
}

function markScheduledActionsRefreshSuccess(loadedAt = Date.now()) {
  state.scheduledActionsLoadedAt = loadedAt;
  state.scheduledActionsError = "";
  state.scheduledActionsFailureCount = 0;
  state.scheduledActionsLastError = "";
  state.scheduledActionsLastErrorAt = 0;
}

function markScheduledActionsRefreshFailure(error, options = {}) {
  const message = formatApiErrorMessage(error, "Couldn’t refresh actions.");
  state.scheduledActionsFailureCount = Math.max(0, Number(state.scheduledActionsFailureCount || 0)) + 1;
  state.scheduledActionsLastError = message;
  state.scheduledActionsLastErrorAt = Date.now();
  state.scheduledActionsError = (options.userInitiated || state.scheduledActionsFailureCount >= SCHEDULED_ACTIONS_REFRESH_ERROR_THRESHOLD)
    ? message
    : "";
}

function isInitialRemoteLoadPending(loading, initialLoadPending) {
  return Boolean(loading && initialLoadPending);
}

function isAgentActionsInitialLoading() {
  return Boolean(
    isSignedIn()
    && (
      isInitialRemoteLoadPending(state.featureActivationLoading, state.featureActivationInitialLoadPending)
      || isInitialRemoteLoadPending(state.scheduledActionsLoading, state.scheduledActionsInitialLoadPending)
      || isInitialRemoteLoadPending(state.sourceActionsLoading, state.sourceActionsInitialLoadPending)
    ),
  );
}

function isAgentToolsInitialLoading() {
  return Boolean(
    isSignedIn()
    && (
      isInitialRemoteLoadPending(state.featureActivationLoading, state.featureActivationInitialLoadPending)
      || isInitialRemoteLoadPending(state.platformConnectionsLoading, state.platformConnectionsInitialLoadPending)
    ),
  );
}

function renderAgentActions() {
  if (!elements.agentPendingActionList || !elements.agentCompletedActionList) {
    return;
  }

  const actions = getRenderableAgentActions();
  const activeActions = sortScheduledActionsByCreatedAt(
    actions.filter((action) => isActiveAgentActionStatus(action.status, action)),
  );
  const completed = sortScheduledActionsByCreatedAt(
    actions.filter((action) => !isActiveAgentActionStatus(action.status, action)),
  );
  const initialLoading = isAgentActionsInitialLoading();

  elements.agentPendingActionsCount.textContent = initialLoading ? "…" : String(activeActions.length);
  elements.agentCompletedActionsCount.textContent = initialLoading ? "…" : String(completed.length);
  const historyExpanded = Boolean(state.agentHistoryExpanded);
  elements.agentHistoryToggleButton?.setAttribute("aria-expanded", String(historyExpanded));
  elements.agentHistoryToggleButton?.setAttribute(
    "aria-label",
    historyExpanded ? "Hide action history" : "Show action history",
  );
  if (elements.agentHistorySection) {
    elements.agentHistorySection.classList.toggle("is-expanded", historyExpanded);
  }
  if (elements.agentCompletedActionList) {
    elements.agentCompletedActionList.hidden = !historyExpanded;
  }
  if (initialLoading) {
    renderScheduledActionLoadingList(elements.agentPendingActionList, "Loading actions…");
    renderScheduledActionLoadingList(elements.agentCompletedActionList, "Loading history…");
  } else {
    renderScheduledActionList(elements.agentPendingActionList, activeActions, "No active actions.");
    renderScheduledActionList(elements.agentCompletedActionList, completed, "Action results and errors will appear here.");
  }

  const selectedAction = actions.find((action) => String(action.id) === String(state.selectedScheduledActionId));
  if (state.selectedScheduledActionId && !selectedAction) {
    state.selectedScheduledActionId = "";
  }
  syncScheduledActionSelection();
  // Action details now live inside the selected card. Keep the legacy detail
  // container hidden so older persisted markup cannot create a second panel.
  elements.agentActionDetailView?.classList.add("is-hidden");
  elements.agentActionDetailContent?.replaceChildren();

  const panelOpen = elements.agentToolsPanel?.classList.contains("is-open");
  setAgentToolsOpen(Boolean(panelOpen));
}

async function refreshScheduledActions(options = {}) {
  if (!isSignedIn()) {
    state.scheduledActionsLoading = false;
    state.scheduledActionsInitialLoadPending = false;
    return null;
  }
  if (scheduledActionsRefreshPromise) {
    return scheduledActionsRefreshPromise;
  }

  const requestSessionKey = currentAuthSessionKey();
  state.scheduledActionsLoading = true;
  renderAgentActions();
  scheduledActionsRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/scheduled-actions?limit=100");
      if (requestSessionKey !== currentAuthSessionKey()) {
        return null;
      }
      const previousActions = state.scheduledActions;
      const nextActions = Array.isArray(response.actions)
        ? response.actions.map(normalizeScheduledAction).filter((action) => action.id > 0)
        : [];
      notifyScheduledActionTransitions(previousActions, nextActions);
      state.scheduledActions = nextActions;
      markScheduledActionsRefreshSuccess();
      return state.scheduledActions;
    } catch (error) {
      if (requestSessionKey === currentAuthSessionKey()) {
        markScheduledActionsRefreshFailure(error, options);
      }
      return null;
    } finally {
      if (requestSessionKey === currentAuthSessionKey()) {
        state.scheduledActionsLoading = false;
        state.scheduledActionsInitialLoadPending = false;
        renderAgentActions();
      }
      scheduledActionsRefreshPromise = null;
    }
  })();
  return scheduledActionsRefreshPromise;
}

async function refreshSourceActions() {
  if (!isSignedIn() || sourceActionsRefreshPromise) {
    if (!isSignedIn()) {
      state.sourceActionsLoading = false;
      state.sourceActionsInitialLoadPending = false;
    }
    return null;
  }
  const requestSessionKey = currentAuthSessionKey();
  state.sourceActionsLoading = true;
  sourceActionsRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/source-actions?limit=100");
      if (requestSessionKey !== currentAuthSessionKey()) return null;
      const previousActions = state.sourceActions;
      const nextActions = Array.isArray(response.actions) ? response.actions : [];
      notifySourceActionTransitions(previousActions, nextActions);
      state.sourceActions = nextActions;
      state.sourceActionsLoadedAt = Date.now();
      return state.sourceActions;
    } catch {
      return null;
    } finally {
      if (requestSessionKey === currentAuthSessionKey()) {
        state.sourceActionsLoading = false;
        state.sourceActionsInitialLoadPending = false;
        renderAgentActions();
      }
      sourceActionsRefreshPromise = null;
    }
  })();
  return sourceActionsRefreshPromise;
}

async function refreshWhatsAppApprovals() {
  if (!isSignedIn() || whatsappApprovalsRefreshPromise) {
    return null;
  }

  const requestSessionKey = currentAuthSessionKey();
  whatsappApprovalsRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/approvals?status=pending&delivery=portal");
      if (requestSessionKey !== currentAuthSessionKey()) {
        return null;
      }

      const approvals = Array.isArray(response.approvals) ? response.approvals : [];
      const agent = getAgentWorkspace();
      const knownApprovalIds = new Set(
        agent.messages
          .filter((message) => message.metadata?.kind === "whatsapp-reply-suggestion")
          .map((message) => String(message.metadata?.approvalId || "").trim())
          .filter(Boolean),
      );
      let didAddMessage = false;
      for (const approval of approvals) {
        const approvalId = String(approval?.approval_id || approval?.approvalId || "").trim();
        if (!approvalId || knownApprovalIds.has(approvalId)) {
          continue;
        }
        const senderName = String(approval.sender_name || approval.sender_wa_id || "WhatsApp contact").trim();
        pushAgentMessage("assistant", `A new WhatsApp message arrived from ${senderName}.`, {
          kind: "whatsapp-reply-suggestion",
          approvalId,
          approval,
          excludeFromModel: true,
        });
        knownApprovalIds.add(approvalId);
        didAddMessage = true;
      }
      if (didAddMessage) {
        persistClientState();
        renderAgentMessages();
      }
      return approvals;
    } catch {
      // The chat remains usable when an inbox refresh is temporarily offline;
      // the next poll will retry without interrupting the user's conversation.
      return null;
    } finally {
      whatsappApprovalsRefreshPromise = null;
    }
  })();
  return whatsappApprovalsRefreshPromise;
}

function syncWhatsAppApprovalsPolling() {
  const shouldPoll = Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && document.visibilityState !== "hidden"
    && state.activeTab === "features"
    && !state.selectedFeatureId
  );
  if (!shouldPoll) {
    if (whatsappApprovalsPollTimer !== null) {
      window.clearInterval(whatsappApprovalsPollTimer);
      whatsappApprovalsPollTimer = null;
    }
    return;
  }

  if (!whatsappApprovalsRefreshPromise) {
    void refreshWhatsAppApprovals();
  }
  if (whatsappApprovalsPollTimer === null) {
    whatsappApprovalsPollTimer = window.setInterval(() => {
      void refreshWhatsAppApprovals();
    }, WHATSAPP_APPROVALS_POLL_MS);
  }
}

// The notification feed is polled independently of the Actions view. Unlike the
// scheduled-action poll it is not gated on a tab or a selected feature, because
// a notification about an overnight run has to arrive wherever the owner is.
function syncNotificationsPolling() {
  const shouldPoll = Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && document.visibilityState !== "hidden"
  );
  if (!shouldPoll) {
    if (notificationsPollTimer !== null) {
      window.clearInterval(notificationsPollTimer);
      notificationsPollTimer = null;
    }
    return;
  }
  if (notificationsPollTimer === null) {
    void refreshNotifications();
    notificationsPollTimer = window.setInterval(() => {
      void refreshNotifications();
    }, NOTIFICATIONS_POLL_MS);
  }
}

function syncScheduledActionsPolling() {
  syncNotificationsPolling();
  // The actions panel belongs to the app shell, so it can be open on any tab.
  // Its first load must not wait for the agent workspace to be the visible
  // tab, or the panel sits on "Loading actions…" forever. Only the repeat
  // polling stays tied to the workspace being on screen.
  const canLoad = Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && document.visibilityState !== "hidden"
  );
  const shouldPoll = Boolean(
    canLoad
    && state.activeTab === "features"
    && !state.selectedFeatureId
  );
  if (canLoad) {
    if (!state.scheduledActionsLoadedAt && !scheduledActionsRefreshPromise) {
      void refreshScheduledActions();
    }
    if (!state.sourceActionsLoadedAt && !sourceActionsRefreshPromise) {
      void refreshSourceActions();
    }
  }
  if (!shouldPoll) {
    if (scheduledActionsPollTimer !== null) {
      window.clearInterval(scheduledActionsPollTimer);
      scheduledActionsPollTimer = null;
    }
    syncWhatsAppApprovalsPolling();
    return;
  }

  if (!sourceActionsRefreshPromise) {
    void refreshSourceActions();
  }
  if (scheduledActionsPollTimer === null) {
    scheduledActionsPollTimer = window.setInterval(() => {
      void refreshScheduledActions();
    }, SCHEDULED_ACTIONS_POLL_MS);
  }
  syncWhatsAppApprovalsPolling();
}

function updateAgentWorkspace() {
  if (!elements.agentMessageList) {
    return;
  }

  renderAgentMessages();
  renderAgentActions();
  renderAgentChats();
  renderAgentFolders();
  syncAgentPanelModeControls();
  if (elements.agentComposerInput) {
    elements.agentComposerInput.disabled = agentTurnBusy;
    elements.agentComposerInput.setAttribute("aria-busy", String(agentTurnBusy));
    scheduleAgentComposerInputResize();
  }
  if (elements.agentComposerButton) {
    elements.agentComposerButton.disabled = agentTurnBusy;
  }
}

function applyAgentScheduledMessageRevision(proposal, changes = {}) {
  if (proposal?.type !== "scheduled-message") {
    return false;
  }

  const patch = changes && typeof changes === "object" ? changes : {};
  const details = proposal.details && typeof proposal.details === "object" ? { ...proposal.details } : {};
  const previousTime = String(details.timeLocal || "").trim();
  const previousMessage = String(details.messageText || "").trim();
  const messageWasGenerated = details.messageSource === "generated"
    || isAgentDefaultScheduledMessageText(previousMessage, previousTime);
  const hasChange = (field) => Object.prototype.hasOwnProperty.call(patch, field);

  if (hasChange("channel")) {
    details.channel = normalizeAgentDeliveryChannel(patch.channel);
  }
  if (hasChange("timeLocal")) {
    details.timeLocal = String(patch.timeLocal || "").trim();
  }
  if (hasChange("datePolicy")) {
    details.datePolicy = String(patch.datePolicy || "next_occurrence").trim();
  }
  if (hasChange("messageText")) {
    details.messageText = String(patch.messageText || "").trim();
    details.messageSource = "user";
  } else if (
    hasChange("timeLocal")
    && messageWasGenerated
    && patch.preserveMessageText !== true
  ) {
    details.messageText = getAgentDefaultScheduledMessageText(details.timeLocal);
    details.messageSource = "generated";
  }

  details.timezone = details.timezone
    || normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC")
    || "UTC";
  details.runAt = resolveAgentScheduledRunAt(details);
  proposal.details = details;
  proposal.executionPlan = buildAgentScheduledMessageExecutionPlan(details);

  const channel = normalizeAgentDeliveryChannel(details.channel);
  if (channel === "whatsapp") {
    proposal.relatedFeatureId = WHATSAPP_REPLY_ASSISTANT_FEATURE_ID;
    proposal.setupActionLabel = "Open WhatsApp setup";
    proposal.missingCredential = isFeatureSetupComplete(getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID))
      ? ""
      : "WhatsApp Business API access token";
  } else {
    proposal.relatedFeatureId = "";
    proposal.missingCredential = "";
  }

  const channelLabel = formatAgentScheduledMessageChannel(channel);
  const timeLabel = details.timeLocal ? ` at ${details.timeLocal}` : "";
  proposal.summary = `Schedule a one-shot ${channelLabel} message${timeLabel}.`;
  proposal.revision = Math.max(1, Number(proposal.revision || 1)) + 1;
  proposal.updatedAt = new Date().toISOString();
  proposal.status = "needs-approval";
  proposal.approved = false;
  return true;
}

function getAgentActionIntentText(action, value = "") {
  const normalizedAction = String(action || "").trim();
  if (normalizedAction === "approve-proposal") {
    return "Set it up please";
  }
  if (normalizedAction === "request-change") {
    return "Change something";
  }
  if (normalizedAction === "open-setup") {
    return "Open setup";
  }
  if (normalizedAction === "credential-help") {
    return "Help me get it";
  }
  if (normalizedAction === "show-whatsapp-setup") {
    return "Set up WhatsApp details";
  }
  if (normalizedAction === "open-whatsapp-setup") {
    return "Open WhatsApp setup";
  }
  return String(value || "").trim();
}

function pushAgentActionIntentMessage(action, value = "", proposalId = "") {
  const text = getAgentActionIntentText(action, value);
  if (!text) {
    return null;
  }
  return pushAgentMessage("user", text, {
    kind: "action-intent",
    action,
    proposalId,
  });
}

function handleAgentMessageAction(event) {
  const target = getEventTargetElement(event);
  const button = target?.closest("[data-agent-message-action]");
  if (!button) {
    return false;
  }

  if (button.disabled) {
    return true;
  }

  const action = button.dataset.agentMessageAction || "";
  const proposalId = button.dataset.agentActionProposal || "";
  const proposalRevision = Math.max(0, Number(button.dataset.agentActionRevision || 0));
  const value = button.dataset.agentActionValue || button.textContent || "";
  const messageId = button.dataset.agentActionMessage || "";
  resolveAgentMessageActions(messageId, action);
  persistClientState();
  renderAgentMessages();

  if (action === "approve-proposal") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    startAgentProposalApproval(proposalId, proposalRevision);
    return true;
  }

  if (action === "request-change") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    requestAgentProposalChanges(proposalId, proposalRevision);
    return true;
  }

  if (action === "open-setup") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    openAgentProposalSetup(proposalId);
    return true;
  }

  if (action === "credential-help") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    openAgentCredentialHelp(proposalId);
    return true;
  }

  if (action === "show-whatsapp-setup") {
    pushAgentActionIntentMessage(action, value);
    pushAgentWhatsAppSetupCard();
    persistAgentWorkspace("WhatsApp setup details are ready.");
    renderApp({ preserveStatus: true });
    return true;
  }

  if (action === "open-whatsapp-setup") {
    pushAgentActionIntentMessage(action, value);
    persistAgentWorkspace("Opening WhatsApp setup...");
    renderApp({ preserveStatus: true });
    openAgentWhatsAppSetup();
    return true;
  }

  if (action === "choose") {
    handleAgentUserText(value);
    return true;
  }

  return false;
}

function handleAgentActionReferenceClick(event) {
  const target = getEventTargetElement(event);
  const link = target?.closest("[data-agent-show-action]");
  if (!link) {
    return false;
  }

  event.preventDefault();
  event.stopPropagation();
  const actionId = link.dataset.agentShowAction || "";
  const proposalId = link.dataset.agentActionProposal || "";
  const resolvedActionId = actionId || getAgentProposalResultActionId(proposalId);
  if (showAgentActionInPanel(resolvedActionId)) {
    setStatus("Action highlighted.");
  }
  return true;
}

function startAgentProposalApproval(proposalId, expectedRevision = 0) {
  if (agentTurnBusy) {
    return;
  }

  agentTurnBusy = true;
  agentTurnProgressText = "Setting it up";
  persistAgentWorkspace("Setting it up...");
  renderApp({ preserveStatus: true });

  void approveAgentProposal(proposalId, expectedRevision)
    .catch((error) => {
      const message = formatApiErrorMessage(error, "I couldn’t finish setting that up yet.");
      pushAgentMessage("assistant", message, {
        kind: "result",
        proposalId,
      });
      persistAgentWorkspace(message);
      renderApp({ preserveStatus: true });
    })
    .finally(() => {
      agentTurnBusy = false;
      agentTurnProgressText = "Thinking";
      renderApp({ preserveStatus: true });
    });
}

function pushAgentProposalResult(proposalId, text, kind = "result", options = {}) {
  const message = String(text || "").trim();
  if (!message) {
    return null;
  }
  const showActionLink = Boolean(options.showActionLink);
  const actionId = showActionLink
    ? String(options.actionId || getAgentProposalResultActionId(proposalId)).trim()
    : "";

  return pushAgentMessage("assistant", message, {
    kind,
    ...(proposalId ? { proposalId } : {}),
    ...(showActionLink && actionId ? { showActionLink: true, actionId } : {}),
  });
}

function getAgentRequiredConnectionApprovalMessage(requirement) {
  if (!requirement) {
    return "Connect the required tool before I create this action.";
  }
  if (requirement.id === "google-workspace") {
    return "Before I create this action, connect Google with Gmail or Drive read access so I can find the source items. No API key is needed.";
  }
  return `Before I create this action, connect ${requirement.toolLabel} so I can ${requirement.capability}.`;
}

function pushAgentRequiredConnectionSetupPrompt(proposal, requirement, reply = "") {
  const candidateReply = String(reply || "").trim();
  const message = isAgentConnectionSetupReply(candidateReply)
    ? candidateReply
    : getAgentRequiredConnectionApprovalMessage(requirement);
  return pushAgentMessage("assistant", message, {
    kind: "credential",
    proposalId: proposal?.id || "",
    requiredConnectionId: requirement?.id || "",
    actions: [
      createAgentAction(
        "open-setup",
        requirement?.actionLabel || "Open setup",
        proposal?.id || "",
        "primary",
      ),
    ],
  });
}

function ensureAgentProposalRequiredConnectionReady(proposal) {
  if (!proposal) {
    return false;
  }
  const requirement = syncAgentProposalRequiredConnection(proposal);
  if (!requirement || isAgentProposalRequiredConnectionReady(requirement)) {
    return true;
  }

  proposal.status = "needs-approval";
  proposal.approved = false;
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    approvalPendingAfterConnection: true,
  };
  proposal.updatedAt = new Date().toISOString();
  pushAgentRequiredConnectionSetupPrompt(proposal, requirement);
  const statusMessage = `${requirement.missingCredential} is required before I can create this action.`;
  persistAgentWorkspace(statusMessage);
  openAgentProposalSetup(proposal.id);
  renderApp({ preserveStatus: true });
  return false;
}

function buildAgentTurnActiveProposal(proposal) {
  if (!proposal || proposal.approved || proposal.status === "rejected") {
    return null;
  }
  return {
    id: proposal.id,
    type: proposal.type,
    revision: Math.max(1, Number(proposal.revision || 1)),
    requestText: proposal.requestText,
    summary: proposal.summary,
    details: proposal.details,
    fields: proposal.fields,
    questions: proposal.questions,
    answers: proposal.answers,
  };
}

function isAgentWhatsAppMonitoringRequest(text) {
  const value = String(text || "").trim().toLowerCase();
  return /\b(?:whatsapp|whats\s*app|wa)\b/.test(value)
    && /\b(?:watch|monitor|listen|track|incoming|new\s+messages?)\b/.test(value);
}

function buildAgentWhatsAppSetupMetadata(setup, actionId, actionLabel) {
  return {
    connectionSetup: {
      platformConnected: Boolean(setup?.genericPlatformConnected),
      connectionStatus: String(setup?.connectionStatus || "not_connected"),
      missingFields: Array.isArray(setup?.missingFields)
        ? setup.missingFields.map((field) => ({
          key: String(field?.key || "").trim(),
          label: String(field?.label || "").trim(),
        })).filter((field) => field.key && field.label)
        : [],
    },
    actions: actionId
      ? [createAgentAction(actionId, actionLabel, "whatsapp", "primary")]
      : [],
  };
}

function pushAgentWhatsAppSetupPrompt() {
  const setup = getWhatsAppConnectionSetupState();
  const firstMissing = setup.missingFields?.[0]?.label || "WhatsApp Business connection details";
  const message = setup.genericPlatformConnected
    ? `WhatsApp is connected for general use. To monitor incoming messages, I need your ${firstMissing} first.`
    : `I can set that up. I need your ${firstMissing} first.`;
  return pushAgentMessage("assistant", message, {
    kind: "question",
    ...buildAgentWhatsAppSetupMetadata(setup, "show-whatsapp-setup", "Set up WhatsApp details"),
  });
}

function pushAgentWhatsAppSetupCard() {
  const setup = getWhatsAppConnectionSetupState();
  const message = setup.genericPlatformConnected
    ? "Here’s what is still needed for WhatsApp message monitoring."
    : "Here’s what I need to connect WhatsApp message monitoring.";
  return pushAgentMessage("assistant", message, {
    kind: "connection-setup",
    ...buildAgentWhatsAppSetupMetadata(setup, "open-whatsapp-setup", "Open WhatsApp setup"),
  });
}

function openAgentWhatsAppSetup() {
  const feature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)
    || clientState.features.find((candidate) => isWhatsAppFeature(candidate));
  if (feature) {
    openFeatureStudio(feature.id, "activation");
    return;
  }
  openPlatformConnection("whatsapp");
}

function createAgentProposalFromTurn(requestText, turn = {}) {
  const blueprint = getAgentBlueprintForType(turn.proposalType);
  const proposal = createAgentProposalFromRequest(requestText, blueprint);
  if (proposal.type === "scheduled-message" && turn.changes && typeof turn.changes === "object") {
    applyAgentScheduledMessageRevision(proposal, turn.changes);
    proposal.revision = 1;
    proposal.createdAt = new Date().toISOString();
    proposal.updatedAt = proposal.createdAt;
  } else {
    applyAgentFieldProposalRevision(proposal, turn.changes, { bumpRevision: false });
  }
  return proposal;
}

function applyAgentTurnProposalRevision(proposal, changes = {}) {
  if (proposal?.type === "scheduled-message") {
    return applyAgentScheduledMessageRevision(proposal, changes);
  }
  if (!proposal || !applyAgentFieldProposalRevision(proposal, changes)) {
    return false;
  }
  return true;
}

const AGENT_ANSWER_RUN_TYPES = new Set(["calendar-summary", "email-digest", "custom"]);

function getAgentAnswerRunFields(turn) {
  const changes = turn?.changes && typeof turn.changes === "object" ? turn.changes : {};
  const fields = changes.fields && typeof changes.fields === "object" ? changes.fields : {};
  return { ...fields };
}

// One question can name several months ("July and August"), but one lookup
// reads one month. Six is more months than anyone asks about in a sentence,
// and it keeps a stray list from turning into a long row of mailbox reads.
const AGENT_ANSWER_RUN_MONTH_LIMIT = 6;
// A month named in free text counts only when it is unmistakably a month:
// "may" is an ordinary word, so it needs its year to be read as May.
const AGENT_ANSWER_TEXT_MONTH_RE = /\b(?:\d{4}-\d{1,2}|may\s+\d{4}|(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:\s+\d{4})?)\b/gi;

function collectAgentAnswerRunMonths(text, months) {
  String(text || "").match(AGENT_ANSWER_TEXT_MONTH_RE)?.forEach((piece) => {
    const month = parseAgentManualRunMonthValue(piece);
    if (month && !months.includes(month)) {
      months.push(month);
    }
  });
  return months;
}

// Every month the question named, oldest first. Asking about two months and
// hearing back about one reads as an unfinished answer, so each month named
// gets its own lookup rather than only the first one parsed.
function getAgentAnswerRunMonths(fields) {
  const raw = String(fields?.manualRunMonth || "").trim();
  const months = collectAgentAnswerRunMonths(raw, []);
  collectAgentAnswerRunMonths(fields?.result, months);
  if (!months.length) {
    return { months: [raw], trimmed: false };
  }
  months.sort();
  return {
    months: months.slice(0, AGENT_ANSWER_RUN_MONTH_LIMIT),
    trimmed: months.length > AGENT_ANSWER_RUN_MONTH_LIMIT,
  };
}

function formatAgentAnswerMonthLabel(value) {
  const match = parseAgentManualRunMonthValue(value).match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return "";
  }
  const date = new Date(Date.UTC(Number.parseInt(match[1], 10), Number.parseInt(match[2], 10) - 1, 1));
  const label = new Intl.DateTimeFormat("en-US", { month: "short", timeZone: "UTC" })
    .format(date)
    .replace(/\./g, "");
  return `${label} ${match[1]}`;
}

// An answer run needs the same connection its saved counterpart would need.
function getAgentAnswerRunBlocker(proposalType) {
  if (proposalType === "calendar-summary") {
    return isCalendarConnectionReady()
      ? ""
      : "I need your calendar connected before I can look that up. Open Calendar setup and connect it with read access.";
  }
  return isEmailConnectionReady()
    ? ""
    : "I need a mailbox connected before I can look that up. Connect Gmail or Outlook with read access, then ask me again.";
}

function getAgentAnswerRunFailureMessage(proposalType) {
  if (proposalType === "calendar-summary") {
    return "I couldn’t read the connected calendar just now. Check Calendar setup and ask me again.";
  }
  return "I couldn’t finish looking that up just now. Check Email setup and ask me again.";
}

// A question gets an answer, not an action. The lookup runs on the spot and
// the result lands in this conversation; nothing is saved and nothing waits
// for approval.
async function runAgentAnswerNow(turn) {
  const proposalType = String(turn?.proposalType || "").trim();
  if (!AGENT_ANSWER_RUN_TYPES.has(proposalType)) {
    return false;
  }

  const reply = String(turn?.reply || "").trim() || "Let me check — this might take a minute.";
  pushAgentMessage("assistant", reply, { kind: "text" });

  const blocker = getAgentAnswerRunBlocker(proposalType);
  if (blocker) {
    pushAgentMessage("assistant", blocker, { kind: "credential" });
    persistAgentWorkspace(blocker);
    renderApp({ preserveStatus: true });
    return true;
  }

  agentTurnProgressText = "Running task";
  persistAgentWorkspace("Running task...");
  renderApp({ preserveStatus: true });

  const fields = getAgentAnswerRunFields(turn);
  const { months, trimmed } = getAgentAnswerRunMonths(fields);
  const lines = [];
  const missedMonths = [];
  let lastError = null;

  try {
    // The months run one after another so each one reports its own total,
    // including the months that turn out to have nothing in them.
    for (const month of months) {
      try {
        const response = await apiRequest("/api/agent/proposals/run", {
          method: "POST",
          body: {
            proposalType,
            mode: "answer",
            fields: month ? { ...fields, manualRunMonth: month } : fields,
            deliveryChannel: "portal",
            timezone: getWorkspaceTimeZone(),
          },
          timeoutMs: 90000,
        });
        const line = String(response.answer || response.message || response.summary || "").trim();
        if (line) {
          lines.push(line);
        }
      } catch (error) {
        lastError = error;
        missedMonths.push(formatAgentAnswerMonthLabel(month) || String(month || "").trim());
      }
    }
    if (!lines.length) {
      if (lastError) {
        throw lastError;
      }
      lines.push("I ran that, but it came back without anything to report.");
    }
    // A month that could not be read is said out loud, so a partial answer
    // never passes for a complete one.
    const missed = missedMonths.filter(Boolean);
    if (missed.length) {
      lines.push(`I couldn’t check ${missed.join(" and ")} just now.`);
    }
    if (trimmed) {
      lines.push(`That was more months than I check at once, so I stopped after ${AGENT_ANSWER_RUN_MONTH_LIMIT}.`);
    }
    const answer = lines.join("\n\n");
    pushAgentMessage("assistant", answer, { kind: "result" });
    persistAgentWorkspace(answer);
  } catch (error) {
    const message = formatApiErrorMessage(error, getAgentAnswerRunFailureMessage(proposalType));
    pushAgentMessage("assistant", message, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(message);
  } finally {
    agentTurnProgressText = "Thinking";
    renderApp({ preserveStatus: true });
  }
  return true;
}

async function applyAgentTurnResponse(turn, userText) {
  const agent = getAgentWorkspace();
  const activeProposal = agent.proposals.find((proposal) => proposal.id === agent.activeProposalId)
    || agent.proposals[agent.proposals.length - 1]
    || null;
  const outcome = String(turn?.outcome || "").trim();
  const reply = String(turn?.reply || "").trim();

  if (activeProposal && !activeProposal.approved && agentWebMonitorTextSuggestsManualOnly(userText)) {
    applyAgentProposalManualMode(activeProposal);
  }
  const currentRevision = Math.max(1, Number(activeProposal?.revision || 1));

  if (activeProposal && switchAgentProposalToCalendarSummary(activeProposal, userText)) {
    applyAgentFieldProposalRevision(activeProposal, turn?.changes, { bumpRevision: false });
    pushAgentProposalNextStep(activeProposal, reply);
    return true;
  }

  if (outcome === "approve_proposal" && activeProposal && !activeProposal.approved) {
    agentTurnProgressText = "Setting it up";
    renderApp({ preserveStatus: true });
    await approveAgentProposal(activeProposal.id, currentRevision);
    return true;
  }

  if (outcome === "approve_proposal") {
    if (reply) {
      pushAgentMessage("assistant", reply, { kind: "text" });
    } else {
      setStatus("Use the latest Set it up button to approve a plan.");
    }
    return true;
  }

  if (outcome === "reject_proposal" && activeProposal && !activeProposal.approved) {
    activeProposal.status = "rejected";
    activeProposal.updatedAt = new Date().toISOString();
    if (reply) {
      pushAgentMessage("assistant", reply, {
        kind: "result",
        proposalId: activeProposal.id,
      });
    }
    return true;
  }

  if (
    outcome === "revise_proposal"
    && activeProposal
    && applyAgentTurnProposalRevision(activeProposal, turn.changes)
  ) {
    pushAgentProposalNextStep(activeProposal, reply);
    return true;
  }

  if (outcome === "answer_now" && await runAgentAnswerNow(turn)) {
    return true;
  }

  if (outcome === "proposal" || (outcome === "question" && turn?.proposalType)) {
    const proposal = createAgentProposalFromTurn(userText, turn);
    agent.proposals.push(proposal);
    agent.activeProposalId = proposal.id;
    pushAgentProposalNextStep(proposal, reply);
    return true;
  }

  if (reply) {
    pushAgentMessage("assistant", reply, buildAgentReplyMetadata(turn, outcome));
  }
  return true;
}

function buildAgentReplyMetadata(turn, outcome) {
  // The agent asks which existing action the user means; the picker answers it
  // so nobody has to retype an action title.
  const choices = turn?.needsActionChoice ? getAgentActionChoices() : [];
  if (choices.length) {
    return {
      kind: "action-choice",
      actionChoices: choices,
      actions: choices.map((choice) => createAgentAction(
        "choose",
        choice.name,
        getAgentActionChoiceValue(choice),
      )),
    };
  }
  return { kind: outcome === "question" ? "question" : "text" };
}

async function handleAgentUserText(text) {
  const cleanText = String(text || "").trim();
  if (!cleanText || agentTurnBusy) {
    return;
  }

  // Never put a likely credential into the transcript or the LLM request.
  // Ask the user to use the dedicated secure connection form instead.
  if (looksLikeCredential(cleanText)) {
    pushAgentMessage("assistant", "Please don’t paste access tokens into chat. Choose the app from Available tools and use its secure connection form instead.", { kind: "credential" });
    persistAgentWorkspace("Use the secure connection form for access tokens.");
    renderApp({ preserveStatus: true });
    return;
  }

  const whatsappSetup = getWhatsAppConnectionSetupState();
  if (isAgentWhatsAppMonitoringRequest(cleanText) && !whatsappSetup.ready) {
    resolvePendingAgentMessageActions("user-message");
    pushAgentMessage("user", cleanText);
    pushAgentWhatsAppSetupPrompt();
    persistAgentWorkspace("WhatsApp setup details are needed.");
    renderApp({ preserveStatus: true });
    elements.agentComposerInput?.focus();
    return;
  }

  const platformConnection = getPlatformConnectionIntentFromText(cleanText);
  if (platformConnection) {
    resolvePendingAgentMessageActions("platform-connection");
    pushAgentMessage("user", cleanText);
    pushAgentMessage("assistant", `Let’s connect ${platformConnection.label}.`);
    persistAgentWorkspace(`Connecting ${platformConnection.label}...`);
    renderApp({ preserveStatus: true });
    openPlatformConnection(platformConnection.id);
    return;
  }

  resolvePendingAgentMessageActions("user-message");
  pushAgentMessage("user", cleanText);
  const agent = getAgentWorkspace();
  const activeProposal = getActiveAgentProposal();
  const conversation = agent.messages.slice(-12).filter((message) => !message.metadata?.excludeFromModel).map((message) => ({
    role: message.role,
    text: message.text,
  }));
  const activeProposalPayload = buildAgentTurnActiveProposal(activeProposal);
  const sourceUrlMatch = cleanText.match(/https?:\/\/[^\s<>)\]}]+/i);
  const sourceContext = agentSourceAttachment?.sourceType === "file"
    ? {
      sourceType: "file",
      fileName: agentSourceAttachment.fileName,
      mimeType: agentSourceAttachment.mimeType,
      size: agentSourceAttachment.size,
    }
    : (
      agentSourceAttachment?.sourceType === "url"
        ? { sourceType: "url", sourceUrl: agentSourceAttachment.sourceUrl }
        : (sourceUrlMatch ? { sourceType: "url", sourceUrl: sourceUrlMatch[0].replace(/[.,!?]+$/, "") } : {})
    );
  agentTurnBusy = true;
  agentTurnProgressText = "Thinking";
  persistAgentWorkspace("Assistyca is thinking...");
  renderApp({ preserveStatus: true });

  try {
    const turn = await apiRequest("/api/agent/turn", {
      method: "POST",
      // Keep this longer than the backend OpenAI gateway timeout so a slow
      // model response becomes a useful 503/502 diagnostic instead of an
      // opaque browser-side AbortError.
      timeoutMs: 90000,
      body: {
        userMessage: cleanText,
        timezone: normalizeMonitorScheduleTimezone(
          clientState?.settings?.timezone || defaultTimeZone(),
          "UTC",
        ) || "UTC",
        conversation,
        activeProposal: activeProposalPayload,
        toolContext: buildAgentToolContext(),
        actionContext: buildAgentActionContext(),
        sourceContext,
      },
    });
    await applyAgentTurnResponse(turn, cleanText);
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    persistAgentWorkspace("Agent updated.");
    renderApp({ preserveStatus: true });
  } catch (error) {
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    const message = formatApiErrorMessage(
      error,
      "I couldn’t get a response right now. Please try again in a moment.",
    );
    // Keep failures in the conversation. A status-only update made the
    // thinking indicator disappear and left the user with no explanation.
    pushAgentMessage("assistant", message, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    elements.agentComposerInput?.focus();
  }
}

function getAgentComposerPixelValue(styles, property) {
  const value = Number.parseFloat(styles?.getPropertyValue(property) || "");
  return Number.isFinite(value) ? value : 0;
}

function getAgentComposerLineHeight(styles) {
  const lineHeight = Number.parseFloat(styles?.lineHeight || "");
  if (Number.isFinite(lineHeight) && lineHeight > 0) {
    return lineHeight;
  }
  const fontSize = Number.parseFloat(styles?.fontSize || "");
  return Number.isFinite(fontSize) && fontSize > 0 ? fontSize * 1.45 : 22;
}

function isAgentComposerCaretAtEnd(input) {
  const textLength = String(input?.value || "").length;
  return input?.selectionStart === textLength && input?.selectionEnd === textLength;
}

function scrollAgentComposerInputToBottom(input) {
  input.scrollTop = input.scrollHeight;
  window.requestAnimationFrame(() => {
    input.scrollTop = input.scrollHeight;
  });
}

function resizeAgentComposerInput(options = {}) {
  const input = elements.agentComposerInput;
  if (!input) {
    return;
  }
  const shouldScrollToBottom = Boolean(options.scrollToBottom);

  const styles = window.getComputedStyle(input);
  const lineHeight = getAgentComposerLineHeight(styles);
  const paddingBlock = getAgentComposerPixelValue(styles, "padding-top")
    + getAgentComposerPixelValue(styles, "padding-bottom");
  const borderBlock = Math.max(0, input.offsetHeight - input.clientHeight);
  const singleLineHeight = Math.ceil(lineHeight + paddingBlock + borderBlock);
  const maxHeight = Math.ceil((lineHeight * AGENT_COMPOSER_MAX_LINES) + paddingBlock + borderBlock);

  input.style.height = `${singleLineHeight}px`;
  const measuredHeight = Math.max(input.scrollHeight + borderBlock, singleLineHeight);
  const nextHeight = Math.min(measuredHeight, maxHeight);
  const isMultiline = measuredHeight > singleLineHeight + 1;
  const isScrollable = measuredHeight > maxHeight + 1;

  input.style.height = `${nextHeight}px`;
  input.style.overflowY = isScrollable ? "auto" : "hidden";
  if (isScrollable && shouldScrollToBottom) {
    scrollAgentComposerInputToBottom(input);
  } else if (!isScrollable) {
    input.scrollTop = 0;
  }
  elements.agentComposerForm?.classList.toggle("is-multiline", isMultiline);
  elements.agentComposerForm?.classList.toggle("is-scrollable", isScrollable);
}

function scheduleAgentComposerInputResize() {
  resizeAgentComposerInput();
  window.requestAnimationFrame(() => {
    resizeAgentComposerInput();
  });
}

function handleAgentComposerSubmit(event = null) {
  event?.preventDefault();
  if (agentTurnBusy) {
    return;
  }
  const input = elements.agentComposerInput;
  const text = String(input?.value || "").trim();
  if (!text && !agentSourceAttachment) {
    input?.focus();
    return;
  }

  if (input) {
    input.value = "";
    resizeAgentComposerInput();
  }

  const defaultSourceText = agentSourceAttachment?.sourceType === "url"
    ? "Please check the attached URL on a recurring schedule."
    : "Please check the attached file on a recurring schedule.";
  void handleAgentUserText(text || defaultSourceText);
}

function normalizeAgentComposerPastedText(text) {
  return String(text || "")
    .replace(/\r\n?/g, "\n")
    .replace(/[ \t]*\n+[ \t]*/g, " ")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

function insertAgentComposerText(input, text) {
  const value = String(text || "");
  if (!input || !value) {
    return;
  }

  const start = typeof input.selectionStart === "number" ? input.selectionStart : input.value.length;
  const end = typeof input.selectionEnd === "number" ? input.selectionEnd : start;
  if (typeof input.setRangeText === "function") {
    input.setRangeText(value, start, end, "end");
  } else {
    input.value = `${input.value.slice(0, start)}${value}${input.value.slice(end)}`;
    const caret = start + value.length;
    input.setSelectionRange?.(caret, caret);
  }
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

function handleAgentComposerPaste(event) {
  const pastedText = event.clipboardData?.getData("text") || "";
  const normalizedText = normalizeAgentComposerPastedText(pastedText);
  if (!normalizedText || normalizedText === pastedText) {
    return;
  }

  event.preventDefault();
  insertAgentComposerText(event.currentTarget, normalizedText);
}

function normalizeAgentSourceUrl(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue) {
    return "";
  }
  const candidate = /^[a-z][a-z0-9+.-]*:\/\//i.test(rawValue) ? rawValue : `https://${rawValue}`;
  try {
    const url = new URL(candidate);
    return ["http:", "https:"].includes(url.protocol) ? url.toString() : "";
  } catch {
    return "";
  }
}

function setAgentAttachSourceMenuOpen(open, mode = "options") {
  agentAttachSourceMenuOpen = Boolean(open);
  agentAttachSourceMenuMode = mode === "url" ? "url" : "options";
  if (elements.agentAttachSourceMenu) {
    elements.agentAttachSourceMenu.hidden = !agentAttachSourceMenuOpen;
    elements.agentAttachSourceMenu.dataset.mode = agentAttachSourceMenuMode;
  }
  elements.agentAttachSourceButton?.setAttribute("aria-expanded", String(agentAttachSourceMenuOpen));
  elements.agentAttachSourceButton?.classList.toggle("is-open", agentAttachSourceMenuOpen);
  if (elements.agentAttachSourceOptions) {
    elements.agentAttachSourceOptions.hidden = !agentAttachSourceMenuOpen || agentAttachSourceMenuMode !== "options";
  }
  if (elements.agentSourceUrlForm) {
    elements.agentSourceUrlForm.hidden = !agentAttachSourceMenuOpen || agentAttachSourceMenuMode !== "url";
  }
  if (elements.agentSourceUrlError) {
    elements.agentSourceUrlError.hidden = true;
    elements.agentSourceUrlError.textContent = "";
  }
  if (agentAttachSourceMenuOpen && agentAttachSourceMenuMode === "url") {
    if (elements.agentSourceUrlInput && agentSourceAttachment?.sourceType === "url") {
      elements.agentSourceUrlInput.value = agentSourceAttachment.sourceUrl || "";
    }
    window.requestAnimationFrame(() => elements.agentSourceUrlInput?.focus());
  }
}

function attachAgentSourceUrl() {
  const normalizedUrl = normalizeAgentSourceUrl(elements.agentSourceUrlInput?.value || "");
  if (!normalizedUrl) {
    if (elements.agentSourceUrlError) {
      elements.agentSourceUrlError.textContent = "Paste a valid http or https URL.";
      elements.agentSourceUrlError.hidden = false;
    }
    elements.agentSourceUrlInput?.focus();
    return;
  }
  agentSourceAttachment = {
    sourceType: "url",
    sourceUrl: normalizedUrl,
  };
  if (elements.agentSourceFileInput) {
    elements.agentSourceFileInput.value = "";
  }
  renderAgentSourceAttachment();
  setAgentAttachSourceMenuOpen(false);
  if (elements.agentSourceUrlInput) {
    elements.agentSourceUrlInput.value = "";
  }
  elements.agentComposerInput?.focus();
}

function renderAgentSourceAttachment() {
  const attachment = agentSourceAttachment;
  if (!elements.agentSourceAttachment) {
    return;
  }
  const sourceType = String(attachment?.sourceType || "").trim().toLowerCase();
  elements.agentSourceAttachment.hidden = !attachment;
  elements.agentSourceAttachment.textContent = attachment
    ? (
      sourceType === "file"
        ? `Attached file: ${attachment.fileName} · ${Math.ceil(attachment.size / 1024)} KB`
        : (sourceType === "url" ? `Attached URL: ${attachment.sourceUrl}` : "")
    )
    : "";
  if (elements.agentAttachSourceButton) {
    elements.agentAttachSourceButton.setAttribute("aria-label", attachment ? "Replace attached source" : "Add source");
    elements.agentAttachSourceButton.title = attachment ? "Replace attached source" : "Add source";
  }
}

function clearAgentSourceAttachment() {
  agentSourceAttachment = null;
  if (elements.agentSourceFileInput) {
    elements.agentSourceFileInput.value = "";
  }
  if (elements.agentSourceUrlInput) {
    elements.agentSourceUrlInput.value = "";
  }
  renderAgentSourceAttachment();
}

function handleAgentSourceFileChange(event) {
  const file = event.target?.files?.[0];
  if (!file) {
    return;
  }
  if (file.size > 5 * 1024 * 1024) {
    setStatus("Files must be 5 MB or smaller.");
    clearAgentSourceAttachment();
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    const dataUrl = String(reader.result || "");
    const comma = dataUrl.indexOf(",");
    if (comma < 0) {
      clearAgentSourceAttachment();
      setStatus("That file could not be read.");
      return;
    }
    agentSourceAttachment = {
      sourceType: "file",
      fileName: file.name,
      mimeType: file.type || "application/octet-stream",
      size: file.size,
      dataBase64: dataUrl.slice(comma + 1),
    };
    renderAgentSourceAttachment();
    elements.agentComposerInput?.focus();
  };
  reader.onerror = () => {
    clearAgentSourceAttachment();
    setStatus("That file could not be read.");
  };
  reader.readAsDataURL(file);
}

async function scheduleAgentScheduledMessageProposal(proposal) {
  const details = proposal.details && typeof proposal.details === "object" ? { ...proposal.details } : {};
  details.channel = normalizeAgentDeliveryChannel(details.channel);
  details.timezone = details.timezone || normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC";
  details.runAt = resolveAgentScheduledRunAt(details) || String(details.runAt || "").trim();
  details.messageText = String(details.messageText || "").trim();

  if (details.channel !== "whatsapp") {
    throw new Error("Only WhatsApp scheduled messages are supported right now.");
  }
  if (!details.runAt) {
    throw new Error("I need an exact send time before I can schedule this.");
  }
  if (!details.messageText) {
    throw new Error("I need message text before I can schedule this.");
  }

  proposal.details = details;
  proposal.executionPlan = buildAgentScheduledMessageExecutionPlan(details);
  return apiRequest("/api/scheduled-actions", {
    method: "POST",
    body: {
      actionType: "send_message",
      channel: details.channel,
      recipientRef: details.recipientRef || "owner",
      runAt: details.runAt,
      timezone: details.timezone,
      messageText: details.messageText,
      source: "portal_agent",
      payload: {
        proposalId: proposal.id,
        requestText: proposal.requestText,
        messageText: details.messageText,
      },
    },
  });
}

function buildAgentWebMonitorWatchItem(proposal) {
  const watchQuery = getAgentProposalFieldValue(proposal, "watchQuery") || proposal?.requestText || "";
  const location = getAgentProposalFieldValue(proposal, "location");
  const timeWindow = getAgentProposalFieldValue(proposal, "timeWindow");
  const pieces = [watchQuery];
  if (location) {
    pieces.push(`Location: ${location}`);
  }
  if (timeWindow) {
    pieces.push(`Date range: ${timeWindow}`);
  }
  return pieces
    .map((piece) => String(piece || "").trim())
    .filter(Boolean)
    .join(" · ");
}

function buildAgentWebMonitorSettings(proposal) {
  const requestText = String(proposal?.requestText || "");
  const requestedFrequency = extractAgentFrequencyField(requestText);
  const frequency = requestedFrequency || getAgentProposalFieldValue(proposal, "frequency");
  const interval = buildAgentMonitorIntervalFromFrequency(frequency);
  const requestsManualRuns = /\b(manual(?:ly)?|on[ -]?demand|when i want|when i ask|turn(?:ed)? on manually)\b/i.test(requestText);
  // Agent-created monitors are manual by default; only an explicit cadence in
  // the user's request opts into recurring background checks.
  const manualOnly = requestsManualRuns || !requestedFrequency;
  const deliveryChannel = normalizeAgentDeliveryChannel(getAgentProposalFieldValue(proposal, "deliveryChannel"))
    || normalizeAgentDeliveryChannel(proposal?.requestText || "")
    || DEFAULT_MONITOR_SETTINGS.deliveryChannel;
  const settings = normalizeFeatureMonitorSettings({
    ...DEFAULT_MONITOR_SETTINGS,
    watchItems: [buildAgentWebMonitorWatchItem(proposal)],
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    intervalMinutes: interval.intervalMinutes,
    intervalDays: interval.intervalDays,
    scheduleTimezone: getWorkspaceTimeZone(),
    deliveryChannel,
  });

  if (!settings.watchItems.length) {
    throw new Error("I need a topic to watch before I can activate the web monitor.");
  }
  return settings;
}

function formatAgentWebMonitorFrequency(settings = {}) {
  if (normalizeMonitorManualOnly(settings.manualOnly)) {
    return "manual only";
  }
  const intervalMinutes = normalizeMonitorIntervalMinutes(settings.intervalMinutes);
  if (intervalMinutes) {
    if (intervalMinutes < 60) {
      return `every ${intervalMinutes} minutes`;
    }
    if (intervalMinutes % 60 === 0) {
      const hours = intervalMinutes / 60;
      return hours === 1 ? "hourly" : `every ${hours} hours`;
    }
    return `every ${intervalMinutes} minutes`;
  }

  const intervalDays = normalizeMonitorIntervalDays(settings.intervalDays);
  if (intervalDays === 1) {
    return "daily";
  }
  if (intervalDays % 30 === 0) {
    const months = intervalDays / 30;
    return months === 1 ? "monthly" : `every ${months} months`;
  }
  if (intervalDays % 7 === 0) {
    const weeks = intervalDays / 7;
    return weeks === 1 ? "weekly" : `every ${weeks} weeks`;
  }
  return `every ${intervalDays} days`;
}

async function runAgentWebMonitorInitialCheck() {
  const response = await apiRequest(`/api/features/${encodeURIComponent(MONITOR_FEATURE_ID)}/run`, {
    method: "POST",
    body: {
      runRequestId: createManualMonitorRunRequestId(),
    },
    timeoutMs: 90000,
  });
  const run = response.run || {};
  return {
    response,
    status: String(run.status || "").trim(),
    message: getManualMonitorRunAlertMessage(run, response.message || "First monitor check finished."),
  };
}

async function saveAndActivateAgentWebMonitorProposal(proposal) {
  if (!isSignedIn()) {
    throw new Error("Sign in before activating a web monitor.");
  }

  const feature = getFeatureById(MONITOR_FEATURE_ID);
  if (!feature) {
    throw new Error("Scheduled Web Monitor is not available for this account.");
  }

  const settings = buildAgentWebMonitorSettings(proposal);
  const prompt = feature.prompt && typeof feature.prompt === "object" ? { ...feature.prompt } : {};
  const configResponse = await apiRequest(`/api/features/${encodeURIComponent(MONITOR_FEATURE_ID)}/config`, {
    method: "POST",
    body: {
      prompt,
      settings,
    },
  });
  applyServerFeatureStates([configResponse.feature || {}], { persist: true });
  state.paymentStatus = configResponse.paymentStatus || state.paymentStatus;

  const updatedFeature = getFeatureById(MONITOR_FEATURE_ID) || feature;
  const activationResponse = await apiRequest(`/api/features/${encodeURIComponent(MONITOR_FEATURE_ID)}/activation`, {
    method: "POST",
    body: {
      action: "activate",
      featureName: updatedFeature.name,
      channel: updatedFeature.channel,
    },
  });
  applyServerFeatureStates([activationResponse.feature || {}], { persist: true });
  state.paymentStatus = activationResponse.paymentStatus || state.paymentStatus;

  let initialRun = null;
  let initialRunError = "";
  if (settings.manualOnly) {
    initialRun = {
      status: "manual_only",
      message: "Ready when you are. Use Run now for a fresh top-five summary.",
    };
  } else {
    try {
      initialRun = await runAgentWebMonitorInitialCheck();
    } catch (error) {
      initialRunError = formatApiErrorMessage(error, "The monitor was activated, but the first check could not run yet.");
    }
  }

  proposal.relatedFeatureId = MONITOR_FEATURE_ID;
  proposal.executionPlan = {
    ...proposal.executionPlan,
    backendFeatureId: MONITOR_FEATURE_ID,
    backendStatus: "active",
    settings,
    frequency: formatAgentWebMonitorFrequency(settings),
    initialRunStatus: initialRun?.status || "",
    initialRunMessage: initialRun?.message || "",
    initialRunError,
  };
  const deliveryTarget = getAgentProposalDeliveryTarget(proposal, settings.deliveryChannel);
  proposal.executionPlan.deliveryTarget = deliveryTarget;
  proposal.summary = `Monitor ${settings.watchItems[0]} ${formatAgentWebMonitorFrequency(settings)} and send source-backed alerts ${formatAgentDeliveryTargetSentence(settings.deliveryChannel, deliveryTarget)}.`;
  return {
    configResponse,
    activationResponse,
    initialRun,
    initialRunError,
    settings,
  };
}

function buildAgentWhatsAppReplySettings(proposal, feature) {
  const requestedChannel = getAgentProposalDeliveryChannel(proposal) || "portal";
  const currentSettings = getSelectedFeatureSettings(feature);
  return buildSettingsForSave(feature, {
    ...currentSettings,
    deliveryChannels: [requestedChannel],
  });
}

async function saveAndActivateAgentWhatsAppProposal(proposal) {
  if (!isSignedIn()) {
    throw new Error("Sign in before activating the WhatsApp reply assistant.");
  }

  const feature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID);
  if (!feature) {
    throw new Error("WhatsApp Reply Assistant is not available for this account.");
  }

  const settings = buildAgentWhatsAppReplySettings(proposal, feature);
  const prompt = feature.prompt && typeof feature.prompt === "object" ? { ...feature.prompt } : {};
  const configResponse = await apiRequest(`/api/features/${encodeURIComponent(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)}/config`, {
    method: "POST",
    body: { prompt, settings },
  });
  applyServerFeatureStates([configResponse.feature || {}], { persist: true });
  state.paymentStatus = configResponse.paymentStatus || state.paymentStatus;

  const updatedFeature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID) || feature;
  const activationResponse = await apiRequest(`/api/features/${encodeURIComponent(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)}/activation`, {
    method: "POST",
    body: {
      action: "activate",
      featureName: updatedFeature.name,
      channel: updatedFeature.channel,
    },
  });
  applyServerFeatureStates([activationResponse.feature || {}], { persist: true });
  state.paymentStatus = activationResponse.paymentStatus || state.paymentStatus;
  return { configResponse, activationResponse, settings };
}

function handleAgentWhatsAppActivationError(error, proposal) {
  proposal.status = "needs-approval";
  proposal.updatedAt = new Date().toISOString();
  const payload = error?.payload || {};
  if (payload.feature) {
    applyServerFeatureStates([payload.feature], { persist: true });
  }
  state.paymentStatus = payload.paymentStatus || state.paymentStatus;

  if (payload.error === "payment_required") {
    const checkoutUrl = payload.paymentStatus?.checkoutUrl || payload.checkoutUrl || "";
    const checkoutOpened = openPaymentCheckout(checkoutUrl);
    const message = payload.message || "Add payment details before activating the WhatsApp reply assistant.";
    pushAgentProposalResult(proposal.id, message, "credential");
    persistAgentWorkspace(checkoutOpened ? "Opening checkout..." : "Payment is required before activation.");
    renderApp({ preserveStatus: true });
    return;
  }

  if (payload.error === "setup_required") {
    const message = String(
      payload.message
      || payload.setupStatus?.message
      || "I need the WhatsApp Business connection details before I can start this.",
    ).trim();
    pushAgentProposalResult(proposal.id, message, "credential");
    pushAgentWhatsAppSetupPrompt();
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    return;
  }

  const message = formatApiErrorMessage(error, "I couldn’t activate the WhatsApp reply assistant yet.");
  pushAgentProposalResult(proposal.id, message);
  persistAgentWorkspace(message);
  renderApp({ preserveStatus: true });
}

function handleAgentWebMonitorActivationError(error, proposal) {
  const payload = error?.payload || {};
  proposal.status = "needs-approval";
  proposal.updatedAt = new Date().toISOString();
  if (payload.feature) {
    applyServerFeatureStates([payload.feature], { persist: true });
  }
  state.paymentStatus = payload.paymentStatus || state.paymentStatus;

  if (payload.error === "payment_required") {
    const checkoutUrl = payload.paymentStatus?.checkoutUrl || payload.checkoutUrl || "";
    const checkoutOpened = openPaymentCheckout(checkoutUrl);
    const message = payload.message || "Add payment details before activating this monitor.";
    pushAgentProposalResult(proposal.id, message);
    openFeatureActivationAlert(
      "Payment needed",
      message,
      {
        eyebrow: "Billing required",
        returnFocus: elements.agentComposerInput,
      },
    );
    persistAgentWorkspace(checkoutOpened ? "Opening checkout..." : "Payment is required before activation.");
    renderApp({ preserveStatus: true });
    return;
  }

  if (payload.error === "setup_required") {
    const setupStatus = payload.setupStatus || {};
    const message = String(
      payload.message
      || setupStatus.message
      || "Finish the web monitor setup before activating it.",
    ).trim();
    pushAgentProposalResult(proposal.id, message, "credential");
    openFeatureActivationAlert(
      "Finish setup first",
      message,
      {
        eyebrow: "One thing left",
        returnFocus: elements.agentComposerInput,
      },
    );
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    return;
  }

  const message = formatApiErrorMessage(error, "I couldn’t activate the web monitor yet.");
  pushAgentProposalResult(proposal.id, message);
  openFeatureActivationAlert("Couldn’t activate the monitor", message, {
    eyebrow: "Try again",
    returnFocus: elements.agentComposerInput,
  });
  persistAgentWorkspace(message);
  renderApp({ preserveStatus: true });
}

async function createSourceActionFromProposal(proposal) {
  const details = buildAgentSourceActionDetails(proposal?.requestText || "", proposal);
  if (details.sourceType === "url" && !details.sourceUrl) {
    throw new Error("Tell me which URL to check first.");
  }
  if (details.sourceType === "file" && !agentSourceAttachment?.dataBase64) {
    throw new Error("Please attach the source file again before setting this up.");
  }
  const response = await apiRequest("/api/source-actions", {
    method: "POST",
    body: {
      sourceType: details.sourceType,
      sourceUrl: details.sourceUrl,
      fileName: details.fileName,
      mimeType: details.mimeType,
      fileContentBase64: agentSourceAttachment?.dataBase64 || "",
      intervalMinutes: details.intervalMinutes,
      timezone: details.timezone,
      label: details.sourceType === "file" ? details.fileName : details.sourceUrl,
      source: "portal_agent",
    },
    timeoutMs: 90000,
  });
  const action = response.action || null;
  proposal.executionPlan = {
    ...proposal.executionPlan,
    backendActionId: action?.id || "",
    backendStatus: action?.status || "active",
    source: details,
  };
  proposal.summary = `Check ${details.sourceType === "file" ? details.fileName : details.sourceUrl} ${details.frequency} and record each source snapshot.`;
  clearAgentSourceAttachment();
  await refreshSourceActions();
  return action;
}

async function approveAgentProposal(proposalId, expectedRevision = 0) {
  const agent = getAgentWorkspace();
  const proposal = agent.proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || proposal.approved || proposal.status === "scheduling") {
    return;
  }

  const currentRevision = Math.max(1, Number(proposal.revision || 1));
  if (expectedRevision > 0 && expectedRevision !== currentRevision) {
    persistAgentWorkspace("Latest plan approval required.");
    renderApp({ preserveStatus: true });
    return;
  }

  if (
    proposal.type === "scheduled-message"
    && normalizeAgentDeliveryChannel(proposal.details?.channel) === "whatsapp"
    && isFeatureSetupComplete(getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID))
  ) {
    proposal.missingCredential = "";
    proposal.relatedFeatureId = WHATSAPP_REPLY_ASSISTANT_FEATURE_ID;
  }

  if (proposal.type === "whatsapp-replies" && isWhatsAppConnectionReady()) {
    proposal.missingCredential = "";
    proposal.relatedFeatureId = WHATSAPP_REPLY_ASSISTANT_FEATURE_ID;
  }

  if (!ensureAgentProposalRequiredConnectionReady(proposal)) {
    return;
  }

  if (proposal.type === "scheduled-message" && proposal.missingCredential) {
    const message = `${proposal.missingCredential} setup is required before I can finish this.`;
    pushAgentProposalResult(proposal.id, message, "credential");
    persistAgentWorkspace(message);
    openAgentProposalSetup(proposal.id);
    renderApp({ preserveStatus: true });
    return;
  }

  if (proposal.type === "whatsapp-replies" && proposal.missingCredential) {
    proposal.status = "needs-approval";
    pushAgentWhatsAppSetupPrompt();
    persistAgentWorkspace("WhatsApp setup is required before I can start this.");
    renderApp({ preserveStatus: true });
    return;
  }

  let scheduledAction = null;
  let sourceAction = null;
  let monitorActivation = null;
  let whatsappActivation = null;
  if (proposal.type === "scheduled-message" && !proposal.missingCredential) {
    proposal.status = "scheduling";
    persistAgentWorkspace("Scheduling message...");
    renderApp({ preserveStatus: true });
    try {
      const response = await scheduleAgentScheduledMessageProposal(proposal);
      scheduledAction = response.action || null;
      proposal.executionPlan = {
        ...proposal.executionPlan,
        backendActionId: scheduledAction?.id || "",
        backendStatus: scheduledAction?.status || "",
      };
      if (scheduledAction?.id) {
        const normalizedAction = normalizeScheduledAction(scheduledAction);
        state.scheduledActions = [
          normalizedAction,
          ...state.scheduledActions.filter((action) => action.id !== normalizedAction.id),
        ];
        markScheduledActionsRefreshSuccess();
        renderAgentActions();
      }
    } catch (error) {
      proposal.status = "needs-approval";
      const payload = error?.payload || {};
      let statusMessage = "Scheduling failed.";
      if (payload.error === "missing_whatsapp_connection") {
        proposal.missingCredential = "WhatsApp Business API access token";
        statusMessage = "WhatsApp setup required.";
        openAgentProposalSetup(proposal.id);
      } else {
        statusMessage = formatApiErrorMessage(error, "I could not schedule that message yet.");
      }
      pushAgentProposalResult(proposal.id, statusMessage, payload.error === "missing_whatsapp_connection" ? "credential" : "result");
      persistAgentWorkspace(statusMessage);
      renderApp({ preserveStatus: true });
      return;
    }
  }

  if (proposal.type === "source-action") {
    proposal.status = "creating";
    persistAgentWorkspace("Creating source action...");
    renderApp({ preserveStatus: true });
    try {
      sourceAction = await createSourceActionFromProposal(proposal);
    } catch (error) {
      proposal.status = "needs-approval";
      const message = formatApiErrorMessage(error, "I couldn’t create that source action yet.");
      pushAgentProposalResult(proposal.id, message, "result");
      persistAgentWorkspace(message);
      renderApp({ preserveStatus: true });
      return;
    }
  }

  if (proposal.type === "web-monitor") {
    proposal.status = "activating";
    persistAgentWorkspace("Activating web monitor...");
    renderApp({ preserveStatus: true });
    try {
      monitorActivation = await saveAndActivateAgentWebMonitorProposal(proposal);
    } catch (error) {
      handleAgentWebMonitorActivationError(error, proposal);
      return;
    }
  }

  if (proposal.type === "whatsapp-replies") {
    proposal.status = "activating";
    persistAgentWorkspace("Starting WhatsApp reply assistant...");
    renderApp({ preserveStatus: true });
    try {
      whatsappActivation = await saveAndActivateAgentWhatsAppProposal(proposal);
    } catch (error) {
      handleAgentWhatsAppActivationError(error, proposal);
      return;
    }
  }

  normalizeAgentMonthlyBatchProposalFields(proposal);
  proposal.approved = true;
  proposal.status = "approved";
  proposal.approvedAt = new Date().toISOString();
  for (const helper of proposal.helpers) {
    const existingHelper = agent.helpers.find((candidate) => (
      candidate.sourceProposalId === proposal.id
      && candidate.name.toLowerCase() === helper.name.toLowerCase()
    ));
    if (existingHelper) {
      existingHelper.status = proposal.missingCredential ? "Needs setup" : "Working";
      continue;
    }

    agent.helpers.push(normalizeAgentHelper({
      id: createAgentId("agent-helper"),
      name: helper.name,
      purpose: helper.purpose,
      status: proposal.missingCredential ? "Needs setup" : "Working",
      sourceProposalId: proposal.id,
      createdAt: new Date().toISOString(),
    }));
  }

  if (proposal.missingCredential) {
    const message = `${proposal.missingCredential} setup is required before I can finish this.`;
    pushAgentProposalResult(proposal.id, message, "credential");
    persistAgentWorkspace(message);
    openAgentProposalSetup(proposal.id);
  } else if (proposal.type === "scheduled-message") {
    const message = "Scheduled message created.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
      actionId: scheduledAction?.id || getAgentProposalResultActionId(proposal.id),
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "web-monitor") {
    const runMessage = monitorActivation?.initialRun?.message || "";
    const runError = monitorActivation?.initialRunError || "";
    const message = runMessage || runError || "Web monitor activated.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "whatsapp-replies") {
    const deliveryChannelId = getAgentProposalDeliveryChannel(proposal)
      || whatsappActivation?.settings?.deliveryChannels?.[0]
      || "portal";
    const deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannelId);
    const message = deliveryChannelId === "portal"
      ? "WhatsApp reply assistant is active. New drafts will appear here for review."
      : `WhatsApp reply assistant is active. New drafts will be brought to you by ${deliveryChannel}.`;
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "source-action") {
    const details = proposal.executionPlan?.source || buildAgentSourceActionDetails(proposal.requestText, proposal);
    const sourceLabel = details.sourceType === "file" ? (details.fileName || "the attached file") : (details.sourceUrl || "the URL");
    const message = `Source action is active. I’ll check ${sourceLabel} ${details.frequency || "on its schedule"} and record each run. I’m not interpreting the content yet.`;
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
      actionId: sourceAction?.id ? `source:${sourceAction.id}` : getAgentProposalResultActionId(proposal.id),
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "calendar-summary") {
    const message = "Meeting summary action is active. I’ll use your calendar for the selected date range and deliver the summary through the chosen channel.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  } else {
    const message = "Action created.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  }
  renderApp({ preserveStatus: true });
}

function requestAgentProposalChanges(proposalId, expectedRevision = 0) {
  const agent = getAgentWorkspace();
  const proposal = agent.proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || proposal.approved || proposal.status === "revising") {
    return;
  }

  const currentRevision = Math.max(1, Number(proposal.revision || 1));
  if (expectedRevision > 0 && expectedRevision !== currentRevision) {
    persistAgentWorkspace("That plan has already changed. Review the latest version before editing.");
    renderApp({ preserveStatus: true });
    return;
  }

  agent.activeProposalId = proposal.id;
  persistAgentWorkspace("Tell Assistyca what you want to change.");
  renderApp({ preserveStatus: true });
  elements.agentComposerInput?.focus();
}

function openAgentProposalSetup(proposalId) {
  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === proposalId);
  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    openPlatformConnection(requirement.setupPlatformId || "calendar");
    return;
  }
  if (proposal?.type === "email-digest" && proposal.missingCredential) {
    openPlatformConnection("email");
    return;
  }
  if (proposal?.type === "calendar-summary" && proposal.missingCredential) {
    openPlatformConnection("calendar");
    return;
  }
  if (!proposal?.relatedFeatureId) {
    persistAgentWorkspace("This plan needs a custom setup path.");
    renderApp({ preserveStatus: true });
    elements.agentComposerInput?.focus();
    return;
  }

  const feature = getFeatureById(proposal.relatedFeatureId);
  if (!feature) {
    return;
  }

  const view = isWhatsAppFeature(feature) && !isFeatureSetupComplete(feature)
    ? "activation"
    : getDefaultFeatureStudioView(feature);
  openFeatureStudio(feature.id, view);
}

function openAgentCredentialHelp(proposalId) {
  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === proposalId);
  const credential = proposal?.missingCredential || "API credentials";
  if (elements.agentComposerInput) {
    elements.agentComposerInput.placeholder = `Ask Assistyca about ${credential}`;
  }
  persistAgentWorkspace(`Ask Assistyca about ${credential}.`);
  renderApp({ preserveStatus: true });
  elements.agentComposerInput?.focus();
}

function getAgentProposalIdFromLocalActionId(actionId) {
  return String(actionId || "").replace(/^proposal:/, "").trim();
}

function getAgentFeatureIdFromLocalActionId(actionId) {
  const text = String(actionId || "").trim();
  return text.startsWith("feature:") ? text.replace(/^feature:/, "").trim() : "";
}

async function deactivateAgentBackendFeature(backendFeatureId) {
  const featureId = String(backendFeatureId || "").trim();
  if (!featureId) {
    return null;
  }

  const feature = getFeatureById(featureId);
  if (!feature || !isFeatureActivated(feature)) {
    return null;
  }

  const response = await apiRequest(`/api/features/${encodeURIComponent(featureId)}/activation`, {
    method: "POST",
    body: {
      action: "deactivate",
      featureName: feature.name,
      channel: feature.channel,
    },
  });
  applyServerFeatureStates([response.feature || {}], { persist: true });
  state.paymentStatus = response.paymentStatus || state.paymentStatus;
  return response;
}

async function deactivateAgentProposalBackendFeature(proposal) {
  const backendFeatureId = String(proposal?.executionPlan?.backendFeatureId || "").trim();
  if (!backendFeatureId) {
    return null;
  }

  return deactivateAgentBackendFeature(backendFeatureId);
}

async function activateAgentBackendFeature(backendFeatureId) {
  const featureId = String(backendFeatureId || "").trim();
  if (!featureId) {
    return null;
  }

  const feature = getFeatureById(featureId);
  if (!feature || isFeatureActivated(feature)) {
    return null;
  }

  const response = await apiRequest(`/api/features/${encodeURIComponent(featureId)}/activation`, {
    method: "POST",
    body: {
      action: "activate",
      featureName: feature.name,
      channel: feature.channel,
    },
  });
  applyServerFeatureStates([response.feature || {}], { persist: true });
  state.paymentStatus = response.paymentStatus || state.paymentStatus;
  return response;
}

async function saveAgentMonitorLifecycleStatus(backendFeatureId, lifecycleStatus) {
  const featureId = String(backendFeatureId || "").trim();
  const feature = getFeatureById(featureId);
  if (!feature || !isMonitorFeature(feature)) {
    return null;
  }

  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  const currentSettings = getSavedFeatureSettings(feature);
  const nextSettings = buildMonitorSettingsForSave(feature, {
    ...currentSettings,
    actionLifecycleStatus: normalizedStatus,
  });
  if (featureConfigBusy && featureConfigSavePromise) {
    try {
      await featureConfigSavePromise;
    } catch {
      // Continue with the lifecycle update after the previous save settles.
    }
  }

  const savePromise = apiRequest(`/api/features/${encodeURIComponent(featureId)}/config`, {
    method: "POST",
    body: {
      prompt: { ...feature.prompt },
      settings: nextSettings,
    },
  });
  featureConfigBusy = true;
  featureConfigSavePromise = savePromise;
  let response;
  try {
    response = await savePromise;
  } finally {
    featureConfigBusy = false;
    if (featureConfigSavePromise === savePromise) {
      featureConfigSavePromise = null;
    }
  }
  applyServerFeatureStates([response.feature || {}], { persist: true });
  state.paymentStatus = response.paymentStatus || state.paymentStatus;
  return response;
}

function setLocalActionLifecycleBusy(action, busy = true) {
  const key = getAgentActionLifecycleBusyKey(action);
  if (!key) {
    return;
  }
  if (busy) {
    agentActionLifecycleBusy.add(key);
  } else {
    agentActionLifecycleBusy.delete(key);
  }
}

function syncProposalActionLifecycleToAction(action, lifecycleStatus) {
  const proposal = getAgentLocalActionProposal(action);
  if (!proposal) {
    return;
  }
  setAgentProposalLifecycleStatus(proposal, lifecycleStatus);
  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  if (action?.payload) {
    action.payload.actionLifecycleStatus = normalizedStatus;
    action.payload.backendFeatureActive = normalizedStatus !== "paused";
  }
  if (!normalizeMonitorManualOnly(action?.payload?.manualOnly, false)) {
    action.status = normalizedStatus === "paused" ? "paused" : "running";
  }
  persistClientState();
}

function updateFeatureLocalActionLifecycle(action, lifecycleStatus) {
  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  if (action?.payload) {
    action.payload.actionLifecycleStatus = normalizedStatus;
    action.payload.backendFeatureActive = normalizedStatus !== "paused";
  }
  if (!normalizeMonitorManualOnly(action?.payload?.manualOnly, false)) {
    action.status = normalizedStatus === "paused" ? "paused" : "running";
  }
}

function updateProposalLocalActionLifecycle(action, lifecycleStatus) {
  syncProposalActionLifecycleToAction(action, lifecycleStatus);
}

async function stopAgentLocalAction(actionId) {
  const action = getRenderableAgentActions().find((candidate) => String(candidate?.id || "") === String(actionId || ""));
  if (!action || !canToggleAgentActionLifecycle(action) || isAgentLifecycleActionPaused(action)) {
    return false;
  }
  const backendFeatureId = getAgentActionBackendFeatureId(action);
  setLocalActionLifecycleBusy(action, true);
  persistAgentWorkspace("Stopping action...");
  renderApp({ preserveStatus: true });
  try {
    if (backendFeatureId) {
      await saveAgentMonitorLifecycleStatus(backendFeatureId, "paused");
      await deactivateAgentBackendFeature(backendFeatureId);
      updateFeatureLocalActionLifecycle(action, "paused");
    }
    if (isAgentProposalLocalAction(action)) {
      updateProposalLocalActionLifecycle(action, "paused");
    }
    state.selectedScheduledActionId = String(action.id || "");
    persistAgentWorkspace("Action stopped.");
    renderApp({ preserveStatus: true });
    return true;
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t stop that action."));
    renderApp({ preserveStatus: true });
    return false;
  } finally {
    setLocalActionLifecycleBusy(action, false);
    renderApp({ preserveStatus: true });
  }
}

async function resumeAgentLocalAction(actionId) {
  const action = getRenderableAgentActions().find((candidate) => String(candidate?.id || "") === String(actionId || ""));
  if (!action || !canToggleAgentActionLifecycle(action) || !isAgentLifecycleActionPaused(action)) {
    return false;
  }
  const backendFeatureId = getAgentActionBackendFeatureId(action);
  setLocalActionLifecycleBusy(action, true);
  persistAgentWorkspace("Starting action...");
  renderApp({ preserveStatus: true });
  try {
    if (backendFeatureId) {
      await saveAgentMonitorLifecycleStatus(backendFeatureId, "active");
      await activateAgentBackendFeature(backendFeatureId);
      updateFeatureLocalActionLifecycle(action, "active");
    }
    if (isAgentProposalLocalAction(action)) {
      updateProposalLocalActionLifecycle(action, "active");
    }
    state.selectedScheduledActionId = String(action.id || "");
    persistAgentWorkspace("Action started.");
    renderApp({ preserveStatus: true });
    return true;
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t start that action."));
    renderApp({ preserveStatus: true });
    return false;
  } finally {
    setLocalActionLifecycleBusy(action, false);
    renderApp({ preserveStatus: true });
  }
}

async function removeAgentProposalLocalAction(actionId) {
  const localAction = getRenderableAgentActions()
    .find((action) => String(action?.id || "") === String(actionId || ""));
  const hasBackendFeature = Boolean(String(localAction?.payload?.backendFeatureId || "").trim());
  const featureId = getAgentFeatureIdFromLocalActionId(actionId);
  if (featureId) {
    const feature = getFeatureById(featureId);
    if (!feature) {
      return false;
    }

    persistAgentWorkspace("Removing action...");
    renderApp({ preserveStatus: true });
    try {
      await saveAgentMonitorLifecycleStatus(featureId, "removed");
      await deactivateAgentBackendFeature(featureId);
    } catch (error) {
      persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t remove that action."));
      renderApp({ preserveStatus: true });
      return false;
    }

    state.selectedScheduledActionId = "";
    persistAgentWorkspace("Action removed.");
    renderApp({ preserveStatus: true });
    return true;
  }

  const proposalId = getAgentProposalIdFromLocalActionId(actionId);
  if (!proposalId) {
    return false;
  }

  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || !proposal.approved || proposal.type === "scheduled-message") {
    return false;
  }

  persistAgentWorkspace("Removing action...");
  renderApp({ preserveStatus: true });
  try {
    const backendFeatureId = String(proposal.executionPlan?.backendFeatureId || "").trim();
    if (hasBackendFeature && backendFeatureId) {
      await saveAgentMonitorLifecycleStatus(backendFeatureId, "removed");
    }
    await deactivateAgentProposalBackendFeature(proposal);
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t remove that action."));
    renderApp({ preserveStatus: true });
    return false;
  }

  const agent = getAgentWorkspace();
  agent.proposals = agent.proposals.filter((candidate) => candidate.id !== proposalId);
  agent.helpers = agent.helpers.filter((helper) => helper.sourceProposalId !== proposalId);
  if (agent.activeProposalId === proposalId) {
    agent.activeProposalId = agent.proposals[agent.proposals.length - 1]?.id || "";
  }
  state.selectedScheduledActionId = "";
  persistAgentWorkspace("Action removed.");
  renderApp({ preserveStatus: true });
  return true;
}

async function cancelScheduledAction(actionId) {
  const id = Math.max(0, Number(actionId || 0));
  if (!id) {
    return false;
  }

  persistAgentWorkspace("Cancelling action...");
  renderApp({ preserveStatus: true });

  try {
    const response = await apiRequest(`/api/scheduled-actions/${encodeURIComponent(String(id))}`, {
      method: "DELETE",
    });
    if (response.action) {
      const normalizedAction = normalizeScheduledAction(response.action);
      state.scheduledActions = [
        normalizedAction,
        ...state.scheduledActions.filter((action) => action.id !== normalizedAction.id),
      ];
      state.selectedScheduledActionId = String(normalizedAction.id || "");
    } else {
      state.scheduledActions = state.scheduledActions.filter((action) => action.id !== id);
      state.selectedScheduledActionId = "";
    }
    markScheduledActionsRefreshSuccess();
    persistAgentWorkspace("Action cancelled.");
    renderApp({ preserveStatus: true });
    return true;
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t cancel that action."));
    renderApp({ preserveStatus: true });
    return false;
  }
}

async function runSourceActionNow(actionId) {
  const id = Math.max(0, Number(actionId || 0));
  if (!id) return false;
  setStatus("Checking source…");
  try {
    const response = await apiRequest(`/api/source-actions/${encodeURIComponent(String(id))}/run`, {
      method: "POST",
      timeoutMs: 90000,
    });
    if (response?.action) {
      notifySourceActionTransitions(state.sourceActions, [response.action]);
    } else {
      addAgentNotification({
        title: "Source check complete",
        message: "The source was checked successfully.",
        tone: "success",
        source: "source-action",
        actionId: `source:${id}`,
        dedupeKey: `source:${id}:manual:${Date.now()}`,
      });
    }
    await refreshSourceActions();
    setStatus("Source checked.");
    return true;
  } catch (error) {
    const message = formatApiErrorMessage(error, "Couldn’t check that source.");
    addAgentNotification({
      title: "Source check failed",
      message,
      tone: "error",
      source: "source-action",
      actionId: `source:${id}`,
      dedupeKey: `source:${id}:manual-error:${message}`,
    });
    setStatus(message);
    await refreshSourceActions();
    return false;
  }
}

async function updateSourceActionLifecycle(actionId, lifecycleStatus) {
  const id = Math.max(0, Number(actionId || 0));
  const endpoint = normalizeMonitorActionLifecycleStatus(lifecycleStatus) === "paused" ? "pause" : "resume";
  if (!id) return false;
  const currentAction = getRenderableAgentActions().find((candidate) => getAgentActionSourceActionId(candidate) === String(id));
  if (currentAction) {
    setLocalActionLifecycleBusy(currentAction, true);
    renderAgentActions();
  }
  setStatus(endpoint === "pause" ? "Stopping source action…" : "Starting source action…");
  try {
    const response = await apiRequest(`/api/source-actions/${encodeURIComponent(String(id))}/${endpoint}`, {
      method: "POST",
    });
    await refreshSourceActions();
    if (response.action) {
      state.sourceActions = state.sourceActions.map((candidate) => (
        Number(candidate.id || 0) === id ? response.action : candidate
      ));
    }
    state.selectedScheduledActionId = `source:${id}`;
    renderAgentActions();
    setStatus(endpoint === "pause" ? "Source action stopped." : "Source action started.");
    return true;
  } catch (error) {
    setStatus(formatApiErrorMessage(error, endpoint === "pause" ? "Couldn’t stop that source action." : "Couldn’t start that source action."));
    await refreshSourceActions();
    return false;
  } finally {
    if (currentAction) {
      setLocalActionLifecycleBusy(currentAction, false);
      renderAgentActions();
    }
  }
}

async function runAgentProposalLocalActionNow(actionId) {
  const action = getRenderableAgentActions().find((candidate) => String(candidate.id) === String(actionId || ""));
  const proposal = getAgentLocalActionProposal(action);
  if (!action || !proposal) {
    return false;
  }

  if (!ensureAgentProposalRequiredConnectionReady(proposal)) {
    return true;
  }

  if (proposal.missingCredential) {
    const message = `${proposal.missingCredential} setup is required before this action can run.`;
    pushAgentMessage("assistant", message, { kind: "credential", proposalId: proposal.id });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    openAgentProposalSetup(proposal.id);
    return true;
  }

  const normalizedActionId = String(action.id || "");
  if (localActionRunBusy.has(normalizedActionId)) {
    return false;
  }

  if (proposal.type === "calendar-summary") {
    localActionRunBusy.add(normalizedActionId);
    const runningMessage = "I’m checking your connected calendar and preparing the meeting summary…";
    persistAgentWorkspace(runningMessage);
    renderApp({ preserveStatus: true });
    try {
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalId: proposal.id,
          proposalType: proposal.type,
          fields: { ...getAgentProposalFieldMap(proposal) },
          deliveryChannel: getAgentProposalDeliveryChannel(proposal) || "portal",
          timezone: getWorkspaceTimeZone(),
        },
        timeoutMs: 90000,
      });
      const message = String(response.message || response.summary || "Meeting summary complete.").trim();
      addAgentNotification({
        title: "Meeting summary ready",
        message,
        tone: "success",
        source: "calendar-summary",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        href: getAgentResponseResultHref(response),
        dedupeKey: `proposal:${proposal.id}:run:${response?.runId || response?.completedAt || Date.now()}`,
      });
      persistAgentWorkspace(message);
      return true;
    } catch (error) {
      const message = formatApiErrorMessage(
        error,
        "I couldn’t read the connected calendar. Check Calendar setup and try again.",
      );
      addAgentNotification({
        title: "Meeting summary failed",
        message,
        tone: "error",
        source: "calendar-summary",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:error:${message}`,
      });
      persistAgentWorkspace(message);
      return false;
    } finally {
      localActionRunBusy.delete(normalizedActionId);
      await refreshPlatformConnections({ render: false });
      renderApp({ preserveStatus: true });
    }
  }

  if (proposal.type === "email-digest") {
    localActionRunBusy.add(normalizedActionId);
    const runningMessage = "I’m checking your connected Gmail inbox and preparing the digest…";
    persistAgentWorkspace(runningMessage);
    renderApp({ preserveStatus: true });
    try {
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalId: proposal.id,
          proposalType: proposal.type,
          fields: { ...getAgentProposalFieldMap(proposal) },
          deliveryChannel: getAgentProposalDeliveryChannel(proposal) || "portal",
          timezone: getWorkspaceTimeZone(),
        },
        timeoutMs: 90000,
      });
      const message = String(response.message || response.summary || "Gmail digest complete.").trim();
      addAgentNotification({
        title: "Email digest ready",
        message,
        tone: "success",
        source: "email-digest",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        href: getAgentResponseResultHref(response),
        dedupeKey: `proposal:${proposal.id}:run:${response?.runId || response?.completedAt || Date.now()}`,
      });
      persistAgentWorkspace(message);
      return true;
    } catch (error) {
      const message = formatApiErrorMessage(
        error,
        "I couldn’t read the connected Gmail inbox. Check Email setup and try again.",
      );
      addAgentNotification({
        title: "Email digest failed",
        message,
        tone: "error",
        source: "email-digest",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:error:${message}`,
      });
      persistAgentWorkspace(message);
      return false;
    } finally {
      localActionRunBusy.delete(normalizedActionId);
      await refreshPlatformConnections({ render: false });
      renderApp({ preserveStatus: true });
    }
  }

  if (isAgentProposalCustomGoogleBatchRunner(proposal)) {
    if (!isEmailConnectionReady()) {
      const message = "A connected mailbox is required to run this receipts search. Connect Gmail or Outlook with read access, then try again.";
      addAgentNotification({
        title: "Mailbox setup required",
        message,
        tone: "warning",
        source: "agent-action",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:mailbox-required`,
      });
      persistAgentWorkspace(message);
      openAgentProposalSetup(proposal.id);
      renderApp({ preserveStatus: true });
      return true;
    }

    localActionRunBusy.add(normalizedActionId);
    const requestFields = { ...getAgentProposalFieldMap(proposal) };
    const outputFolder = getAgentMonthlyBatchOutputFolder(proposal, {
      ...requestFields,
      frequency: getAgentLocalActionFrequencyValue(action, proposal),
      outputFolder: requestFields.outputFolder || action.payload?.outputFolder || "",
    });
    if (outputFolder) {
      requestFields.outputFolder = outputFolder;
      proposal.fields = normalizeAgentFieldValues({ ...getAgentProposalFieldMap(proposal), outputFolder });
      action.payload.outputFolder = outputFolder;
      persistClientState();
    }
    const runMonth = getAgentCustomGoogleBatchRunLabel(proposal);
    const runningMessage = `I’m checking your connected Gmail for ${runMonth} receipts…`;
    persistAgentWorkspace(runningMessage);
    renderApp({ preserveStatus: true });
    try {
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalId: proposal.id,
          proposalType: proposal.type,
          fields: requestFields,
          deliveryChannel: getAgentProposalDeliveryChannel(proposal) || "portal",
          timezone: getWorkspaceTimeZone(),
        },
        timeoutMs: 90000,
      });
      const message = String(response.message || response.summary || "Receipt search complete.").trim();
      recordAgentReceiptFolder(response);
      addAgentNotification({
        title: response.artifacts ? "Receipt bundle ready" : "Receipt search ready",
        message,
        tone: "success",
        source: "custom-google-batch",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        href: getAgentResponseResultHref(response),
        hrefLabel: response.hrefLabel || response.href_label || "Open PDF",
        dedupeKey: `proposal:${proposal.id}:run:${response?.runId || response?.completedAt || Date.now()}`,
      });
      persistAgentWorkspace(message);
      return true;
    } catch (error) {
      const message = formatApiErrorMessage(
        error,
        "I couldn’t run that receipts search. Check Gmail setup and try again.",
      );
      addAgentNotification({
        title: "Receipt search failed",
        message,
        tone: "error",
        source: "custom-google-batch",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:error:${message}`,
      });
      persistAgentWorkspace(message);
      return false;
    } finally {
      localActionRunBusy.delete(normalizedActionId);
      await refreshPlatformConnections({ render: false });
      renderApp({ preserveStatus: true });
    }
  }

  const title = getScheduledActionTitle(action);
  const message = proposal.type === "calendar-summary"
    ? "This action does not have a connected runner yet. Nothing was sent."
    : `The manual run button is ready for ${title}, but its execution service is not connected yet. Nothing was sent.`;
  addAgentNotification({
    title: `${title} unavailable`,
    message,
    tone: "warning",
    source: "agent-action",
    actionId: String(action.id || ""),
    proposalId: proposal.id,
    dedupeKey: `proposal:${proposal.id}:unavailable`,
  });
  persistAgentWorkspace(message);
  renderApp({ preserveStatus: true });
  return true;
}

async function removeSourceAction(actionId) {
  const id = Math.max(0, Number(actionId || 0));
  if (!id) return false;
  try {
    await apiRequest(`/api/source-actions/${encodeURIComponent(String(id))}`, {
      method: "DELETE",
    });
    state.sourceActions = state.sourceActions.filter((action) => Number(action.id || 0) !== id);
    state.selectedScheduledActionId = "";
    renderAgentActions();
    setStatus("Source action removed.");
    return true;
  } catch (error) {
    setStatus(formatApiErrorMessage(error, "Couldn’t remove that source action."));
    return false;
  }
}

function handleAgentWorkspaceClick(event) {
  const whatsappApprovalButton = getEventTargetElement(event)?.closest("[data-agent-whatsapp-action]");
  if (whatsappApprovalButton) {
    void handleAgentWhatsAppApprovalAction(whatsappApprovalButton);
    return;
  }

  if (handleAgentActionReferenceClick(event)) {
    return;
  }

  if (handleAgentActionChoiceDetailsClick(event)) {
    return;
  }

  if (handleAgentMessageAction(event)) {
    return;
  }

  const target = getEventTargetElement(event);
  const stopSourceActionButton = target?.closest("[data-agent-stop-source-action]");
  if (stopSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void updateSourceActionLifecycle(stopSourceActionButton.dataset.agentStopSourceAction || "", "paused");
    return;
  }

  const resumeSourceActionButton = target?.closest("[data-agent-resume-source-action]");
  if (resumeSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void updateSourceActionLifecycle(resumeSourceActionButton.dataset.agentResumeSourceAction || "", "active");
    return;
  }

  const stopLocalActionButton = target?.closest("[data-agent-stop-local-action]");
  if (stopLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void stopAgentLocalAction(stopLocalActionButton.dataset.agentStopLocalAction || "");
    return;
  }

  const resumeLocalActionButton = target?.closest("[data-agent-resume-local-action]");
  if (resumeLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void resumeAgentLocalAction(resumeLocalActionButton.dataset.agentResumeLocalAction || "");
    return;
  }

  const removeLocalActionButton = target?.closest("[data-agent-remove-local-action]");
  if (removeLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void removeAgentProposalLocalAction(removeLocalActionButton.dataset.agentRemoveLocalAction || "");
    return;
  }

  const cancelScheduledActionButton = target?.closest("[data-agent-cancel-scheduled-action]");
  if (cancelScheduledActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void cancelScheduledAction(cancelScheduledActionButton.dataset.agentCancelScheduledAction || "");
    return;
  }

  const runMonitorActionButton = target?.closest("[data-agent-run-monitor-action]");
  if (runMonitorActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void runMonitorActionNow(runMonitorActionButton.dataset.agentRunMonitorAction || "");
    return;
  }

  const runSourceActionButton = target?.closest("[data-agent-run-source-action]");
  if (runSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void runSourceActionNow(runSourceActionButton.dataset.agentRunSourceAction || "");
    return;
  }

  const runLocalActionButton = target?.closest("[data-agent-run-local-action]");
  if (runLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void runAgentProposalLocalActionNow(runLocalActionButton.dataset.agentRunLocalAction || "");
    return;
  }

  const removeSourceActionButton = target?.closest("[data-agent-remove-source-action]");
  if (removeSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void removeSourceAction(removeSourceActionButton.dataset.agentRemoveSourceAction || "");
    return;
  }

  const scheduledActionItem = target?.closest("[data-agent-scheduled-action-id]");
  const scheduledActionId = scheduledActionItem?.dataset.agentScheduledActionId || "";
  const isActionControl = target?.closest("button, input, select, textarea, a, summary, details, [contenteditable=\"true\"], [role=\"button\"], [role=\"combobox\"]");
  if (
    scheduledActionItem
    && scheduledActionId
    && state.selectedScheduledActionId === scheduledActionId
    && !isActionControl
  ) {
    event.preventDefault();
    event.stopPropagation();
    selectScheduledAction(scheduledActionId);
    return;
  }

  const scheduledActionTrigger = target?.closest("[data-agent-scheduled-action-trigger]");
  if (scheduledActionTrigger) {
    event.preventDefault();
    event.stopPropagation();
    selectScheduledAction(scheduledActionTrigger.dataset.agentScheduledActionTrigger || "");
    return;
  }

  const addToolButton = target?.closest("[data-agent-add-tool]");
  if (addToolButton) {
    event.preventDefault();
    event.stopPropagation();
    const option = getAgentAddToolOption(addToolButton.dataset.agentAddTool || "");
    if (option) {
      setAgentAddToolMenuOpen(false);
      if (option.platformId) {
        openPlatformConnection(option.platformId);
      } else if (option.prompt) {
        void handleAgentUserText(option.prompt);
      }
    }
    return;
  }

  const platformConnectionButton = target?.closest("[data-agent-platform-connection]");
  if (platformConnectionButton) {
    event.preventDefault();
    event.stopPropagation();
    openPlatformConnection(platformConnectionButton.dataset.agentPlatformConnection || "");
    return;
  }

  const toolButton = target?.closest("[data-agent-tool-feature-id]");
  if (toolButton) {
    event.preventDefault();
    event.stopPropagation();
    openAgentToolDetails(toolButton.dataset.agentToolFeatureId || "");
    return;
  }

  const approveButton = target?.closest("[data-agent-approve-proposal]");
  if (approveButton) {
    const proposalId = approveButton.dataset.agentApproveProposal || "";
    pushAgentActionIntentMessage("approve-proposal", "Set it up", proposalId);
    persistClientState();
    renderAgentMessages();
    startAgentProposalApproval(proposalId);
    return;
  }

  const setupButton = target?.closest("[data-agent-open-setup]");
  if (setupButton) {
    openAgentProposalSetup(setupButton.dataset.agentOpenSetup || "");
    return;
  }

  const changesButton = target?.closest("[data-agent-request-changes]");
  if (changesButton) {
    const proposalId = changesButton.dataset.agentRequestChanges || "";
    pushAgentActionIntentMessage("request-change", "Change something", proposalId);
    persistClientState();
    renderAgentMessages();
    requestAgentProposalChanges(proposalId);
    return;
  }

  const helpButton = target?.closest("[data-agent-credential-help]");
  if (helpButton) {
    openAgentCredentialHelp(helpButton.dataset.agentCredentialHelp || "");
  }
}

function setAgentToolsOpen(open) {
  const isOpen = Boolean(open);
  elements.agentToolsPanel?.classList.toggle("is-open", isOpen);
  elements.agentToolsToggleButton?.setAttribute("aria-expanded", String(isOpen));
  if (elements.agentToolsToggleButton) {
    const upcomingCount = getRenderableAgentActions().filter((action) => isActiveAgentActionStatus(action.status, action)).length;
    const folderCount = getAgentWorkspace().folders.length;
    const closedLabel = state.agentPanelMode === "chats"
      ? "View chats"
      : (state.agentPanelMode === "folders"
        ? (folderCount ? `Folders (${folderCount})` : "View folders")
        : (upcomingCount ? `Actions (${upcomingCount})` : "View actions"));
    elements.agentToolsToggleButton.textContent = isOpen
      ? "Close panel"
      : closedLabel;
  }
}

function createFeatureCard(feature) {
  const card = document.createElement("button");
  card.type = "button";
  card.className = "glass-card feature-card feature-card-button";
  card.setAttribute("aria-label", `Open ${feature.name}`);
  card.addEventListener("click", () => openFeatureStudio(feature.id));

  const status = document.createElement("span");
  status.className = "feature-status feature-card-status";
  applyFeatureActivationBadgeStyle(status, feature);
  status.textContent = getFeatureActivationLabel(feature);

  const head = document.createElement("div");
  head.className = "feature-card-head";

  const titleBlock = document.createElement("div");
  const title = document.createElement("h3");
  title.textContent = feature.name;

  titleBlock.append(title);
  head.append(titleBlock);

  const description = document.createElement("p");
  description.className = "feature-card-copy";
  description.textContent = feature.description || "";

  card.append(status, head, description);
  return card;
}

function getAgentToolLabel(feature) {
  if (isWhatsAppFeature(feature)) {
    return "WhatsApp";
  }
  if (isMonitorFeature(feature)) {
    return "Web monitoring";
  }
  if (isReengagementFeature(feature)) {
    return "Customer follow-up";
  }
  return feature?.name || "Tool";
}

function getAgentToolDetailsView(feature) {
  if (canOpenFeatureWhatsAppDetails(feature)) {
    return "activation";
  }
  return getDefaultFeatureStudioView(feature);
}

function openAgentToolDetails(featureId) {
  const feature = getFeatureById(featureId);
  if (!feature) {
    return;
  }

  state.agentAddToolMenuOpen = false;
  openFeatureStudio(feature.id, getAgentToolDetailsView(feature));
  setStatus(isWhatsAppFeature(feature) ? "WhatsApp details opened." : `${getAgentToolLabel(feature)} details opened.`);
}

function getAgentAddToolOption(id) {
  return AGENT_ADD_TOOL_OPTIONS.find((option) => option.id === id) || null;
}

function setAgentAddToolMenuOpen(open) {
  const nextOpen = Boolean(open);
  if (agentAddToolMenuOpenFrame !== null) {
    window.cancelAnimationFrame(agentAddToolMenuOpenFrame);
    agentAddToolMenuOpenFrame = null;
  }
  if (agentAddToolMenuCloseTimer !== null) {
    window.clearTimeout(agentAddToolMenuCloseTimer);
    agentAddToolMenuCloseTimer = null;
  }
  state.agentAddToolMenuOpen = nextOpen;
  state.agentAddToolMenuClosing = !nextOpen && (
    !elements.agentAddToolMenu?.hidden
    || !elements.agentAddToolBackdrop?.hidden
  );
  renderAgentAddToolMenu();
}

function createSvgElement(tagName, attributes = {}) {
  const element = document.createElementNS("http://www.w3.org/2000/svg", tagName);
  for (const [name, value] of Object.entries(attributes)) {
    element.setAttribute(name, String(value));
  }
  return element;
}

